/* 平成18年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h18.committeeSessions.push(...[{"id":"h18-20060926-5","meetingId":"h18-cm09","date":"2006年9月26日","dateIso":"2006-09-26","committee":"総務委員会","time":"午前１０時０２分～午前１１時０９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"実際に解散をしたときにどうなっていくのか、この辺を教えていただきたいのと、あわせて教えていただきたいというふうに思います。その辺をちょっと教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"具体的にはどういうことかと申し上げますと、先ほどもご説明させていただきましたように、今の工場の直営体制、これを極力委託に切りかえる。今度自治制度委員会のほうでもご報告をするという予定になっておりますけれども、今、それであたるということがまず一応決まっている。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"前提になるのは一部事務組合の存在ですから、会社としてそれがどうなるんですかというのは、もう少しその辺を。実質的に会社として設立をするわけですから、会社そのものはもう当然利益を上げて、利潤を上げていかなければ存在し得ないわけです。","respondent":"日下部企画財政課長","answer":"現に例えば今予定をしております東京ガスがそういう独自のプラントを持って発電事業をやっている。そことの相互の補完の中で十分に対応できる、あるいは資金的に支援をしていくとか、このように受けとめてあります。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"これはちょっと今の問題から離れますけれども、もう１点だけお聞かせ願いたいんですけれども、教育のほうなんですけれども。この補助金を使って、どういうことをやっていくのか、教えていただけますか。","respondent":"日下部企画財政課長","answer":"今、予定されておりますのは、要するに小中一貫教育の実施に向けてのいろいろな諸課題を整理をするということだと思います。それから、あと周辺校との関係でありますとか、ただいま申し上げたような中身が一つの研究テーマとして設定をされているです。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"ですから、その辺での教育そのものに対する論議というのは、もっともっと必要なのではないかというふうに思うわけです。そうしたことを理由として、この第６３号議案については反対をいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"それに２３区、それとも一回議会に諮って審議してからそういうふうに動くべきではないのかなと思うんですが、ちょっとお聞かせ願いたい。出資率は２３区で６０％出資するわけですから、やはり２３区でまた補っていくような形になるのか、その３点だけ説明を求めました。","respondent":"日下部企画財政課長","answer":"こちらのほうでこの間もずっと何回かにわたってこの問題についていろいろ検討して、評議会のほうで一致を見たということで承知をしています。それから何カ年か先にわたっても当然営業の一つの収支の見込みも立てているわけでありますけれども…","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"どういうトラブル、それはどんな事業でもそうだと思うんで、また考えておかなきゃいけないんじゃないかなと思うのが１点。そうじゃないんか尋ねました。","respondent":"日下部企画財政課長","answer":"補正予算の審議を通して、その分担金の追加、分担金の追加というのは、清掃一部事務組合が新会社の設立のために出資をする。この品川区議会の場において予算審議を通してお諮りをしている、そういうものです。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"一応お聞きして納得できましたので、補正予算には賛同します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"区民委員会も厚生委員会も賛成多数ということで、総務委員会で総合的に審査をするということで、第６３、６４、６５号議案は総合的には賛成です。２団地と先ほど説明がありましたけれども、耐震診断経費５７４万円と提示してありますけれども、場所と内容をちょっと教えていただけますか。","respondent":"日下部企画財政課長","answer":"今回の２団地につきましては、先ほどもご説明申し上げましたけれども、これが実は清水台保育園が併設されております。ということで、この２カ所につきまして耐震診断をまず今年度中に実施をする。","id":"exchange-008"},{"speaker":"山路委員","kind":"意見","question":"それで区営住宅もたくさんありますよね。現在でもよく声を聞くんですが、そういう計画というのは今後進んでいくのかどうか、その説明をしていただけますかとの意見を述べました。","respondent":"日下部企画財政課長","answer":"そうすると残りが９団地になります。９団地につきましては平成１９年度以降、計画的に耐震化の取り組みをしていきたい、このように考えているところです。","id":"exchange-009"},{"speaker":"山村委員","kind":"質問","question":"具体的には質問というほどでもないんですけれども、本当に昨日やったテレポートセンターみたいなことがないことを私としては願うばかりです。本当は、自分としては反対したいんですけれども、そういうわけにもいかないので賛成ということで。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"第６３号議案は賛成ですが、１点質問しますが、補正というのは、どうしても組まなくてはいけない予算が出たという意味だと思うんです。１点ちょっと、教育費の新教育システム開発プログラム事業というのは、なぜ今補正を組まなくてはいけないのか尋ねました。","respondent":"日下部企画財政課長","answer":"この２本とも実はそうなんですが、新年度に入って初めてそれが具体的に明らかになって、各自治体とのいろいろな具体的な調整に入る。昨年もそうでしたが、どうしても９月の補正で計上させていただかざるを得ない、そういうような状況です。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"頼もしいと思うんですけれども、毎回補正で組まなくては、ということ自体がおかしいと思うんですね。新年度でちゃんとできたほうが、やっぱり特に教育ですからいいと思うんですけれども、その辺についてはどうか尋ねました。","respondent":"日下部企画財政課長","answer":"東京都もそうですが、その辺の申し入れはしっかりと言って、調整をいたしていきたいと思います。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"その窓口といいますか、都に言っていく、国に言っていくというポジションというのは、それは区長か尋ねました。","respondent":"日下部企画財政課長","answer":"おそらく、これは教育内容そのものにかかわりますので、基本的には教育委員会のほうが窓口になってやりとりをするという形になるんだろうと思います。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"この事業は１本でいいんじゃないのかみたいな気がするんですけれども、その辺ちょっと、どうして二段構えなのかということを教えていただきたい。それとあと、国保の国庫負担率は３８.２％でいいのかということを、そこも確認をさせていただきたい。","respondent":"日下部企画財政課長","answer":"それが単純に考えれば、ある意味ではリスク分散する算定制度ですね、これの対象が３０万以上になった。実は当初予算では先ほどもご説明いたしましたけれども、対象が３０万円以上になりますよということはわかっていました。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"当然これは拠出金があって交付金があってという形ですので、そうすると、実際に財政が不足していく可能性というのは十分出てくるのかなと思うんです。それからあるいは保険料にはね返ってくる、そういう実態が生まれてくるのかなと思うんですけど、ちょっとその辺をもう少し教えていただけますか。","respondent":"日下部企画財政課長","answer":"そういう仕組みも取られますので、一応財政運営の面では心配ない。そのような形になってあります。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう１点お聞きします。そうなると、これは当然、今後厚生労働省が目指していく流れというのを少し教えていただきたいんですけれども。","respondent":"日下部企画財政課長","answer":"そういった意味では、やはりリスクの回避、要するに全体の平準化も含めて広域化という大きな流れがあります。国もそういう方向でいろいろな制度的な検討というのを進めておりますけれども、これは十分注視をしていく必要があるかな、このように考えてあります。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、都道府県についていえば、医療そのものの抑制が進んでいくという悪循環になっていくんではないかというふうに思います。そんなことがありますので、第６４号議案については、反対をいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816536?Template=document&Id=1732#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":21819,"voices":60}},{"id":"h18-20060927-11","meetingId":"h18-cm09","date":"2006年9月27日","dateIso":"2006-09-27","committee":"自治制度特別委員会","time":"午前１０時０３分～午後０時０３分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"林（宏）委員","kind":"質問・要望","question":"中山課長、この資料はもう我々の手元へ届いているわけですし、できればもう少し中身の話が聞けることを一組の方に要望としてもらってほしい。都区財調の方とも関連してくる話ですから、それを知りたいと思うんだけど、資料はありますか。","respondent":"中山資源循環推進課長","answer":"ちょっと冒頭の説明でも簡単に申し上げたんですが、申しわけありませんが、決算の確定数字そのものがきょうお示しできませんでした。この中で説明は割愛させていただきましたけれども、清掃工場の運営にかかる経費が２０９億円、清掃費の説明の方には書いてきております。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"そういうふうに聞けば答えられるんじゃないですか。品川区の財政課長としての感想を聞かせていただきましょう。","respondent":"日下部企画財政課長","answer":"財調基金もあるわけですけれども、どっちみち基金のお金というのは一般会計を通さなくちゃいけませんので、そういう形で全体の調整を図っている。結果的に金額は同じになっておりますけれども…","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"なぜ１,０００億円の決算を生み出さなきゃいけないのかと。それを繰入金で賄って、一組の決算が終われば出てくるでしょうから、またそのときは数字を出していただくようにお願いして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"三上委員","kind":"意見","question":"歳入総額が１,０４１億円何がしで、歳出が９９７億円という。それで両方とも１００％という言い方をしているんだけれども、この違いについてはどう解釈したらいいのとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"これは繰り返しになりますけれども見込額として出しておりまして、それは翌年度へ繰り越される部分で、そういう不用額の処理に使われています。したがって、これはたしか７月の資料になっていますから、見込みをそのまま計上した額です。","id":"exchange-004"},{"speaker":"三上委員","kind":"質問","question":"そうすると、やはり１００％という言い方はおかしいんじゃないかと思うんだ。これが今話してきている品川区であればという話にくるけれども、品川区のやり方というのは普通じゃないというんか尋ねました。","respondent":"中山資源循環推進課長","answer":"あくまでもこれは決算見込みという形でこういうふうに資料を出すこと自体が。歳入見込額の構成比を足し上げた１００％ですので、内訳を１００％に示した積み上げた数字ということです。","id":"exchange-005"},{"speaker":"三上委員","kind":"意見","question":"幾ら見込み額にしたって何にしたって、１００％にはならないという表現にしなければ、通常の見方としてはどうなんだろう。基本的な形で見ちゃったら、やはりどうなんだろうかと思わせるような雰囲気になるんだろうと思いますねとの意見を述べました。","respondent":"日下部企画財政課長","answer":"例えばここでまいりますと約５０億６,０００万円ほど出てまいりますけれども、これは翌年度への繰り越しという取り扱いになってまいります。確定数値の中で具体的なその辺の補足の説明を含めてできるような形になると思いますので、その辺はひとつご了解いただきたいと思います。","id":"exchange-006"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"この財政調整のところで７５億円ほどの赤字にはなったんですけれども、いわゆる基金のところもどのくらいあって、ほかに基金があるのかどうなのか。このそういう財務状況という改革とどういうふうにここには出ていないんですけれども、大まかにわかれば教えていただきたい。","respondent":"中山資源循環推進課長、岩崎環境清掃事業部長","answer":"一部事務組合の基金と申しますのは、ここにあります財政調整基金だけです。手元にありますのは平成１６年度末の決算の確定額ですけれども、約１６３億３,２５６万円、１６３億強というのがこの財政調整基金の残高です。 １６％ぐらい入ってくるわけですけれども、これを値上げしようかということを検討しているわけです。ということで、いろいろと一組としても努力しているというような説明は部長会でも受けているところです。","id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"意見","question":"そうすると、その年度年度のやりくりのところでの穴埋めだとかというところで使うと、そういう性格だということですね。１６３億ほどの残があるということなんですけれども、大体どのくらいが適当だとかという、そういう見通しがあるのかどうなのかとの意見を述べました。","respondent":"中山資源循環推進課長、山路委員長","answer":"昨年度のその見込みですとほぼ同額になっておりますが、昨年度などもかなり繰り出しの方が多くなっております。… ほかにございませんか。もう１枚、新会社の説明資料がありますので、資源循環推進課長お願いします。 清掃制度に関することの２点目として、お示ししながらご説明したいと思います。簡単ですけれども、新会社に関する説明です。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"極めて異常だし、この３区の何か主張がどんな主張だったかというのはある程度、なぜ反対をしたのかというのは伝わっているんでしょうか。わからないんじゃしようがないんですけれども。","respondent":"中山資源循環推進課長","answer":"この３区は早くからいわゆる引き続き審議を継続すべきではないかというふうなご提案があったというふうに伺っております。いわゆる採決を本日やるべきだということで、その継続についての動議については少数で否決された上で採決があったというふうなことを伺っております。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問・要望","question":"利益が上がらなかった場合にはどうするんだという、その財政見通しについて意見書をこれは出して、議会も反対決議をしているんですね。その辺について、何かその情報があればぜひお知らせいただきたいことと、日を追ってちょっと説明してもらえるとありがたいんですけれども。","respondent":"中山資源循環推進課長","answer":"しかし、新聞の中にありましたのは中央区議会は２５日に設立見直しを求める意見書を採択する動きがあったということが書かれております。検討が進められたということで、検討が行われて、評議会と一組議会での報告の中を基本として検討されてきたというふうにとらえております。","id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"３区が反対したように時間をかけてこれはいろんな面から検討すべきだということを言って、ちょっと次の具体的に売電の問題で聞いていいですか。プラスチックを燃やして売電をやるわけですからね、その今の計画では。","respondent":"中山資源循環推進課長","answer":"もともといわゆる変更の過程からしても、清掃工場の熱を有効利用するために民間の力を活用する検討というものがいわゆる経営計画の中でございまして。そういう意味では次元の違う過程で検討されてきているということで申し上げたわけですので…","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"それなら収支見通しの中に廃プラを燃やして電力を効率的にやって、幾ら売上というのはリンクしていないんですか。収支見通しの中に、その中に入っているんじゃないか尋ねました。","respondent":"中山資源循環推進課長","answer":"正直、ここの中にどういうふうに熱量を見込んでいるというのは十分読み取れない部分がございました。確かにある意味、この会社の設立に向けてそのことを検討していくという格好で全部を検討しているわけではないということで申し上げております。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"３といって、３番目に電気小売事業による収益力の強化、収益力の強化をやるためにはどうするかというのが当然出てくるじゃないですか。その点についはどうなんか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"それは、それだけの経営力を身につけていけば、そういう収支もさらによくなるということを一組は言っているわけです。小売できなくても、この一組の新会社は説明を受けていると、風力のようにそんなに不安定なものではないのかなというふうには思っております。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"だからそこはもっと慎重にやって、最後は住民の税金で償うということになるわけですから、極めて不十分なんじゃないかと私は思います。環境問題なんかについてはちょっと決算特別委員会もあるので、そちらでやりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"土井委員","kind":"確認","question":"東京の場合は、休んだり何だりほとんどないですから、工場を整備するとき以外は。質的なものを確保して高く売っていこうと、こういうことだと理解をしているんですが、間違いか尋ねました。","respondent":"中山資源循環推進課長","answer":"結果的に２３区にもそういうものを還元できるように努力していこうという方向ですので、新たな熱利用を開始するこということでない中でのいわゆる効率的なスケールメリットを生かした仕組みとして、たまたまこの会社を活用していこうです。","id":"exchange-015"},{"speaker":"三上委員","kind":"質問・要望","question":"会社をつくるわけですから、人が少なくても何十人なり、会社へ行けば、工場だけでも１２０人ぐらいの人がいると、そういうことになってくるわけです。とかく言われているのは、この会社についてはどういうふうな仕組みで行われようとしているのか、ご存じだったらひとつ教えていただきたい。","respondent":"中山資源循環推進課長","answer":"別途説明資料で示したものにもあったかと思いますが、ある種、清掃工場の豊富な経験が２３区の中で生かされないまま埋もれてしまう可能性があると。新たなものとしてはそういう形での持ちかけをやりつつも…","id":"exchange-016"},{"speaker":"三上委員","kind":"質問","question":"本社組織なんかは事務的な部分はだからこれが２３区の全部、どこかから派遣している形でとるんだと。それとも、そういったいわゆる事務職的な人たちもこの会社の中においては採用という仕組みがとられるのか、そこらあたりはどうなんか尋ねました。","respondent":"中山資源循環推進課長","answer":"今、一部事務組合も既に準備委員会というのを持っておりまして、いわゆる清掃工場の運営の経験のある職員が設立に向けての準備作業に入っております。したがって、例えばここに本社人員での１２名となっておるのですが…","id":"exchange-017"},{"speaker":"三上委員","kind":"質問・要望","question":"一つの事業をやるのに５年、１０年かかるような事業を抱えていながら、これは要望しておきたい。どこかで伝えていっていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"もし違っていれば訂正いただきたいんですが、先ほど土井委員の質問で、都全体ではどんな割合になっているんか尋ねました。","respondent":"中山資源循環推進課長","answer":"８割がそのまま埋め立てられているですけれども、その２割というのはいわゆる大田工場の第２工場で焼却され、スラグ化されております。品川区の不燃ごみもその扱いの中に入っておりまして、東品川清掃工場、それと中継の方から船で運んで…","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、今度の新しい熱リサイクルで、この３３万トンの８割ですか、この部分を今までは埋め立てていたけど燃やそうと。そういうことでいいかどうか。","respondent":"中山資源循環推進課長","answer":"ただし、２３区の方針の中にリサイクルできるものは、できるだけしましょうと。２３区で早い段階で全域、いろいろ各区で考える中で、こういうことです。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"いや、品川は全量燃やしているんですから、関係ありません。だからちょっと、何かさっきので言いますと、今は燃やしているんだから、高く売るのは当然だという議論がされたんで、ちょっと聞かせてもらいました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"三村委員","kind":"質問","question":"工場の委託と同じように随意契約でもう固定にされていくのか。ほかの会社が高く引き取ってくれるんだったら、高く売るという計画はあるのかどうか、その辺について伺いたいと思います。","respondent":"中山資源循環推進課長","answer":"一つは先ほどの説明とも含まれますけれども、ばらばらにしてしまうと、どうしても小さな工場の部分の東京電力への売却単価等が下がってしまう。現段階でも以前ご説明申し上げたと思いますけれども、それらを集約する形でやっていくというふうに考えております。","id":"exchange-022"},{"speaker":"三村委員","kind":"意見","question":"２３区にとっても本当にプラスになることなのか、小売していくというところで、どういうふうに一部事務組合と新会社の方で協議がされたのか。どういう関係性をつくっていくのか、その辺、ちょっともう少し詳しく説明をいただけますかとの意見を述べました。","respondent":"岩崎環境清掃事業部長","answer":"新会社の方としては高く売れるんで、一組から買うときの値段も今までよりは高く買えますというのが一組側から見た場合の新会社のメリットです。設備投資もありますので、そういう中でご質問のことは大体、決まっていくんじゃないのかというふうに思います。","id":"exchange-023"},{"speaker":"三村委員","kind":"質問","question":"その発電量の大きい工場以外の清掃工場の電力もきちんとしたかたちで、一部事務組合の方できちんと高い単価で買うような仕組みに今回の中でもなっているか、その辺についてお伺したいのですけれども。","respondent":"中山資源循環推進課長","answer":"説明の中ではそういう比較で高いものが１キロワットアワー８円ぐらいで高い部分は東京電力に売れているわけですけれども。それによって８円を超える、その他の部分についても言い方によっては高い単価の部分に吸い上げていけるというふうに説明を伺っております。","id":"exchange-024"},{"speaker":"三村委員","kind":"確認","question":"そういうふうな話も伺ったので、その辺のところをぜひ確認したいというふうに思っていたのと、そういうところが見えないんです。実際に２３区それぞれの自治体の職員の方には、新会社の内容というのはどの程度まで詳しく情報が来ているのか、その辺についてお伺いできますか。","respondent":"中山資源循環推進課長","answer":"この中に積算してというのは、申しわけありませんが、そこまでのバックデータを合わせての説明は我々の方も受けてはおりません。ただ、最終的には一部事務組合を通じて区の方にも還元できる仕組みにしていこうということで説明を受けておりますので、これは当然であると。","id":"exchange-025"},{"speaker":"三村委員","kind":"質問","question":"小売業に参入することによって、手数料などが取られると思いますけれども、その辺の小売に係る手数料がどの程度かかるんですか。その赤字になった場合の費用負担の方法や何かはきちんと詰められているのかどうか、その点についてはどうか尋ねました。","respondent":"中山資源循環推進課長","answer":"それは経費の中に逆に小売をすることに伴って入るということは一定、織り込まれております。小売に伴う経費も一定積算しておりますから、当然、その辺は準備組織の方でも見込んでおるものというふうには考えております。","id":"exchange-026"},{"speaker":"三村委員","kind":"質問・要望","question":"まずきちんともととなるデータを入手していただきたいということで、委員会の中でもぜひ情報提供をきちんと一部事務組合の方に資料請求をして、委員会の方に詳しいデータの単価と各工場の状況なんかも盛り込んだ情報提供の方をぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"石田委員","kind":"質問","question":"それからここに「安定期」と書いてあって、４つの工場を委託したころが安定期というふうに読み取れるのか。そこら辺の理解というか、この見方を説明を求めました。","respondent":"中山資源循環推進課長","answer":"資料にもありますようにまだこの段階でも検討中、確定するものと、まだ詰めていく部分があろうかというふうに思います。広がっていっても、逆に言えば本社部分等はそんなに減らしていくものじゃないということで示していいものじゃないかというふうに考えております。","id":"exchange-028"},{"speaker":"石田委員","kind":"質問","question":"工場は随契でいくんだろうけれども、それで工場数が増えていけば、会社自体は安定的になっていくんじゃないの。そこだけちょっと教えて。","respondent":"中山資源循環推進課長","answer":"４工場以上の段階では収支見通しが営業利益が出てくると見ておりますので、これは安定的にやっていけるという見通しを立てているものです。それがこの資料ですと４工場あたりからいわゆる営業利益が運転部門でも出てくるというふうに見通して、このくらいとしています。","id":"exchange-029"},{"speaker":"石田委員","kind":"質問","question":"だけど、それだって決まっているんだ、これだって４つの工場で、次こうなったらどうしようと。ちゃんと別会社の株式会社の社長として私はやるべきだと思うんだけど、そこら辺の話は出なかったのか教えてください、もしそういう話があったら。","respondent":"中山資源循環推進課長","answer":"そこの部分はやはり一部事務組合の方にイニシアチブをとってもらいたいんだという中での割合だということで説明を聞いております。６対４という形になったわけですが、以前にご説明したとおり、今年から始まった新たな委託がようやくプラントメーカーで２工場出たと。","id":"exchange-030"},{"speaker":"石田委員","kind":"質問","question":"だれにこれは責任があるんですかという問いに対して、責任をとれないと、だれという形ではとれないというような回答が来ているわけです。それはどうやってとるんですかと言ったら、向こうの言い分だけれども、とっていくのは実際、こっちの人間だと向こうの言い分です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"沢田委員","kind":"意見","question":"本当に大丈夫なのかというのを専門家を交えて経営分析しなかったら、危なっかしくてしようがないというのが私らの思いです。だから、そのことだけ言っておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"林（宏）委員","kind":"意見","question":"３年目で出てくる６,７００万円の利益のうちの半分ぐらいは払ったっていいと思うんだけれども、そういう体制をつくっていってほしいと思っています。さっきから出てくる赤字になったどうなんだという話じゃなくて、片方で筆頭株主のトップにいながら、感想はとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"契約も含めて先々ということになると、人材確保のご質問もありましたけれども、本当にそのいわゆる民間の会社というふうに実施していくためには。自立した会社にしていくための仕掛け…","id":"exchange-033"},{"speaker":"林（宏）委員","kind":"意見","question":"多分これは毎年１工場ずつ増やしていって、３０人ずつ人を入れていくということになると、これはもうどういう人を確保していくのか。やがては新規採用、そういうことを考えたら、片手間の会社運営では成り立たないということをしっかりと僕は言っていくべきだと思うねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと伺いたいのは、そのうちの３３万トンが不燃ごみで、あと１６万トンがいろんな可燃ごみに混入して入ってきてしまうと。これはどういうふうな、どのぐらい増えるのかというのは試算されているんでしょうか、焼却に回すのは。","respondent":"中山資源循環推進課長","answer":"先ほどもご説明申し上げたとおり、全量化ということではなくて、リサイクルをしたり、発生する一定の出てくる部分ということです。例えば平成２０年度に向けてということでもいろいろ各区努力を始めておるわけですが、具体的な数値はちょっと現段階では示せません。","id":"exchange-035"},{"speaker":"宮崎副委員長","kind":"意見","question":"ちょっと、そうすると、財政条件というのは今もある程度あるのか。ちょっとここの説明をお願いしたいんですとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"それは平成２０年度の分別変更という区長会の方針がありましたので、その減量割合を一定のというところで見ております。今後、これはまた各区の施策方針をまた別次元で積み上げなければいけないので、見込みも立っていないということで申し上げたわけでございまして。","id":"exchange-036"},{"speaker":"宮崎副委員長","kind":"質問","question":"そうすると、量はわからないというふうに言っておるのですけれども、基本的には焼却するのが増えていくということは確実なんですか。日本も京都議定書の批准という、そういう中で大きな包括するＣＯ2排出を削減しようということの中で、そこのところはどうか尋ねました。","respondent":"中山資源循環推進課長","answer":"たしか約１０万トンぐらいこのいわゆる焼却することによるメタンガスの排出量の減量が見込まれる。石油だとか、そういうものの使用が抑制されることを見込むと、一部事務組合の方が東京都の言う資料等をもとにはじいているものです。","id":"exchange-037"},{"speaker":"宮崎副委員長","kind":"意見","question":"ＣＯ2を排出しないということを言っていかないと、そういう大きな環境問題の中で、今度の新会社がどういうふうに位置づけられるのか。それしか私は思えないのですがとの意見を述べました。","respondent":"岩崎環境清掃事業部長","answer":"区民委員会の所管の話に触れられているというふうに思いますけれども、その辺はどのような委員会運営をなさるのか、それをご説明していただいた上でご答弁申し上げようかというふうに思うんですが。","id":"exchange-038"},{"speaker":"宮崎副委員長","kind":"質問","question":"どういうふうな見通しを持ってつくられて、大きな環境問題の中で、どういうふうに位置づけられているのか。ですから、答弁が出てこなきゃしようがないんですけれども、私はそういうシステムの中で事業を考えていかないといけないと思いますよ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/148286?Template=document&Id=5604#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":35108,"voices":85}},{"id":"h18-20060927-16","meetingId":"h18-cm09","date":"2006年9月27日","dateIso":"2006-09-27","committee":"街づくり特別委員会","time":"午後１０時０２分～午後３時４５分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"平成１８年請願第２１号 品川区池田山交番存続に関する請願","agenda":"平成１８年請願第２１号 品川区池田山交番存続に関する請願","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"その後に第２案として出されてきたのが今の課長の説明の範囲なのかなと思いますけれども、この２番目の案というのは決定したものなんでしょうか。そこを確認させていただきたいんですけれども。","respondent":"金子生活安全担当課長","answer":"これは都議会で説明している内容ですので、今のところ、これ以上のものはございません。結論が決定した上で都議会に、まだ出ていないようです。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"それは警視庁で決定したことということなんです。そうすると、品川区としては２つ目の案に対してどういう態度をとられたんか尋ねました。","respondent":"金子生活安全担当課長","answer":"警視庁で新たに施設を設けて運用することで検討しておりますので、それに対して、今のところ区としてはその動きを見て、区としてできることを考えていかなければならないのかなと考えております。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"その出された第２案についても、今の話ですと、第２案をもとにして区として何ができるのか考えていくという立場だということですよね。第２案でもこれはだめだよと言っている他の自治体とは別で、いわゆるこれを受け入れていきますよという立場だということで解釈していいんか尋ねました。","respondent":"金子生活安全担当課長","answer":"はい、そのとおりです。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"全国的に無人交番の中で事件が起きているということもよく報道されていますよね。皆さん記憶にあると思うんですけれども、警視庁が交番を廃止をしますよと言うのを単純に受け入れたのだということで考えていいんか尋ねました。","respondent":"早津区民生活事業部次長","answer":"しかしながら、４カ所の交番については用途変更と申しておりますけれども、これはそもそもの交番というものではなくて用途変更をするということです。こういう中で、区としても一定の警視庁の対応としては進歩が見られたと、こういうふうに考えているものです。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"それでしたら、警察官の持っている職務権限と相談員の方の職務権限の違いを教えてくれますか。","respondent":"金子生活安全担当課長","answer":"交番相談員の職務範囲につきましては、当初よりそれぞれ拡大をしてきております。こういったいわゆる警察官としての権限行使、これを伴う活動への一時的な支援、こういったものです。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"確かに多少は訓練して、もう６０歳になって定年退職をされた方がやるわけですから、警察官ＯＢとしての職務遂行というのは当然変わってきますよね。そこをもう少し明確に違いを示してもらいたい。","respondent":"金子生活安全担当課長","answer":"したがいまして、当然不審者がいれば、自分では職務質問はできないけれども、１１０番もできますし、警察署に通報もできることと思います。根本的に、警察官が交番に在所していては、その肝心な職務質問もできない、外に出て初めて職務質問ができるという考え方だと思うんです。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問・要望","question":"課長自身は品川区の求めに応じて警視庁から派遣をされてきて、品川区役所でその職務を務めておられるわけですから、来ておられるんだと思います。夜になればいなくなるようですけれども、実際に事件が起きたときに、警察官を呼ぶといっても、近くだと五反田の派出所か何かになるんでしょうかね。","respondent":"山田区民生活事業部長","answer":"交番については警視庁の管轄の中で決定をされ、いわゆる今回の第２次案についても警視庁が決定をされて、ご提示をしているです。都議会の中で審議をされて、基本的にこれは区の権限の及ぶものではないというところは押さえた上でご質問いただきたいと思います。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"ただ、実際に区がどういう意見を上げていくかで全く変わっていくんじゃないですか。明らかに最初から安心・安全のまちづくりなんていうのを投げ捨てているような答弁と一緒じゃないか尋ねました。","respondent":"山田区民生活事業部長","answer":"今回について、警視庁から区長に、いわゆる新聞発表をされる前に今回のこの交番機能強化の方向についてご説明がありました。私どもも、それではしばらく全体の警視庁の方針を見せていただきますですので、ご理解いただきたいと思います。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問・要望","question":"どちらも住民は求めているんだと思います。今、警視庁で言えば公安関係というのが数千人の職員を持っているようですから、というものを配置することだってできるわけですし。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"藤原委員","kind":"確認","question":"確認したいんですけれども、まず区の職員ではないですよねということが１点と、警視庁が基本的には決めていくと。警視庁の管轄の議会というのは、改めてどこの議会が管轄をしているんか尋ねました。","respondent":"金子生活安全担当課長","answer":"大崎署の警察職員につきましては、警視庁の職員、都の職員です。それと、議会の関係につきましては、その人員の増員を含めて、本来、東京都議会で決めるべきものだと、そういうものです。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"ということは、品川区の住民の意見というのは、品川区から出ている東京都議会議員もいるわけですよね。その方たちが議会で、それは警察・消防委員会だと思うんですけれども、言っていくのが私たち議会人としてのシステムとしては正当なんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"だから区で特段の配慮は、ここで何かを決めても、配慮ができて、それが生きていくんですかという思いがあるものですから。東京都議会が議決の機関であるわけですから、現実問題、出てくるんか尋ねました。","respondent":"山田区民生活事業部長","answer":"廃止をしないという権限については、これは都が持っておりますので、私どもがいかんともしがたいというところがあります。","id":"exchange-012"},{"speaker":"藤原委員","kind":"確認","question":"最後にもう一回確認しますが、池田山交番の廃止計画を見直しということで、そのままにしてほしいということを品川区が決めても、それは効力がないということですね。","respondent":"山田区民生活事業部長","answer":"そのとおりです。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"質問をしたいんですけれども、改めて池田山のいわゆる警察事象というのは、どういう状況なのかをちょっとお知らせいただきたいんですけれども。泥棒が入る経験もこの間４回ぐらいあったというお話をされていましたし、それがあって、どの程度のことなのかということを改めて伺いたいと思います。","respondent":"金子生活安全担当課長","answer":"平成１７年につきましては、いわゆる刑法犯の認知件数については二十数件、約２０件と聞いています。大崎署全体については５００件ぐらいあるように聞いておりますので、そういった点で犯罪は少ない地域であることは言えるのかと思います。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"私は数で見ることも１つの見方だとは思うんですけれども、内容だって、全然違うと思うんです。品川区として一定のきちっとした発言というのはしていくべきだと思っているんですけれども、その点についてどんな認識を持っておられるんか尋ねました。","respondent":"早津区民生活事業部次長","answer":"凶悪犯罪からさまざまな事象に対応するように、これはそういうお話でもありますし、私どももそれは理解できるようなことだと思います。先ほど部長からもお答えしましたが、そういった形で対応していこうと、こう考えているところです。","id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"私が伺ったのは、それじゃ安心・安全は保てないんじゃないかという見解はないのかと、それでいいんですか。今まで交番を配置していたのと質が全然違っちゃうんじゃないかと思うわけですけれども、そこについても質は同じだ、大丈夫だと認識しているんか尋ねました。","respondent":"早津区民生活事業部次長","answer":"それが少ないところについては一定の見直しを図ると、こういった考え方自体は、区としても１つの考え方であろうというふうには思います。では、どういう対応が必要なのかというのは…","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"いいんですかということを聞いているんですけれども、そこについての答弁がなかったので、改めてちょっと伺いたいと思うんです。ですから、あるのか、その辺をちょっと伺いたいです。","respondent":"早津区民生活事業部次長","answer":"そうした中で、一定の限られた財源等の中でより有効な警察行政を進めていくためには、そういうふうに私どもは理解はできることだと考えております。プロフェッショナルである警察署で考えた構成ということですので、ＯＢですが一定の職員も配置されると…","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことをしてほしいということで払っているわけじゃなくて、そういう行政をしていただくために税金を払っているわけですから。そういう中で品川区としても、そういう区民の安全な生活を一層進めていくという角度で配置しているものだと思うわけですから、とりあえず終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"大西委員","kind":"質問・要望","question":"品川区はそのための知恵を出すべきであるし、強い要望として、私はあってよいのじゃないかと。区の中としてどういう協力ができていけるのかということを考えてもらえる部分があれば、そのための、区ができることというのは何かないか尋ねました。","respondent":"金子生活安全担当課長","answer":"池田山交番の犯罪情勢ならびに警察官等の運用については、これから警視庁でもそれぞれ防犯拠点を含めて考えていくものと考えております。最も効果がある方法を検討していきながら、抑止の面に力を注いでいきたいと、こういうふうに考えます。","id":"exchange-019"},{"speaker":"大西委員","kind":"質問","question":"相談員という方々だけの状態になってきたときに、どれぐらい、今は２４時間あそこでどなたかがいてという状態での認識でいいんでしょうか。小泉さんがいたから２４時間やっていたのが、総理が関係なくても本来的には２４時間いた現状なのかどうなのかというのはどうなんか尋ねました。","respondent":"金子生活安全担当課長","answer":"先ほどちょっとお話ししたかと思うんですけれども、朝の７時から２０時までの間、交番相談員が中心となって２交代で配置しているような状態です。したがいまして、夜間帯につきましては、今、配置されていないときが多いように聞いております。","id":"exchange-020"},{"speaker":"大西委員","kind":"質問・要望","question":"およそ私はあそこが有人であるということが、外から見たときとか、犯罪者はおよそあの中には犯罪を抑止する人間がいるという想定をされていると。もし今後、住民の方々がずっと安心して暮らせるような形を少し考えていただくことを要望して、私はこれは意見として終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"築舘委員","kind":"意見","question":"交番の廃止ということが最初に６月にはうたわれたかもしれませんが、８月の段階で、それは全然廃止ではないわけですよね。この点のことを熟知されているのかどうか、要するに廃止じゃないですよと、これは地域の方にわかっていただいていますかとの意見を述べました。","respondent":"金子生活安全担当課長","answer":"交番の廃止につきましては、大崎警察署で何度か町会の方を含めて居住者の方に説明しているようです。そこにＯＢを置くということで、今、警視庁で検討しているという形で町会の方にはお話ししているように聞いております。","id":"exchange-022"},{"speaker":"築舘委員","kind":"質問","question":"だから、それは具体的にはいつからとかというのは当然出てくると思うんです。その用途変更をして置くのは、決定した以上は、それはこれから検討しますということにはならないわけですから、そこはどうなっているんか尋ねました。","respondent":"金子生活安全担当課長","answer":"１２１カ所の統廃合に関しましては、方針を決定しているものでありまして、個別に池田山交番をどういった形で運用していくかというのは、最終的にはまだ決定はいたしておりません。","id":"exchange-023"},{"speaker":"築舘委員","kind":"質問","question":"用途が一応変更になるのは決定しましたね。要するに交番の、今までのように安心・安全なものをつくっていくということは決めているわけですから、どうなんか尋ねました。","respondent":"金子生活安全担当課長","answer":"今、調整しています。それを得た上で、最終的には決定、こういったことになるかと聞いております。","id":"exchange-024"},{"speaker":"築舘委員","kind":"意見","question":"人の話はまた別ですよ、だれがなるとかというのは別ですが、ということは決定しているはずだと思うんですけれども。そうしないと決定ができないでしょうとの意見を述べました。","respondent":"早津区民生活事業部次長","answer":"ただし、警視庁の方針として、４交番については用途変更をするという形の方針であるというようなことを承知しているということです。例えば何人ＯＢが配置されるのかとか、委員が今お尋ねの何月からなのかというようなことは、まだ私どもは全然知らないというような段階です。","id":"exchange-025"},{"speaker":"築舘委員","kind":"質問","question":"それは警視庁じゃないと判断はできないんですかね。その１１０番をするというのはどこから来るんか尋ねました。","respondent":"金子生活安全担当課長","answer":"１１０番された場合は、さっき言ったいるだけの交番になりますと、その１１０番もなかなか行きがたいような場合も出てくるかと思います。したがって、パトロールの強化を含めた交番の強化、こういったものを警視庁で考えているようです。","id":"exchange-026"},{"speaker":"築舘委員","kind":"質問","question":"区はそうやって協力していこうと言っているわけですから、何も今回、そして新しい発想で交番というものの機能を自分たちで使って。これは意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"今まで交番の機能は７時から２０時までですから、また常に警察官、ある意味で住民の皆さんにとっては非常に不安をかき立てるような要素だと思います。これは要望なんですけれども、ちょっと品川区でもできることを、要望だけ言わせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"堺委員","kind":"質問・要望","question":"ちょっと何点か確認をさせていただきたいんですが、たしか今回、そのことによってどうなってくるのかということを確認をさせていただけますか。その辺はどうなんか尋ねました。","respondent":"金子生活安全担当課長","answer":"池田山交番の用途変更の運用の関係ですが、先ほど委員のお話があったとおり、五反田駅前の交番の職員を強化するということになります。したがって、委員がご心配の安全性に関しましては現行よりよくなるのではないかと、そういうふうに聞いております。","id":"exchange-029"},{"speaker":"堺委員","kind":"質問","question":"今まで以上にその住民の人たちが不安にならないようにパトロールが強化されるんですよと、ご安心くださいというふうに理解をしていいんですか。その辺は。","respondent":"金子生活安全担当課長","answer":"おっしゃるとおりです。","id":"exchange-030"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから、その思いは警視庁にも届けていただきたいなと、そんな気がするんです。ですから、その辺のところは何かご意見かご感想がありましたら、そこは教えていただけますか尋ねました。","respondent":"金子生活安全担当課長","answer":"これは警察白書の平成１６年度版のデータ等に基づくものですけれども、パトロール強化というのが６２.３％で飛び抜けて高いわけなんです。したがいまして、そういった声も大事にしながら、警察の動きを見ながら、区でできることをこれから考えていきたいと…","id":"exchange-031"},{"speaker":"堺委員","kind":"確認","question":"つく予定じゃなく、人が足りなかったから一般の人をそういうところに回したとか、その辺はどうなんですか。確認をしておきたいと思うわけですが。","respondent":"金子生活安全担当課長","answer":"東京都の考え方もありますので断言できませんけれども、そういったことについていろいろ働きかけをしていると、このように聞いております。","id":"exchange-032"},{"speaker":"堺委員","kind":"質問・要望","question":"池田山交番がなくなります、今まで大変よかったと言っているんですから、それがなくなっちゃうんですから、不安でしようがない。何かあれば即それの対応ができるわけですから、ですからそういう意味で、そう要望だけしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"林（和）委員","kind":"質問・要望","question":"ここら辺で、もうそろそろ内容もわかってきたところですので、結論を出してほしいと求めました。そして、我が自民党といたしましては、この請願に対しまして趣旨採択ということで決めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"菊地委員","kind":"質問・要望","question":"具体的にどういうふうに、どういうふうにパトロール強化をされるのか、ここをきちっと示していただきたいんです。例えば１日のうちあの地域を、そういう具体的なところが示されない限りは、言葉上で警視庁の考え方を述べているだけなんじゃないか尋ねました。","respondent":"金子生活安全担当課長","answer":"これは２つほど問題があるのかなと思います。１つは、区とも連携していろいろな形でやっていますけれども、これから検討していきたいと思います。","id":"exchange-035"},{"speaker":"菊地委員","kind":"質問","question":"こういう段階でこういう請願が出ているわけですから、職務権限も違う、これは明確なんです。だからこそ区としてきちんと意見を上げるということが必要なのではないか尋ねました。","respondent":"山田区民生活事業部長","answer":"荏原警察署は荏原町駅前交番、これは廃止ということに、今段階そういう方針でいるということで説明がわざわざ署長がいらしたときに。これはそうではなく、地域のパトロールも充実できるんだというふうにご説明がありましたので…","id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"パトロールを強化するのはいいですから、今、とりわけ必要なのかなと思います。もう少し請願を出された方々のご意見も伺うチャンスを議会として持っていく必要もあるのかなと思いますので、今日結論を出すのであれば、しかし。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"堺委員","kind":"意見","question":"私も、今日この請願については結論を出すべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"大西委員","kind":"意見","question":"ただ、行政として当然のことであろうと思うので、この特段の配慮をお願いしますということを私は趣旨として採択すべきであろうと考えます。ですので、私どもとしては今回の請願を趣旨採択にしたいと考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから、安心というんですか、安全ですか。このことを申し添えて、趣旨採択というふうにお願いしたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"菊地委員","kind":"意見","question":"私どもは採択すべき内容だと考えていますけれども、委員の皆さんのご意見で趣旨採択でということで、ぜひ趣旨採択ということでお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区として池田山周辺住民の安全が最善に、品川区で最善の努力をして、いっときでも早く何か対策を打ってほしいと。できれば、対策を考えていただきたいということを要望しながら、趣旨採択ということでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"最後に開催されたのが３月２３日なので、これからの議題なのかなとは思って先ほど説明は伺っていたんですけれども、いずれの機会にやるでしょうか。今後の、その中で皆さんの中からいろいろと出されているご意見で特徴的なことがあったら教えてほしいと求めました。","respondent":"金子生活安全担当課長","answer":"こういったさまざまな活動に大変な影響を及ぼすと思いますので、あらゆる機会を通じて各種団体等にご説明等をしていきたいと思います。２点目の生活安全協議会の議題ですけれども、これまでの７回のうち、そういった内容で協議はしています。","id":"exchange-043"},{"speaker":"南委員","kind":"意見","question":"ここにもご紹介がありましたように８３運動だとか、この中で子どもの安全対策についてが特徴だということなんですけれども、具体的にはどんな内容でこの問題が議論されているのかということをもう少し詳しくご紹介してほしいと求めました。","respondent":"金子生活安全担当課長","answer":"そういったことを検討して、対策を検討、協議しています。","id":"exchange-044"},{"speaker":"菊地委員","kind":"質問","question":"ちょっとよくわからなくて、この荏原の図面ですけれども、さっき見てきた交番って、これはどこの地点になるんか尋ねました。","respondent":"金子生活安全担当課長","answer":"真ん中に駅舎があります。その図面向かって右側のところに、右斜めというか、点線で囲われている地区があると思うんですが、ここが現交番です。","id":"exchange-045"},{"speaker":"菊地委員","kind":"質問","question":"ちょっとお聞きしたい。ここは今の計画ですと、さっきほかの４カ所はＯＢの配置とかという話がありましたけれども、ちょっとその辺の体制を教えてくれますか。","respondent":"金子生活安全担当課長","answer":"ここにつきましては、区の防犯拠点となります。交番の勤務員、あるいはパトロールカー、こういったものの立ち寄り所として活用する予定です。","id":"exchange-046"},{"speaker":"菊地委員","kind":"質問","question":"立ち寄り所として活用するだけで、別に常駐されるわけではないということですよね。先ほど交番が他の４カ所については警視庁がＯＢを手配をすると、どうしてこれが先につくられる状況というのが生まれてきているんか尋ねました。","respondent":"金子生活安全担当課長","answer":"８月に荏原警察署長が区に参りまして、そこで荏原町駅前交番については廃止すると、こういった説明に基づくものです。したがいまして、現交番が廃止されて、空白期間が生じないように補正で組んで、こういった穴の生じない拠点を設けていきたいところでの措置です。","id":"exchange-047"},{"speaker":"菊地委員","kind":"意見","question":"ただ、決定をしていないものに対してどうなのかという、やっぱりここでも同じ疑問が私はどうしても出てくるんですけれども。それともう１つは、少なくても常駐をするなど、警視庁が統括をするところと同じようにするべきではないかなと思うんですけれどもとの意見を述べました。","respondent":"早津区民生活事業部次長","answer":"事前の対応に区として取り組めるようにするにはどうしたらいいかという観点の中から、速やかな対応をとるという趣旨で計上させていただいたものです。立ち寄り所というような形で、この安心安全のステーションにしていく、こういうことです。","id":"exchange-048"},{"speaker":"菊地委員","kind":"意見","question":"区の施設としてこれをもし設置をするのであれば、それは別に区の費用で人員を配置することは可能なんですよね。だから法律的に無理だとか、どうのこうのという話じゃないんでしょうとの意見を述べました。","respondent":"早津区民生活事業部次長","answer":"しかしながら、区として考えた中で、パトロールの重要性だとかというような警察の考え方もあります。警察の人も来ているし、何となくまちの中でもって、あそこには結構人がいますねみたいな感じになればというような考え方にしたいというものです。","id":"exchange-049"},{"speaker":"菊地委員","kind":"質問・要望","question":"区の生活安全サポート隊のパトロールですか、これなんかも、これが区が十分区民の皆さんに見せていくことのできる部分だと思うんです。ちょっと元に戻ってしまうような気もするんですけれども、どうしてここだけ廃止というふうになったのかをもう一度言ってくれますか。","respondent":"山田区民生活事業部長","answer":"ただ、背景とすれば、駅舎全体にあそこに東急の職員寮も含めて立ち上げるという建物変更というのがあります。そうした変更の中で、警視庁では、いわゆる一たんつぶさなければならないところに新たに建て替えるというような方針は持っていないと。","id":"exchange-050"},{"speaker":"菊地委員","kind":"質問・要望","question":"最後にしますけれども、この地域で、さっきの議論と共通してしまいますけれども、最低限この体制でいくということであれば、これに区として常駐をする職員を配置するということをぜひ考えてほしいと求めましたので、意見として申し上げておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"今日はもうこんな時間ですのでいいですから、改めてそういう説明をいただく時間をとっていただきたいと思っておりまして、理事者にもそういうことで準備をしてほしいと求めました。","respondent":"早津区民生活事業部次長","answer":"品川区における５つの交番については、そのほか４交番については連絡所としてＯＢを配置すると、それ以外のことは特段ございません。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"私は警察行政がストレートにこのところに来ているわけじゃないですから、ぜひ取り計らっていただきたいし、ちょっとその辺がどうしてなのかわからないから……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"安全・安心のまちづくりということで大きなテーマに掲げているわけですから、そして、ぜひご報告をいただきたいということでお願いをしたところです。正副委員長で確認されておりましたし、委員長としてもぜひご報告を区からも出していただきたいということで要望させてほしいと求めました。","respondent":"山田区民生活事業部長","answer":"これは私どもが同じようにご報告をもししたとしても、それについてのご質疑があっても、お答えできる立場ではございません。４カ所については用途変更でということで、概略を口頭でご説明させていただいたことをもって報告をさせていただいたと解釈していますので、その点。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"それを私たちもそのとおりに期待していたわけですから、そこのところは整理をしていただいて、報告をしていただければいいと私は思うんです。品川は数のところが４と１というふうになっているけれども、それは答弁ができないということだけをもって説明できないということなんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"大西委員","kind":"質問・要望","question":"そのことを議論して、理事者に答弁を求めるというのは、これは本来的には。それは警視庁が答弁すべきことで、理事者が今後答弁していくこととは違う話でしょう。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/847285?Template=document&Id=6334#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":43266,"voices":129}},{"id":"h18-20060928-14","meetingId":"h18-cm09","date":"2006年9月28日","dateIso":"2006-09-28","committee":"行財政改革特別委員会","time":"午前１０時０２分～午後 ２時０７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"これはどういうふうに集められたものの集計なのかということが１点と、あとちょっと具体的な１つは、今年度の予算特別委員会でしょうか。今ある事業についてもう少し予算をそこに投入するべきではないかというところもあるんですが、何かあれば教えてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"各事業部長のほうに庁内で通知をして回答をもらいまして、各課長、それから事業部長の意見をもらったという形です。それは内部管理的なものですとか、特にそれだけではないということを、そういう観点でこの事務事業評価を進めてきたです。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"そこのところはどうなのか教えていただきたいことと、区民の方たちに参加をしていただきたいという制度だと私は理解しているので、どういうふうになっているのかということを説明ほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"それから、外部評価委員の進捗状況の部分なんですけれども、こちらについては今、仕組みづくり、ベンチマークの部分について進めている最中です。こちらの部分と直接的にリンクするようなものではないんですけれども…","id":"exchange-002"},{"speaker":"井上委員","kind":"確認","question":"この事務事業評価のまとめということで、案ということで今日提示されまして説明を受けたわけですが、これはこれからどういうふうに利用していくかというか、広報というか、出していくものとして考えればいいのかということですけれども、確認させてください。","respondent":"堀越行財政改革担当課長","answer":"今後の検討の大まかな方向性をできればこの中にも記載できるような形、通常の各年度行っております事務事業評価の報告書の公表の時期と同様に、年度末に公表をしていきたいと考えております。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、せっかく品川区のほうでここまでやったわけですから、そういうことについての対応をお聞かせくださいというのが１つと。せっかくやったわけですから、それはぜひ事業部制になっているわけですから、そのことについての仕組みの考え方を説明を求めました。","respondent":"堀越行財政改革担当課長、新美企画部長","answer":"企画部のほうで進めております指定管理、それから民間委託のあり方、どのような方策をとるべきかといった観点で検討を進めております。それについては各所管の事業部の意識の中にも課題として認識されていると考えております。 評価シートにつきましては、当然評価を継続的にする場合、シートは原則同一シートで５年間行ってきたわけです。そういうことを含めて５年たった時点で、本年度検討を始めておりますので、本年度は節目の年に来ているというものです。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"素直に１４ページを読み込んでしまったものですから、リンクされていないかなと思い込んでしまう文章になっていますので、その対応をお願いします。指定管理者とか、民間に出した事業をどう評価していくかというシートも当然考えていかなきゃならないわけですから、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"少し教えていただきたいと思うんですけれども、そこをまず伺いたいのと、お考えを説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"業績による評価、やはり区民に対する説明責任ですとか、他の自治体におきましてもこういう行政評価といった導入が進んできていると考えております。この２点が大きな成果ではないかと考えております。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"人の命よりももうけが優先されたり、こうした流れの中に対するそれでいいのかという、この流れをどう考えているのが伺いたいんですね。一人ひとりの区民の生活、福祉、それこそ行政だと思うんですけれども、その辺がよくわからないので、教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"そういう考えではございませんで、向上を図りながら、より効率的な運営を図っていくという考えです。それからもう１点の効果をどう見るかという部分ですけれども、より効果的なあり方を探って事業の執行に努めている、そういった認識をしております。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"なのでもう少し教えていただきたいのは、具体的に教えていただきたいということがまず１つと、５ページ目になるんでしょうか。そこを教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"それによってサービスが図られるのであれば、そういった形で活用していくという考えです。区民の目線というか、区民の視点から見ているような、そういった形での基準を設けていると考えております。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"それを伺いたいので、教えていただきたい。その点も説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"これまでも繰り返し伺うところですけれども、職員をたしか１,６００名でしたか、削ったと。そこの点だけ、最後にお考えを説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"考え方がちょっと違うのかもしれないんですけれども、我々としてはサービス維持向上とノウハウの活用、先ほど申し上げましたとおり、そのような観点で進めておりまして、委員がご指摘なさるような考えを目的としてやっているものではございません。","id":"exchange-010"},{"speaker":"須藤委員","kind":"質問","question":"うちの会派でこの何年間で議会で質問した、そんな計算とかどうのとかとしなくても、こういう項目が当てはまってきていますよね。このあたりはどうかなというのと、しなくても我々から見るとそういうことが出てきているのは、どういうお考えになっているのかなと。","respondent":"堀越行財政改革担当課長","answer":"先ほどもご説明しましたようなさらなる民間委託の追求、今、より発展していけるようなそういった部分も入れていきたいなと考えています。それからもう１点が、そういったものもきちんと受けとめながら、丁寧に進めていきたいなと考えています。","id":"exchange-011"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、この辺はどうだろうという質問してきたことがこの中にあらわれてきた結果だなと感じているんです。それが我々の考え方と一緒になってきたということは、区民の目線に近づいてきたものと理解しているんですが、そのあたりはいかがか尋ねました。","respondent":"新美企画部長","answer":"一つひとつを毎年チェックしてきた結果であろうと考えていますので、区民満足度を整理する仕組みというのは、ちょっと意味不明なところがあります。そういったことやもう少し高めの部分、もう少し正確に表現できるように…","id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"今、そのあたりをしっかりつかめるような事務事業評価というものを掲げていくのが、私は行政の１つの持っていき方だろうと思っているんです。ですから、それでいいのかどうか、いかがか尋ねました。","respondent":"新美企画部長","answer":"仕組みとしてどうやっていくかということがありますので、そういうことについて今現在、この５年間進めてきたやり方ですね。この方式では見直しすべきところは見直したという時点に来ているという認識で、全体をどうするかをこの時点で検討したいですので、全体的な観点で。","id":"exchange-013"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"これについて見ただけではなくて、そのことについて、原小学校の場合にはこういう施設運用に関して基本的な方針ということでも行政から出されている。せっかく他の施設を見学に行ったわけですから、そういった時間を今日取れたらそういうことでしていただきたいし、ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"須藤委員","kind":"質問・要望","question":"あそこはあそこで１つのやり方だと思うし、もう少し資料を集めていただきたいということをお申し出して、それがとれたらというふうにお願いしたいと思います。","respondent":"本多委員長","answer":"今日のところは１カ所が運営をしているという、またそういったものをできる限り資料は準備をさせていただきたいと考えています。〔「なし」と呼ぶ者あり〕","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/218784?Template=document&Id=5808#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":21339,"voices":41}},{"id":"h18-20061012-6","meetingId":"h18-cm10","date":"2006年10月12日","dateIso":"2006-10-12","committee":"区民委員会","time":"午後１時５８分～午後２時０３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"の１、新委員の紹介","agenda":"の１、新委員の紹介","exchanges":[{"speaker":"山内委員","kind":"意見","question":"自民党の山内晃です。そしてご鞭撻をいただき、しっかりと委員会を盛り上げていきたいと考えていますので、どうか今後ともよろしくお願いを申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247239?Template=document&Id=2472#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":1491,"voices":23}},{"id":"h18-20061012-8","meetingId":"h18-cm10","date":"2006年10月12日","dateIso":"2006-10-12","committee":"建設委員会","time":"午後１時５８分～午後２時０４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/965541?Template=document&Id=3864#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":1384,"voices":17}},{"id":"h18-20061012-9","meetingId":"h18-cm10","date":"2006年10月12日","dateIso":"2006-10-12","committee":"文教委員会","time":"午後１時５８分～午後２時０２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"の１、新委員の紹介","agenda":"の１、新委員の紹介","exchanges":[{"speaker":"本間委員","kind":"意見","question":"区民連合の本間隆です。どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/670410?Template=document&Id=4586#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":1439,"voices":16}},{"id":"h18-20061012-4","meetingId":"h18-c-settlement","date":"2006年10月12日","dateIso":"2006-10-12","committee":"決算特別委員会","time":"午後１時４０分～午後１時４６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/754385?Template=document&Id=1258#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":2388,"voices":17}},{"id":"h18-20061012-5","meetingId":"h18-cm10","date":"2006年10月12日","dateIso":"2006-10-12","committee":"総務委員会","time":"午後１時５７分～午後２時０２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"の１、新委員の紹介","agenda":"の１、新委員の紹介","exchanges":[{"speaker":"原（浩）委員","kind":"意見","question":"どうも皆さん、こんにちは。何とぞ今後、諸先輩方、ご指導をよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816536?Template=document&Id=1734#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":1591,"voices":25}},{"id":"h18-20061013-4","meetingId":"h18-c-settlement","date":"2006年10月13日","dateIso":"2006-10-13","committee":"決算特別委員会","time":"午前１０時０４分～午後６時２７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地副委員長","kind":"質問・要望","question":"残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。次に第６項、５階の理事者控室に当委員会の模様を放送いたしますので、そちらでお聞きいただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値についての説明が終わりました。 それでは、平成１７年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値についての説明が終わりました。 それでは、平成１７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"築舘委員","kind":"質問・要望","question":"決算の概要ということで、成果報告書では５５ページのあたりを質問させてほしいと求めましたが、その前に、濱野新区長誕生おめでとうあります。その点に関して、新区長の抱負、また感想をお聞きできればと思います。","respondent":"濱野区長","answer":"多少時間と努力の積み重ねが必要になってくる政策だと思いますが、この点をしっかりやっていきたいと考えています。そういうやり方で、今後の区政を運営していきたいと考えています。","id":"exchange-002"},{"speaker":"築舘委員","kind":"質問・要望","question":"平成１８年度の方針としては、安心・安全のまちづくりの３本柱になっているわけでございまして、しっかりとやってほしいと求めました。後で教育費のほうで質問はしますが、まず、しっかりと抱負はお聞きいたしました。","respondent":"日下部企画財政課長","answer":"副収入役からもご説明させていただきましたけれども、税収増については、例えば税務部門が徴収努力を相当しっかり行っております。そういう形での取り組みをしておりますし、それぞれの立場におきまして、自主的な財源確保の努力を進めているです。","id":"exchange-003"},{"speaker":"築舘委員","kind":"質問・要望","question":"国のほうも三位一体改革とか、社会保障制度の改革などので、しっかりとした自主財源をつくっていくということもしていかなければならないと思います。手数料も前年比で２.９％増になっておりますが、努力もしてほしいと求めましたが、その点に関してお答えほしいと求めました。","respondent":"日下部企画財政課長","answer":"基本的には、まず大事なことは、受益者負担の原則というものをしっかりと保って運営をしていくということが非常に重要であります。適宜、社会、今後とも区民の間で負担の公平さがしっかりと保たれるように努力をしてまいりたいと思っています。","id":"exchange-004"},{"speaker":"築舘委員","kind":"質問","question":"もう一つどうしても取り上げておかなければいけないのは、しっかり２３区の区長会でも発言をされ、頑張ってこられたわけです。今年の５月から都区のあり方検討会とかができつつ、その点、新区長からお伺いしたいと思います。","respondent":"濱野区長","answer":"一生懸命発言をしていきたいと考えていますし、自分なりに、東京都の幹部の方に働きかけをしていきたいと考えています。大変に厳しい交渉だとは思いますけれども、自分としては精一杯の力を振り絞って交渉の下支えをしていきたいと考えています。","id":"exchange-005"},{"speaker":"築舘委員","kind":"質問・要望","question":"そういった意味で、今後も健全財政をしっかりと築いて、重点政策につぎ込んで、また品川区が全国に発信をしていくという、地方自治体としての真の自主的な行動というものをしっかりと示していただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私からは、７１ページの民生費負担金、それから８０ページ以降の国庫支出金、都の支出金の関係でお伺いをしたいと思います。平成１７年度は、大きなところで一つ、三位一体改革の影響をお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"大きな枠組みで申し上げますと、見込みといたしましては、品川区の場合は約４億円ほどの増収になるというふうに見込んです。増収がほとんど見込まれない、差し引きマイナス２０億円ほど、区の財政への影響が出てくるということが言えるかと思います。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"確認","question":"大枠のところでは２０億円ぐらいの減、合計すると一般財源のところは平成１５年度とほぼ同規模であって、基本には大きく変化をしない。ちょっと見解が違うなと思うんですけれども、どうか、ちょっとその辺を確認したいと思います。","respondent":"日下部企画財政課長","answer":"ここで具体的な影響というのが、細かい点も含めてはっきりしてまいりますけれども、先ほど申し上げましたが、増収という形での期待はできない。実質が下がったとか、減ったとか、そういう中身ではないということでご理解いただきたいと思います。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"新しく改善で上乗せがされているというところも見受けられるので、そういった面では、大枠のところでどうなのかなと。十分に黒字でやっていけていると思うんですが、そこを一つ、お聞きしたいと思います。","respondent":"日下部企画財政課長","answer":"今回の三位一体改革におきましても、いろいろ検討の俎上には乗りましたけれども、結果的には、大きな進展を見ることができなかった。その部分が減るということにはなりますけれども、実質そのものは基本的には変わらないと、このように私どもは受けとめてあります。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成１６年１１月２６日、このことの方針を確認をしているということなので、こういうところは引き続き求めていくところであると思うので。やはりこの辺の基準というところが出てくるんですけれども、このところが崩れてきていると思うんですが、この辺をどう考えていらっしゃるか尋ねました。","respondent":"日下部企画財政課長","answer":"大ざっぱに申し上げれば、一つはやはり３兆円の税源移譲が実現したということが大きな評価です、今までになかったことです。今後の課題として、やはり地方が力を合わせて、この課題に解決に取り組んでいかなければいけないのではないかと考えているところです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成１９年度の新しい保育料に跳ね返ってくると思うんですが、どうか、その辺。豊島区などでは、連動値上げをさせないための保育料の段階を調整する条例が出されているんですけれども、その辺についてのお考えを説明を求めました。","respondent":"小林保育課長","answer":"ただ、その後、平成２０年度におきましては、所得税の税制改正、トータルで影響が出てまいりますので、逆に大幅な減収が想定されております。むしろ全体の状況を考えて、保育料の水準を検討してまいりたい、ご議論いただくところになるかと考えております。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お子さんの保育料の値上げは、豊島区はきちんと試算をしていまして、平均で、お一人が２万５１７円なんです。すごく求められていると思うんですが、今現在の困難をどう救っていくのかが大事であると思うんですが、いかがか尋ねました。","respondent":"古川児童保健事業部長","answer":"今、この減税の問題をとらえていきませんと、そのことから保育料を幾らにすればいいかということだけはないと考えています。そういうふうに、今後、さまざまな視点からとらえていく課題であろうと考えております。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５１％求めているということでしたけれども、条例で是正を求めますが、いかがか尋ねました。","respondent":"古川児童保健事業部長","answer":"先ほどお答えしたとおりでございまして、三年、一定の水準の中で推移してきております。定率減税の問題につきましては、大きく全体をとらえて検討すべき課題だと、先ほどお答えしたとおりです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保育園は、ほんとうに今、子育てが大変な中で、共働きのところもそうですが、在宅を支えるところで、ぜひほんとうに負担軽減をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"私は、８４ページの木造住宅耐震診断事業費と、これに関連してお伺いしたいと思います。平成１７年度はここに載っておりますが、平成１８年度と続いておりますけれども、わかりましたらあわせてお願いいたします。","respondent":"片田建築課長","answer":"平成１６年から実施してございまして、予算上は４０件ということでございまして、実績についても４０件という内容です。なお、２０件ほど補強設計も含めて改修を進めているというような状況でございましたけれども、合わせて２８件ほどが改修を進めているという状況です。","id":"exchange-015"},{"speaker":"武内委員","kind":"意見","question":"そうしますと、今、２０件、２８件ぐらいが検討中というか、設計中ということで、３年間で４８件が改修に結びついたというふうに理解していいのか、どうか、もう１回お願いしますとの意見を述べました。","respondent":"片田建築課長","answer":"ちょっと説明が十分でなかったですけれども、現時点で、２８件が改修に向けての作業に取りかかっているという状況です。先ほどの２０件というのは、今年の３月末の状況です。","id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました、２８件ということで理解いたしました。いよいよ今年７月からは、スタートして約３カ月になるかと思うんですが、その辺の数も教えてほしいと求めました。","respondent":"片田建築課長","answer":"改修についての支援ですけれども、今年７月から実施しています。ただ、いずれも現在工事中というものもありますので、まだ予算の執行までには至っていないという状況です。","id":"exchange-017"},{"speaker":"武内委員","kind":"確認","question":"多少対応していただいたと、たしか聞いているんですけれども、その辺の確認。５件という予算ではありますけれども、何とかその辺を弾力的に対応していただけるのかどうか、その辺のところの見解をお聞きしたいと思います。","respondent":"片田建築課長","answer":"現在は４件という状況ですけれども、設計等々にそれなりの時間がかかっているということもありまして、タイムラグが生じてくるという状況です。当初の予算上は５件ですけれども、そのような申込みが増えてくると想定していますので…","id":"exchange-018"},{"speaker":"武内委員","kind":"質問・要望","question":"ところで、今年１月２６日に耐震改修促進法が改正をされまして、施行されました。１１月ごろを目途に計画を策定すると聞いているんですけれども、区のほうでわかる範囲で結構ですので、現在の状況を教えてほしいと求めました。","respondent":"片田建築課長","answer":"そういうことも含めて、現在、東京都のほうとしては、６月初旬から検討会を立ち上げているという状況です。パブリックコメントを予定しているというようなお話も聞いてありますので、来年１月、もしくは２月になってからの公表になろうかなと想定しています。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問・要望","question":"１０月１１日に、耐震改修促進計画の早期策定を求める要望書ということで、区としての策定をお願いしたいということで要望してまいりました。安心・安全のまちづくりを進めていくというお話もありましたので、この件についての区長のお考えがありましたら、お聞きしたいと思います。","respondent":"濱野区長","answer":"そういう中で、やはり安心・安全のまちづくりのためにできるだけのことを、区として、していかなければならない。所管での検討、あるいは支援というものが必要だという認識は持っておりますので、前向きな対応をしてまいりたいと考えているところです。","id":"exchange-020"},{"speaker":"武内委員","kind":"質問・要望","question":"４月にスタートした木造住宅耐震改修の助成につきましても、私どもも、要望させていただいた次第であります。計画に組み入れて計画的に行っていくのか、どうか、その辺についての見解を教えてほしいと求めました。","respondent":"片田建築課長","answer":"計画のほうの今後の進め方ですけれども、東京都も、おおむねそういうような考え方に沿った形で動いているということを聞いてあります。そのような方向で検討してまいりたいと聞いておりますので、区としても、同じような考え方に基づいて進めていきたいと認識しております。","id":"exchange-021"},{"speaker":"武内委員","kind":"質問・要望","question":"国の９割ということではなくて、ぜひ限りなく１００％に近い耐震を目標として進めていただきたい、これは要望させてほしいと求めました。耐震診断だけじゃなくて、耐震改修についても計画に入れてやっていくものと考えておりますけれども、その辺のご見解をお伺いしたいと思います。","respondent":"片田建築課長","answer":"マンションにつきましては、平成１８年から２０年までの３年計画ですけれども、分譲を対象に診断の支援をしていくといったような流れがあります。区のほうとしても、そのような国の動向ならびに東京都の動向を十分に踏まえまして、促進計画の中で検討してまいりたいという考えで…","id":"exchange-022"},{"speaker":"武内委員","kind":"質問・要望","question":"そうした範囲についても、実態に合わせて範囲を広げていくということも検討していただきたいと、ここで要望させてほしいと求めました。東京都の計画が出た段階で早急にやっていただきたい、このように考えていますけれども、ご見解をお伺いします。","respondent":"片田建築課長","answer":"東京都のほうとしても、その内容を踏まえた地域防災計画にフィードバックするというようなこともあろうかと考えております。促進計画が位置づけられているという認識を持っておりますので、できるだけ速い時期に、促進計画について検討してまいりたいと考えています。","id":"exchange-023"},{"speaker":"武内委員","kind":"質問・要望","question":"できるだけ速い時期ということなので、それ以上はあれなんですけれども、大体の目安がもしありましたら、お示しいただけるようだったら、お示しほしいと求めました。","respondent":"片田建築課長","answer":"東京都の危険度調査というものは、これはおそらくですけれども、来年の１２月とか、そのぐらいの時期になろうかと考えております。やはり、来年度中に何とか検討ができればということも考えておりますので、できるだけ速い時期に行ってまいりたいと考えております。","id":"exchange-024"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひよろしくお願いします。調査を待たずに計画を出すわけですから、ぜひ早めに取り組んでいただきたいことを、最後に要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"大西委員","kind":"質問・要望","question":"今、積立金をやっていくということもありましたけれども、その辺のお考えはきちっとできているのか、どうなのかということが１点。この６年間で６１０名ほどか尋ねました。","respondent":"濱野区長、日下部企画財政課長","answer":"これからの日本の人口構造が大きく変化をする、その対応策として、国家的なプロジェクトとして全体をプランニングするべき事柄だと考えています。したがって、全体として… 義務教育の積立金を１３０億円ほどしておりますけれども、それから有効な活用という形で、この大きな財政需要に対応してまいりたいと考えております。先ほどもご説明申し上げましたが、昨年が２５.１％でありますので…","id":"exchange-026"},{"speaker":"大西委員","kind":"質問","question":"少し聞き逃したでしょうか、採用等の中で、適正な人数をどのレベルに置かれているのかということが１点。一つ風穴をあけていく必要性もあろうかなと思うんですが、その辺は、区長はどのようにお考えか尋ねました。","respondent":"濱野区長、榎本人事課長","answer":"少子化対策の基本の法律、私どもで今プランニングしている中にも、企業への働きかけという重要な項目があります。あるいは、指導していくという部分がありますので、そういうところでの働きかけというのをしてまいりたいと考えておりま… 結論的には、適正な人数を自治体の中で定めようという考え方は持っておりません。その経費にかかる人件費、時代とともにいろいろなサービス需要も変わりますし、減らせるものはどんどん減らしていくという形で臨んでいるところです。","id":"exchange-027"},{"speaker":"大西委員","kind":"質問","question":"今、人事課長がお答えになりましたけれども、今、自然減の中で職員の数が１００名ずつ減っていますけれども、では、今だったら、これが適正な人数じゃないか、最低限だったらこれぐらいじゃないかという数字というのは、全く考えられていないということか尋ねました。","respondent":"榎本人事課長","answer":"そういう意味の数でいきますと、職員定数というもので、きちんと条例で定めておりますので、平成１８年４月１日現在、２,６９２名というのが職員定数という形で定めているところです。","id":"exchange-028"},{"speaker":"大西委員","kind":"質問","question":"最後に１点。２名定員減という方向になってまいりますが、品川区全体の予算の中から２名減することによって、わかりますれば説明を求めました。","respondent":"日下部企画財政課長","answer":"全体の１,３００億円の中で２,８００万円ということでありますので、パーセンテージからまいりますと、率自体としてはかなり低いと考えられます。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"都区財政調整制度についてお伺いをしますが、昨日の区長の所信表明を伺っていたときに、私は、ある場面を思い出しました。品川区の財政自主権を確立するために、これから財調制度をまずどのようにしていかなければいけないかというお考えをお尋ねします。","respondent":"濱野区長","answer":"財調というものを、とにかく配分率を増やせばいいというものではないというのが、私のもともとの考え方です。考え方として、私も、そういう点で努力をしていきたいと思っているところです。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"２３区に配っていくというこのパターンを変えるために、しかし、５年経ってもあまり変わっていないわけですよね。続いていってしまうのかなという思いもあるんですけれども、その辺についてはいかがか尋ねました。","respondent":"濱野区長","answer":"あるいは２３区の区議会、それは単なる運動論でしょ、法律は違いますよということにはならないんではないか。それは、どこかでそういう広範な運動というものが必要になってくる時期が出てくるのではないかと、私はそんなふうに思っています。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"区長がおっしゃったことをどんどん推進していただきたいという区もあれば、いや、このままでいいというふうな思いがある区もあると思うんです。その強い思いを、２３区特別区長会等で発揮していっていただきたいと、私は思うんですけれども、その辺のご決意はどうか尋ねました。","respondent":"濱野区長","answer":"それからもう一つ、東京都との関係は、先ほど申し上げた考え方です。したがって、そういう考え方にのっとって、自分として行動していきたいと考えています。","id":"exchange-032"},{"speaker":"三村委員","kind":"質問","question":"私から７６ページの放置自転車等保管料についてお伺いいたします。保育施設を充実していくべきではないかと思いますけれども、その点について、今後の方針についてお伺いできればと思います。","respondent":"濱野区長","answer":"やはり、こういった施設を企業責任において設けるべきだという声が大分高まっているのも事実です。そういったことで、品川区の子育て支援の方針も、そういう方向でありますので、企業についての働きかけは続けていきたいと思います。","id":"exchange-033"},{"speaker":"三村委員","kind":"質問・要望","question":"先ほど申し上げました７６ページの放置自転車関連について、質問をさせてほしいと求めました。どのぐらい引き取りに来ているのか、その点についてお伺いしたいと思います。","respondent":"松嶋交通安全担当課長","answer":"それから、撤去台数につきましては、平成１７年度は自転車が２万６,９０３台、バイクが５２６台、合わせまして２万７,４２９台です。返還数につきましては、自転車が１万３,９４４台、バイクが２２２台、合わせまして１万４,１６６台という数字になっております。","id":"exchange-034"},{"speaker":"三村委員","kind":"質問","question":"国の法律が変わって、道路上にも駐輪場整備できるようになったとお伺いしているんですけれども、詳しい内容についてお聞かせほしいと求めました。大井町駅前にも法律が変わったことによって駐輪場の整備が可能になったのかどうか、その点にいいてもお聞かせほしいと求めました。","respondent":"松嶋交通安全担当課長","answer":"駐輪場を設置することによる一般通行者への影響が一番の課題でございまして、そういったものを交通の安全と円滑に支障を及ぼさないことが大前提です。駐輪場の整備の必要性も十分認識しておりますので、設置手法、大いに検証した上で検討していきたいと考えております。","id":"exchange-035"},{"speaker":"三村委員","kind":"質問","question":"いろいろ検証した上で設置していきたいということです。具体的に大井町駅前ということでお伺いしたんですけれども、設置の可能性があるのかないのか、その辺のところについてお伺いしたいと思います。","respondent":"松嶋交通安全担当課長","answer":"それも含めまして、詳細に幅員等の計算をしたり、交通量の計算もしなければならないということもありますので、そういった部分も含めて検証していきたいと考えております。","id":"exchange-036"},{"speaker":"三村委員","kind":"質問","question":"次に、５２ページの就学援助費および７０ページの奨学金貸付金についてお伺いいたします。奨学金の利用者の実数の推移についてお伺いしたいと思います。","respondent":"古里学務課長、鷹倉区民課長","answer":"就学援助費の推移ですが、昨年度、小学校につきましては認定率２７.５％、中学校におきましては３１.４％です。平成１６年度が３０％、１５年度が２８％、近年微増という傾向です。 平成１６年の在学貸付金は公立・私立と合わせまして２４９名、平成１７年度が２４２名、平成１８年度が２２９名です。そして、入学準備貸付金も公立・私立を合わせまして、平成１６年度が６０名、平成１７年度が７０名です。","id":"exchange-037"},{"speaker":"三村委員","kind":"質問","question":"実際に就学援助を受けられている家庭は約３割程度あるということで、全国平均に比べると大分高い数字と理解しているんですけれども、その辺については、区としてどのように判断をされているのかお伺いしたいと思います。","respondent":"古里学務課長","answer":"全国的なレベルで申し上げますと、都市部においてかなり就学援助率が高くなっているということは承知しています。東京都の２３区の中でいきますと、品川区の認定率についてはやや中位より下というところかと認識しています。","id":"exchange-038"},{"speaker":"三村委員","kind":"質問","question":"２３区の中では中位より下ということですけれども、全国平均に比べると就学援助率は高いと思うんです。問題点等を利用者から改善をしてほしいという声は届いているのかどうか、その辺についてお伺いしたいと思います。","respondent":"鷹倉区民課長","answer":"利用者の実績の部分ですけれども、２３区全体で言いますと、どちらかというと品川区は基準が教育的配慮という部分で実績は多いほうです。十分教育的な配慮という点から、経済的な困窮度も取り入れてありますけれども、教育的配慮ということで貸し付けを行っているという状況です。","id":"exchange-039"},{"speaker":"三村委員","kind":"意見","question":"親の収入と子どもの学力を連動させないためには、奨学金制度の貸付額を高くしたり、制度の充実をさらにしていくべきではないかと思うんです。私立幼稚園への補助金額は、品川区は大体４億円ぐらい使われていると思うんですけれども、ぜひその辺の充実をとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"大沢委員","kind":"質問","question":"９１ページの東急目黒線連続立体交差事業費、１０８ページの住居表示管理事務費を伺います。そして東京都の事業ですけれども、５億９,０００万円余という補助金について、パーセンテージはどのぐらいのものか説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"今年の分については合計がございませんが、全体に占める割合といたしましては、都側が８割ぐらい、そのうちの品川区側が２割５分ぐらいが全体的な事業費に対する負担の関係、それに対する今回の歳入となっています。","id":"exchange-041"},{"speaker":"大沢委員","kind":"質問","question":"私もあまり数字がわからないのですけれども、都が８割ということで、あとの２割がわからなかったんですけれども、説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"総額が８７０億円程度ということでございまして、都側で８割程度を負担しているということです。そのうちの４分の１程度を品川区が負担をしていて、それに見合った金額が歳入として入っているです。","id":"exchange-042"},{"speaker":"大沢委員","kind":"質問","question":"質問を変えます。どのように隣の区と連携が取られているかというのが、全然浮かんでこないのですが、どのような面で連携を図られているのか説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"目黒区の４者でやっているものですので、当然品川区の区域に対する仕事量に応じて、連続立体事業の負担額が変わってくるです。しかし、一方では、目黒区は目黒区側の、特に西小山駅を中心としたまちづくりについて負担しているです。","id":"exchange-043"},{"speaker":"大沢委員","kind":"質問・要望","question":"時代の移り変わりとともに、近年ではいい悪いは別にして懐古趣味といいますか、昭和３０年代の生活をもとにされた映画などもはやっております。地域に愛着を持たせるという意味では、旧町名を復活させる議論を区で行われているのかどうか、教えてほしいと求めました。","respondent":"新美企画部長","answer":"私からご答弁を申し上げますと、確かに昭和３９年にわかりやすい住居表示にされまして、旧町名が住居表示に生かされなかったことはあります。今後も適切な形で活用して、誇りにしていく、そういった活動を行っていくです。","id":"exchange-044"},{"speaker":"大沢委員","kind":"質問","question":"今はルール違反ですので、款別のときに合ったときに、また質問をします。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"若林委員","kind":"質問","question":"私は成果報告書７５ページの区民住宅のうち借上型区民住宅を中心にお伺いをします。都補助金と入っておりますけれども、全体的な体系、また今後の借上型区民住宅の計画についてもお知らせほしいと求めました。","respondent":"齋藤住宅課長","answer":"平成１６年度、１７年度に区が中心になりまして、区長会要望という形で国に要望をいたしました。国土交通省の予算の概案の中で、そういった国の動向を注目しながら、区として対応を考えていきたいと考えています。","id":"exchange-046"},{"speaker":"若林委員","kind":"質問・要望","question":"私の第一の疑問の家賃が高い、傾斜家賃については国へも要望しているということを聞きました。お聞かせ願うとともに、今後２０年を区切りに、その後の借上型区民住宅はどのようになっていくのかお知らせほしいと求めました。","respondent":"齋藤住宅課長","answer":"今後、借上型区民住宅につきましては、新たに借り上げる計画はございません。２０年の契約期間が終了いたしましたら、契約満了とともに、基本的には借り上げた区民住宅は公の施設ではなくなるということで考えてあります。","id":"exchange-047"},{"speaker":"若林委員","kind":"質問","question":"入りたくても入れない、空いているのに入れないという状況があります。この空き家が目立つのはどのような理由なのか、傾斜家賃というのはお聞きしましたけれども、ほかの理由についてもお知らせ願いたいと思います。","respondent":"齋藤住宅課長","answer":"その結果、設備が古いあるいは外観が気に入らない、あるいは日当たりが悪いといったような、３住宅については個々の特殊な事情があります。入居募集にあたっては、品川宅建管理センターに入居させたら１カ月分のインセンティブをお支払いするという仕組みも取り組んでおりますが。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"本区としても、国へ制度の改善要望をしているということ。これは国の制度ですので、当然各部屋が経年によりまして劣化していくわけですから、当初の設定より下げていくという交渉の努力はされているのか尋ねました。","respondent":"齋藤住宅課長","answer":"今のところ考えてございませんが、さまざまな施策を組み込みながら、一定程度上乗せ補助というのも検討しながら入居対策について考えてまいります。引き下げの交渉ですけれども、引き続きオーナーの方と交渉いたしまして、引き下げに向けて努力してまいります。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問","question":"引き続き交渉していくということですので、これまで既に交渉を行っていると理解いたしました。受けた方がいらっしゃるのか、それともどうしても受けてくれないのか、ご答弁をお願いします。","respondent":"齋藤住宅課長","answer":"そのうち１住宅については、オーナーの方が引き下げ交渉に応じていただきまして、満室になっております。残りの３住宅につきましては、オーナーの方の事業資金の返済計画等々の事情もございまして、承諾をいただけない状況です。","id":"exchange-050"},{"speaker":"若林委員","kind":"質問・要望","question":"区の交渉、また区が制度の改善要望をされている中で、今後２０年ですので、まだ先があります。今後、区の持ち出しの実態が出てくると思いますが、この辺の推移、試算をどのようにされておりますか尋ねました。","respondent":"齋藤住宅課長","answer":"賃料は大体４億４,０００万円ぐらい、あとは国や都の補助金がありますので、区が一般に持ち出している金額は３,０００万円強です。空き家が増えてきますと、今後一定の負担も検討しなければならないと思いますけれども、大きな財政上の点については心配ないと考えています。","id":"exchange-051"},{"speaker":"若林委員","kind":"質問・要望","question":"現在３,０００万円強、年々持ち出しが増えていくということで、歳入としての借上型区民住宅の問題点を一つ指摘させてほしいと求めました。最後にもう１点、今後一層の努力をどのような改善の努力をされていくか、ご答弁をほしいと求めました。","respondent":"福田まちづくり事業部長","answer":"区といたしましてはこれまで最大限と申し上げていいぐらい、家賃の賃下げ交渉ですとか、さまざまな工夫を凝らしてまいりました。この問題は早急に解決する必要があると認識しておりますので、今後とも最大限の努力を図ってまいりたいと考えております。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"私から５９ページの歳入、特別区民税について伺いたいと思います。伺いたいのは、税制改正によるものはどういうものか、金額などをご説明ほしいと求めました。","respondent":"太田税務課長","answer":"そのことを踏まえまして、当初予算としては確か０．1％ほどの増収を見込んでいたところです。この部分については、当初予算で見込んでいるところです。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問","question":"品川区は納税義務者が増えたことをどのように見ているのか伺いたいですけれども、そういった方々が多く入っているのではないかと思うんです。今後の見込みですけれども、平成１８年度は納税義務者の税収はどのような変化を見込んでいるのか説明を求めました。","respondent":"太田税務課長","answer":"現実に、平成１７年度の予算ですから、平成１６年の収入に対して税額のフレームが決まります。平成１６年度が９２.０３％ですから、１.２５％徴収率がアップしているということを見ると、やはりお金は動いているのかなと見ているところです。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"そもそも固定された税金が上がるわけですから、品川区の税収が上がっているから景気もよくなっているという見方はどうなのかと思います。そこがおかしいと思いますけれども、いかがか尋ねました。","respondent":"太田税務課長","answer":"平成１８年度の状況ですけれども、現在の調定で約３３０億円、さらに当初予算に比べて約１８億円ほど増えてくるという見込みでおります。今後の景気動向は楽観論もあれば悲観論もあるわけですから、原油高等いろいろな状況があると…","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"さらに定率減税の縮小廃止で１０億円、それは翌年は完全廃止ですから２０億円。ぜひ働く者や高齢者、増税負担増にあえいでいる区民から絞り上げた税金を負担軽減に充てるべきではないか、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"なかなか税収の先の見通しを立てることはできませんし、今一時的に税収が上がったからといって、先々もそのまま右肩上がりでいくとは限らないのです。安定的な財政運営、区政運営を図っていくという視点で、品川区としては取り組んでいるところです。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"税制改正で高齢者の課税、これは一時的なものですか、違いますね。国に対して増税をやめていただきたい、せめて区民の生活実態を伝えることをやって当然ではないかと思いますけれども、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"それから、一番基本的なことですけれども、これからの少子高齢化社会にどう対応していくか。５０年あまりにわたっていろいろな措置が取られてきましたが、社会経済が変わって、この間の国の税制改正等も出てきていると私どもは理解しています。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ増税負担増に苦しむ高齢者や障害者、働く者の立場に立って、負担増を国に対してはっきり中止を求めるべきではないかと思います。なぜ、国に対して求める気持ちがないのか、それだけ最後に教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"基本的には、地方分権推進の立場に立って、区は区独自の立場で今の行政サービスの拡充を図っていく。この辺の基本的な姿勢には変わりございません。","id":"exchange-058"},{"speaker":"伊藤委員","kind":"質問","question":"お伺いしたいのは、今年度は総合区民会館使用料と出ていますけれども、おそらく来年度は出てこない。そのことについての対応、それから品川区では議会に対して、このことについてどうやって知らせていくのか説明を求めました。","respondent":"日下部企画財政課長","answer":"指定管理者制度が導入されまして、利用料金制度という形を取りますので、確かに平成１８年度の決算書の中から項目が除外される形になってまいります。その辺はどういう形で議会にお諮りするか…","id":"exchange-059"},{"speaker":"伊藤委員","kind":"確認","question":"指定管理者をどんどん出していけば、私たちに見せる機会が少なくなるわけですから、そのことについての対応をぜひ後でしっかりお聞かせください。つまり、こういうことについてはすべてそこで受け付けますという確認をここでいただければありがたいのですが、いかがか尋ねました。","respondent":"山田区民生活事業部長、鷹倉区民課長","answer":"先ほど、総合区民会館の会計等の報告については、従来からも区の監査を受け、それぞれの報告書ということで議会にご提示をしています。利用料に関する記載については工夫をしてまいりますけれども… 私どもは指定管理者と定期的に打ち合わせ等をしている状況もありますので、その中でそういう声をきちんと伝えて、区民の方々に安心して利用していただけるようにしていきたいと考えています。","id":"exchange-060"},{"speaker":"伊藤委員","kind":"質問","question":"ものづくり創造センターに関しては、非常に利用率が低いということを前にも質問をいたしました。たまたま、お伺いしたいのはものづくり創造センターの利用率と利用実態等がわかりましたら説明を求めました。","respondent":"金子産業振興課長","answer":"ものづくり創造センターは、現在のところ三つの団体にお貸ししております。(株)近隣システム研究所という三つの団体にお貸しして、使用料をいただいているところですので、現在の利用率ということでは１００％です。","id":"exchange-061"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認したいのが、東京都のグラウンドの代替案についてお聞かせほしいと求めました。それから、品川区独自の八潮北公園の野球場を含めたグラウンド代替施設の考え方について、説明を求めました。","respondent":"阿部都市計画課長、藤田道路公園課長","answer":"代替の施設ですけれども、今、東京都と協議しているのは港湾局所管の品川南ふ頭公園です。これにつきまして、東京都から区が移管を受けて、その後に野球場を含めた整備をしていこうということで検討しています。 現在ある品川区のグラウンドの有効活用の面ですけれども、現在私どもが管理している八潮北野球場について、早朝からの利用について検討を進めているところです。","id":"exchange-062"},{"speaker":"伊藤委員","kind":"質問・要望","question":"二面、区内のチームの方々から運営に支障があるということをいろいろ聞いていますので、もう少し踏み込んだ対応をお聞かせいただきたい。やはり千数百チームの利便性の向上のためには、そのようなところまで踏み込んだ対応をしていくべきと思いますが、考え方をお聞かせくだい。","respondent":"松代管理工事課長","answer":"一般の利用も早朝から夜間までできるということで、利用枠を広げることによって利用者の方に広く使っていただければと考えています。隣接する土地を港湾局からさらに購入させていただきまして、野球場としての面積を確保して整備してまいりたいと考えているところです。","id":"exchange-063"},{"speaker":"山村委員","kind":"質問・要望","question":"今後考えるべきだと思いますので、現状ではどのように思われているか、もし何かやられていたら教えていただきたい。今後やるような考えはあるかどうか、しながわ水族館もやれると思いますが、そういうことを教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"いろいろ工夫を凝らして増収の取り組みを進めているところですが、現時点では具体的な検討を進めている状況ではございません。ほかの事例なども含めながら、今後の検討課題ということで進めさせていただきたいと思います。","id":"exchange-064"},{"speaker":"山村委員","kind":"質問","question":"その辺をどう考えていくか、これは文化的な部分も含めていると思うので、その辺の基準をある程度考えてからでないと難しいと思います。現在、このように払われていない方に対して、例えば保育園などはどういう対応をされているのか教えてほしいと求めました。","respondent":"小林保育課長","answer":"既に、９割以上が口座振替の対象になっておりますが、翌月に催告等を行いまして納付していただくように対応しております。それにつきましては、毎月電話での催告あるいはご訪問をする等の対応によりまして、徴収率の確保を行っているところです。","id":"exchange-065"},{"speaker":"山村委員","kind":"質問","question":"私が聞いたことに答えていただいていないのがあったのですけれども、大体わかっているつもりですが、時効完成分と執行停止即時消滅分の意味を詳しく教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"ただ、収入未済額が納入される見込みがないような状況になった場合については、これに基づいて滞納整理の処理をするということになっております。例えば、そういう形で滞納不納欠損処分についての具体的な手順が定められておりまして、これに沿って対応させていただいているです。","id":"exchange-066"},{"speaker":"山村委員","kind":"質問・要望","question":"先ほどお伺いした、例えば保育料を払われていない方はどうされているのか、そのまま通われているのか、どういう対応をされているのか。当然、徴収努力はされていると思うんですけれども、ずっと払わない人が保育園に通われているのかどうか、そこを教えてほしいと求めました。","respondent":"小林保育課長","answer":"保育料の徴収ですが、もちろん毎月納めていただけるように訪問、電話、催告等を行っております。最終的にどうしても支払いの誠意が得られない場合には、給料等を含めまして差し押さえという形で徴収する体制で取り組んでおります。","id":"exchange-067"},{"speaker":"山村委員","kind":"質問・要望","question":"徴収するというのはわかりますが、要するにそれで保育園に来ているのか来ていないのか。給食で言えば、給食を出しているのか出していないのかという、その辺のことを教えていただきたい。","respondent":"小林保育課長","answer":"確かに、諸々の事情で納めていただくべきものを納めていただけないケースがあることは事実です。だからといって保育に欠けるこどもに対して、相いれないところはありますので、引き続き保育を継続することに変わりはございません。","id":"exchange-068"},{"speaker":"山村委員","kind":"質問","question":"言い方が難しいですけれども、もう少し厳しい対応を取るべきではないかと思うことがありますので、一線を決めておいたほうがいいと思います。お金があるのに払わない人がいると考えればの話ですけれども、その辺のことはどう思われているのか教えてほしいと求めました。","respondent":"小林保育課長","answer":"事業を進める場合に、今後も滞納分の徴収率の確保等には、今まで以上に一層努力をしてまいりたいと思います。前年度は１４.４％ほどでございましたけれども、１年間努力をさせていただいた結果、今年度は１９.９％と若干の向上は図られております。","id":"exchange-069"},{"speaker":"中島委員","kind":"質問・要望","question":"そういう視点から、今日も少しですがその一端を質問させてほしいと求めました。高齢者住宅は１１月頃に申込みがあって、今年は前年に比べて早く入れる方が多いと感じているんですが、応募者の倍率はどのぐらいか尋ねました。","respondent":"冨岡高齢事業課長","answer":"平成１８年度につきましてはこれからですが、平成１７年度の状況ですと、申請が１６３件、空き家の入居が１８戸でございまして、倍率が９.１です。ちなみに、前年度は申請が１７３件、空き家入居が１６戸でございまして、１０.９でございましたので、１.８ほど下がっておりま…","id":"exchange-070"},{"speaker":"中島委員","kind":"質問","question":"以前、確か区として高齢者住宅は今後はつくらないというお話を伺ったような気がするんですが、その考えは今後も変わらないのかということ。これから２０１５年には４人に１人が６５歳以上と言われている中で、その辺のお考えを説明を求めました。","respondent":"冨岡高齢事業課長","answer":"あわせて、あっ旋等の事業も利用していただいて進めてまいりたいと考えています。制度として２人世帯の高齢者住宅については、残念ながら考えておりませんが、宅建業者をご紹介することも考えております。","id":"exchange-071"},{"speaker":"中島委員","kind":"質問","question":"質問を移らせていただきますが、区営住宅の場合も、５階建てのところでエレベーターが幾つかついたと思うんです。ただ、今後区営住宅にエレベーターを設置するかどうかという予定はあるのか尋ねました。","respondent":"齋藤住宅課長","answer":"残りの区営住宅には、残念ながら設置できません。エレベーターを設置した場合、エレベーターをつけるにはなじまないということでございまして、今後エレベーターを設置する計画はございません。","id":"exchange-072"},{"speaker":"中島委員","kind":"質問・要望","question":"ですから、体をふいてもらって過ごしているという方もいらっしゃいます。例えば道路を補修できなくても、今回は問題点だけを投げかけて質問を終わらせてほしいと求めましたが、総合的にお答えをほしいと求めました。","respondent":"松代管理工事課長","answer":"そういったご相談、申請等かありましたら、私どもはなるべく申請に沿って速やかに対応できるように区民の側と話をしています。今後も、そのような形で進めていきたいと考えているところです。","id":"exchange-073"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"私から７２ページの使用料及び手数料についてお伺いをさせてほしいと求めました。そのときに四つの課題、この４点についてお伺いしたわけですけれども、あるいは今後の方向等々についてお伺いをさせていただきたいと考えています。","respondent":"日下部企画財政課長","answer":"平成１８年度は１４種で６２施設ということで、新規で利用料金制を導入するという形を取りましたのはきゅりあんの１カ所です。平成１７年度決算はこのような形で出ておりますが、平成１８年度はこの項目は除外されると、決算書上はそういう取り扱いになるです。","id":"exchange-074"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"先ほどの金額を入れての推移、今後の方向はどうなるかお伺いしたのですが、この次のところでお答えをいただきければと思います。積算を踏まえた形で、どう考えて今後の中で使用料として設定していくのか、お答えほしいと求めました。","respondent":"日下部企画財政課長","answer":"先ほど考え方は３割ということを申し上げまたけれども、六％ぐらいというところで、目標を若干上回っている状況には変わりございません。基本的な考え方は、先ほど料金設定の考え方で申し上げましたように、施設の建設コストそのものは料金設定の中には加味してございません。","id":"exchange-075"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"今後の改定の予定があるのかないのかお伺いしたいと思います。今後の中ではどういう形で見直しをかけていくのかあるいは予定があるのかないのか、そこをお聞かせほしいと求めました。","respondent":"日下部企画財政課長","answer":"先ほども申し上げましたけれども、社会経済の動きをにらみ合わせながら、どうしていくかということが基本です。２３区共同歩調でそういう取り組みをしているとか、基本的な考え方としましては、これから取り組んでいく課題ではないかと考えております。","id":"exchange-076"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"上げることが区民サービスにつながらないということもないわけですから、今後の中でなるべく早くバランス性を考えた形で考えていただければと、要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"井上委員","kind":"提案","question":"決算特別委員会では、こういった資料は図書館にも閲覧用として置かれているわけですから、そのことがわかればいいと思っています。そして、そのことを聞こうとすると、内容を逐一職員の方に伺わなければいけないという流れの中で、全然市民にも見えてこないとの意見を述べました。","respondent":"日下部企画財政課長","answer":"例えば、この冊子をご覧いただいて、「ご理解ください」と言っても、なかなか難しいところがあろうかと思います。そういう努力をしてきているところですし、今後ともご指摘を受けとめて、改善の努力はしてまいりたいと考えています。","id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"表記を変えるとか、小さな字にするとか、いろいろな工夫をもって検討していただければいいと思います。成果報告書の内容について、成果報告書に書かれる内容は何か政策的な意図をアピールしたいとか、何か考え方があるのかどうかお聞きしたいと思います。","respondent":"日下部企画財政課長","answer":"表記の問題については、基本的には、決算の中身についてより客観的かつ公平にご理解いただくですので、事実を事実として整理をさせていただいているということでございまして、あまり政策的な意図ということで考えているわけではございません。","id":"exchange-079"},{"speaker":"井上委員","kind":"意見","question":"例えば７３ページの使用料のところで、衛生費に書かれている二段目の性病相談６件１,２３０円というところが、その辺は何かありますかとの意見を述べました。","respondent":"日下部企画財政課長","answer":"平成１６年度は実績がありませんでした。平成１７年度に６件ほど実績が出てまいりましたので、これを決算書の中に明記したというものです。","id":"exchange-080"},{"speaker":"井上委員","kind":"質問","question":"平成1４年から１０年間の時限立法としてこの辺から予算が計上されているわけですが、あるいは交付金ですから裁量枠が広いと思うんですが、どのような事業に使われているのか説明を求めました。","respondent":"小林保育課長","answer":"次世代育成支援対策交付金の件ですけれども、この間一般財源化する中で、新しい補助制度として整備されているところです。次世代育成支援対策施設整備交付金につきましては、具体的に本決算におきましては、荏原保育園の大規模改修等が交付対象となっております。","id":"exchange-081"},{"speaker":"井上委員","kind":"確認","question":"そうすると、今まで交付金がないときにも、病後児保育等で使われていた一般財源が交付金で賄えるようになったということが１点。これは１０年間、こういった形で継続して収入として見込まれるものなのか確認をさせてください。","respondent":"小林保育課長","answer":"次世代育成支援対策交付金につきましては、病児保育あるいは延長保育につきましては、従前の特別保育事業補助金の代替としてつくられているです。５年、１０年と安定的に制度が残置されるかどうか、現段階では確信を持っていない状況にあります。","id":"exchange-082"},{"speaker":"井上委員","kind":"質問","question":"そうしますと、こういった交付金については政策的支援、あるいはこの交付金は経済的支援、例えば認証保育園などの経済的支援といったものに流用できるものなのか、交付金の性格はいかがか尋ねました。","respondent":"小林保育課長","answer":"こちらの交付金は、基本となる保育事業に対して、先進的あるいは誘導的手法として整備する点が視点としてあると解釈しております。都の認証保育所制度自体が都の認定ですので、基本的に別な都単独の補助金、認証保育所運営助成金での対応となっております。","id":"exchange-083"},{"speaker":"井上委員","kind":"質問・要望","question":"具体例が悪かったのですが、認証保育所でもなくて、子育て世代の方々が同じように経済的支援も一方で求めているところで、保育園のハードとか事業の拡大とは別に、こういうものが流用できるのか、経済支援として流用できるものなのかということをお伺いしたいと思います。","respondent":"小林保育課長","answer":"次世代育成支援対策交付金につきましては、先ほど申し上げましたように極めて補助対象が限定されているメニュー方式になっておりますので、委員ご指摘の経済的な部分の制度創設等には対象にはならないと考えております。","id":"exchange-084"},{"speaker":"井上委員","kind":"質問・要望","question":"そのことを地域におろして、そしてまたそこで意見を聞きながら計画を図って実行していきたいとお話しをいただきました。そのような形で、本当に現場の人たちに合ったサービスというところで、ぜひ施策を進めていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"沢田委員","kind":"意見","question":"介護の先進区だということを言いながら、そのような趣旨の話をおっしゃっていたようですけれども、それで間違いないかどうかということ。先進区だというのなら、例えばグループホーム…","respondent":"濱野区長","answer":"高齢者福祉においても、施設をつくったり、それをきちんと運営していくためには、それなりの財政力の裏打ちがなければできないわけです。つぶさに２３区比較をして申し上げたわけではありませんけれども、あるいは介護保険のありよう、そういうふうに思っております。","id":"exchange-086"},{"speaker":"沢田委員","kind":"質問","question":"高齢者福祉を充実したいということは、その反省の上に立ってのことなのかお尋ねしたい。それから、入所待ちをしている所得階層別の分析をされているなら、教えてほしいと思います。","respondent":"蓼沼高齢福祉課長、濱野区長","answer":"４５０名の中身につきましては、基本的に施設ですので、要介護１以上の人が対象になります。基本的にお断りをしないですべてお受けしておりますので、要介護１とか要介護２の軽度の方を含めて４５０名が申込みをされているという状況で… それからもう一つは、品川区の場合は、他区に比べて非常に早い段階で特別養護老人ホームをつくって対応してきた。老人保健施設、どれか１点で全部をくくってはかるということではなくて…","id":"exchange-087"},{"speaker":"沢田委員","kind":"質問・要望","question":"それに比べて、品川区は介護の先進区だと言いながら、私どもが町中に入ると、特別養護老人ホームに入りたいという人が本当に多いですから。４５０名が待っている特別養護老人ホームこそ最大のニーズだし、緊急性が求められていると思いますけれども、その点はいかがか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"基本的には、先般の本会議でも部長が答弁したとおりで、今のところ基礎的な部分については充足しているという認識です。今後も、そういう方向で進めていきたいと考えております。","id":"exchange-088"},{"speaker":"沢田委員","kind":"質問","question":"お尋ねしますけれども、要介護４で住民税非課税、相部屋の場合、特別養護老人ホームは月額幾らかかりますか。それからもう一つ、ケアホームの場合、同じ介護度４で今の条件で、一体幾らかかるのか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"特別養護老人ホームですけれども、８万２,０００円です。ケアホームが約２０万円です。","id":"exchange-089"},{"speaker":"沢田委員","kind":"意見","question":"２８万円を払える人は、民間の有料老人ホームに入れる人たちだと思うんです。６年間も苦しんでいる人をそのままにしていくのか、特別養護老人ホームをつくって入所の備えをするのか、どちらが緊急度が高いか聞かせてくださいとの意見を述べました。","respondent":"木下福祉高齢事業部長","answer":"これが個室対応になれば２を切る状況でないと、おそらく本来あるべきサービス体制は取りにくいと思います。やはり今後の一つの方向として個室対応ということを考えたときに、やはりケアホームとかグループホームが選択肢だろうということが基本であります。","id":"exchange-090"},{"speaker":"沢田委員","kind":"質問","question":"要介護で寝たきりの人を入れれば２８万円、リーズナブルと言いましたけれども、それは福祉の充実をやるべき地方自治体の任務なのでしょうか。今すぐやるべき緊急度の高いことなのか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"今回、小規模多機能居宅介護などの新しいサービスメニュー、それから夜間対応の訪問介護、そういう事業も今回新しく始めてまいります。そういう中では、在宅の部分については極力厚く対応をするという考え方に立っております。","id":"exchange-091"},{"speaker":"本多委員","kind":"質問・要望","question":"それから、大崎第一地域センターが平成１６年度から複合施設に移転されて、かなり多目的な使い方ができるようになったと思うんです。いいことだと思っているのですが、その辺の状況について説明を求めました。","respondent":"田村地域活動課長","answer":"現在の第一地域センターは６室ということで分母が増えました。平成１７年度で６０.１％、平成１８年度９月現在までの利用率が６４.０％ということで、さまざまな方に利用していただいているというのが現状です。","id":"exchange-092"},{"speaker":"本多委員","kind":"確認","question":"今度、平成２１年度内に竣工される大崎駅西口中地区再開発事業によりまして、無償譲渡での移転計画があります。その確認の意味でお聞きしますけれども、区民の公平感というところの使用料の考え方をお聞きします。","respondent":"田村地域活動課長","answer":"現在の大崎第二地域センターは５２２m2ほどですので、今のところ約６００m2ほど移転先として考えられるです。先ほど来企画財政課長からご説明をしているように、ほかの地域センターと同様の金額算定でご利用をいただくという考え方です。","id":"exchange-093"},{"speaker":"本多委員","kind":"質問・要望","question":"民間の建物ですから、民間の考え方でやったのだと思います。当然運営は自主的に町会・自治会がやるべきことだと思いますが、やはり方向性も必要ではないかという思いから答弁をほしいと求めました。","respondent":"田村地域活動課長","answer":"町会長みずから入居者説明会に自分から出席して、自治会そのものが町会に入ってほしいということで、実際的に入っております。今、本多委員のおっしゃったような形を区としても支援しながら、町会の基盤整備に努めてまいりたいと考えております。","id":"exchange-094"},{"speaker":"本多委員","kind":"質問","question":"当然、できることとできないことがあると思いますが、積極的にお願いしたいと思います。１,０８４世帯が入居される計画がありますから、まず目の前にあるわけですから、もう一度お願いいたします。","respondent":"田村地域活動課長","answer":"先ほども申し上げましたが、新区長も強い決意ですので、私のほうもできる限りご支援させていただきたいと思いますので、よろしくお願いいたします。","id":"exchange-095"},{"speaker":"本多委員","kind":"質問・要望","question":"先ほどから出ています少子高齢化、子育て支援が各委員から出ておりましたが、関連いたしまして１点だけ聞かせてほしいと求めました。聖域でなくていいと思いますので、社会全体で対応していく展開について、最後に説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"これまで品川区といたしましても、仕事と子育ての両立支援のほか、在宅の子育て支援、いろいろ総合的に進めてきました。次世代育成支援対策推進行動計画が法で義務づけられまして、区としても計画をつくって進めているわけです。","id":"exchange-096"},{"speaker":"木下委員","kind":"質問","question":"６０件の診断があって、２８件の改修を今、４件の改修補助の申し込みがあった。それを先にお聞かせ願えますか。","respondent":"片田建築課長","answer":"私ども、東京都および国の考え方の中で、これまで個人資産への支援ということについての考え方をいろいろしてきたところがあります。荏原地区を中心に考えてありますので、それとあわせて、そういう制度として立ち上げてきているという状況です。","id":"exchange-097"},{"speaker":"木下委員","kind":"質問","question":"それと、先ほどエリアは荏原地区を考えておりますのでということのご発言がありましたけれども、はっきり確定していないんでしょうか。ここが対象になっている、対象になっていないと確定しているか、もう一度お聞かせ願えますか尋ねました。","respondent":"片田建築課長","answer":"その中で、エリアについては先ほどの７.７ｋm2ということで確定しています。ただ、わかりやすく地図等々についてもホームページ等を活用して掲示させていただいて、区民の皆さんに十分周知してまいりたいと考えています。","id":"exchange-098"},{"speaker":"木下委員","kind":"質問","question":"それからまた、どういう業種からいただいているのかですとか、おわかりになりますでしょうか。どのぐらいの規模なのか、金額と、そういう部分がわかりましたら、教えていただけないか尋ねました。","respondent":"日下部企画財政課長、中川原広報広聴課長","answer":"例えば教育委員会で小中一貫校の教育のカリキュラムを平成１７年度、１万部発行ということで、これが一定の額入って来ております。それ以上の具体的なものというのが正直言いまして、今のところちょっと上がってきていないんですが… 広告を載せております業者ですが、広報紙、それから「ふれあい」等々は区内事業者を中心とした事業者の方に広告を載せていただいております。さらに全国区のメディアになっておりますので、大学等々…","id":"exchange-099"},{"speaker":"木下委員","kind":"質問・要望","question":"財政的にどうなのかなというのもありますので、新しいそういう収入の確保について、これからもご努力していただきたいなと。４つか６つつくったらどうかという話があったように、そういうまた新たな運動論を展開していかないと、そこら辺のご認識としてはいかがか尋ねました。","respondent":"濱野区長","answer":"やり方はさまざまあろうかと思いますが、当面はやはり従来続けてきた東京都との役割分担の話をしっかり詰めていくことが先決だろうと考えています。その線で進めていくべきと考えております。","id":"exchange-100"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうから１点だけ、確認といいましょうか、お尋ねをさせてほしいと求めました。平成１７年度の決算におきましては、４５万４,６５０円という歳入が計上されておりますけれども、その辺を一つ確認しておきたいと思います。","respondent":"田村地域活動課長","answer":"平塚橋会館は平成１７年の４月から集会所として、当初は葬儀をする、平成１０年６月１日に利用を開始いたしました。その後、施設全体の年間の利用率を見ますと、当初、平成１０年の６月から利用を開始して、全体４.９％、平成１１年が８.９％と。","id":"exchange-101"},{"speaker":"堺委員","kind":"質問・要望","question":"あるいは平成１４年の決算特別委員会のときにも、ぜひ利用率が高いので、そういう備品を取りそろえていただきたいということを要望いたしました。そういう経過があるんですけれども、今、ここでそういう必要な備品等については取りそろえてあるのか、ないのか、その辺について確認しておきたい。","respondent":"田村地域活動課長","answer":"平成１４年の決算特別委員会でもそのようにご指摘いただきまして、備品として平成１５年度にテレビ、整備しています。ビデオ、マイク等は無料でお貸ししますということで、早急に受付窓口のほうに一般の利用者から見えるように掲示したところです。","id":"exchange-102"},{"speaker":"堺委員","kind":"提案","question":"今は大丈夫ですよということなんですかね。提案させていただいた、その辺についてもきちっとしていただきたいと思うんですが、いかがか尋ねました。","respondent":"田村地域活動課長","answer":"ただいま申し上げましたように、指導を徹底していきたいと考えております。","id":"exchange-103"},{"speaker":"石田委員","kind":"質問・要望","question":"私は成果報告書の確認をしたいことがあるので、８５ページの外国人登録事務費になるのかと考えていますが、区民住宅使用料借上型から伺います。法的に何か突破口が見つかって、行けそうだということで理解をしていいのか、その２点を確認させていただきたい。","respondent":"齋藤住宅課長","answer":"したがって、入居者に対する家賃補償がなくなりますので、１６万円から１８万円の住宅になってしまう。補助するというような取り組みがありますので、どのような工夫ができるかについて、改めて検討させていただきたいというものです。","id":"exchange-104"},{"speaker":"石田委員","kind":"質問・要望","question":"オーナーとかもいらっしゃるわけですから、もちろん７年後というのはわかっておりますが、対策を練っていくという理解でいいのか。例えば高齢者をそういう形で入れていくということが制度の中で大丈夫なのかというところだけ確認をさせていただきたい。","respondent":"齋藤住宅課長","answer":"引き続き枠の中でできるかどうかについては、都や国と協議をしながら頑張って、空き室を少なくするように進めてまいります。その部分はオーナーに減額を求めるだけじゃなくて、区が新たに財政支出をすることの可能性についての検討です。","id":"exchange-105"},{"speaker":"石田委員","kind":"質問・要望","question":"それから先ほどの部分なんですが、これは私はちょっとよくわからないので、これも教えていただきたいのですが、これは法定受託事務だと考えています。それから品川区で言うのであれば、改めてどこの課が法定受託事務をやっているのかということを教えていただきたい。","respondent":"日下部企画財政課長","answer":"４割程度は法定受託事務として残ったわけでありますけれども、自治法の中で、具体的に列挙されてあります。ですから、大体そういう意味では区民生活事業部が所管している事例が大半です。","id":"exchange-106"},{"speaker":"石田委員","kind":"質問・要望","question":"区民の役に立つ施策はどうだということを考えて、職員の方も頑張ってくださっているんだろうなと、私は思っております。どういうふうにしていくんだということ、指導をどのようにしているのか、そこら辺の考え方を教えていただきたい。","respondent":"榎本人事課長","answer":"その中で区の職員としましては、その窓口事務の中できちんと対応ができる、そういう職員の能力というのはかなり大事なものではないかと考えています。説明ができて、区のどこの職場に行っても大事なものだと考えておりますので、職員の指導・育成をしていきたいと考えています。","id":"exchange-107"},{"speaker":"石田委員","kind":"質問・要望","question":"国、地方自治法があるわけですけれども、その部分で国は例えば小さな政府、それで国家公務員も非常に少ないわけです。そういう話を私は持ち上げていくべきだと思うんだけど、そこら辺の点の考えについて教えていただきたい。","respondent":"濱野区長","answer":"ただ、これは現実の問題として、法定で受託をされているということですから、それを覆すということは非常に難しいだろう。国の地方事務という考え方も成り立つわけですから、今の段階で現実、お返ししますということにはならないと思います。","id":"exchange-108"},{"speaker":"石田委員","kind":"質問・要望","question":"それで１つだけ確認したいんです。そういうことを一歩先んじなければだめだと思うんだけど、そこら辺の話し合いができているのかどうかだけ確認をさせていただきたい。","respondent":"片田建築課長","answer":"国の制度としては、平成１７年に補助金を統合するなどして整備してきたと。私どものほうも２３区の課長会等の議論の中で、都のほうとしても、やはり整備地域を中心にということの状況でございました。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"１９８ページのこれは決算の状況一覧表、ここにもＤになるんでしょうか、ここは０ではないんですね。３億円というのは誤差範囲という解釈でよろしいのかどうかを教えていただきたい。","respondent":"日下部企画財政課長","answer":"ところがこれは冒頭ご説明させていただきましたように、基準を統一して、比較できるようにすると。自治法の中で明記されております継続費とか、平成１７年度に積み残したもの、実は職員が１人亡くなりました。","id":"exchange-110"},{"speaker":"西本委員","kind":"意見","question":"先ほどの３億円何がしかのずれというのは、いずれにしても、いつかは合わせる形になってくるのか。ちょっと３億円というと、１,２００億円の予算においては、その帳尻はどうなっているのかなとの意見を述べました。","respondent":"日下部企画財政課長","answer":"ところがそれがいろいろな事情の変更もあって、その最終補正で見込んだ段階から、どうしてもその辺との多少のずれが出てくる。最終的に決算対応という形にならざるを得ませんので、ものによって金額の幅はありますけれども、出てこざるを得ない。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"いろいろと努力をされているということはお聞きしているんですが、どうしてそうなってしまうのか、納められないのか。それから適切な指導というのはされているのかどうか、どこまでできているんだろうかということについてはいかがか尋ねました。","respondent":"小林保育課長","answer":"具体的には、在園中の方につきましては、園のほうへ出向いて、お子さんを引き取りにくるときに、いろいろな相談も含めて対応しています。その辺はよくよくお話を聞く中で、一括が無理であれば、分割で納めていただく計画等も含めて対応しています。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"次に７１ページの保育料についてですが、保育料の収入は去年からでしょうか、夜間保育の徴収の方法を変えたんですね。年収に応じてだとかという形で、それによって徴収額がどういう変動があったのかを聞きたい。","respondent":"小林保育課長","answer":"基本的には夜はご家庭でお子さんとスキンシップを図りながら、子育てしていただくということで、安易な保育にならないようにという趣旨もあります。基本的には夜間保育総体の実施状況といたしましては、横ばいないしは施設によっては若干減少傾向という形になっております。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"子どもにとってどうなのかという見地に立ったときに、そこは適正な保育料を考えつつ、方法をこれからも考えてほしいと求めました。交付金いろいろあるかと思うんですが、そういう形で変わってくるのかどうか、都と国の対応についてどういう動向があるのかをお聞きしたいと思います。","respondent":"市川庶務課長","answer":"すまいるスクール事業については平成１３年度にこの事業を始めてまいりましてから、開設後の運営費については、基本的に区の単独事業という取り扱いでしています。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"そうすると、これからも品川区として、そこの部分については一般財源から出していく、支出していくと。法制化されたかどうかあれですけれども、認知されるようになってきたときに、補助金等々が増えるとかという動きはないんか尋ねました。","respondent":"市川庶務課長","answer":"現在の国と東京都の補助制度で活用できるものはございません。さまざまな国や東京都の動向がありますので、私ども事業担当課としては、注意深くその辺を見ていきたいと考えています。","id":"exchange-115"},{"speaker":"西本委員","kind":"質問・要望","question":"それと同じような関係で、９ページの二葉幼保一元化施設費というのがあります。特に都になるんでしょうか、補助金等々のそういうのはあるのかないのか、お聞きしたい。","respondent":"小林保育課長","answer":"基本的には幼稚園に関する補助金、それから保育園に関する補助金、現行のフレームを基本として継承していくという形になっております。具体的な認定子ども園への移行時に都条例によって、その辺のフレームが確定するかと思いますので、その動向を注視してまいりたいと思います。","id":"exchange-116"},{"speaker":"西本委員","kind":"質問・要望","question":"現段階でわかっているところを教えていただきたいんですが、認定子ども園に指定される、多分品川区はあまり関係ないんじゃないかなと思うんですね。品川区においては、今後どういう期待を持っているのか、あまりそうではないのかというところはいかがか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"特には今までの制度の中で実施するというところでありますので、３園ある中では、都の詳細は見ないとわからないというところです。今年の７月にいろいろ調査がございましたけれども、民間が認定子ども園に変更したいとかという話はありますけれども、今のところ出ていない状況で…","id":"exchange-117"},{"speaker":"西本委員","kind":"質問・要望","question":"総合施設という意味で、公立保育園も発展しつつあるというところでは、都との関係をこれから注意深く見ていただきたいと思っています。最後に９６ページの保育園ＰＴＡ事業への負担金の中身はどういうものなのかを、まず教えてほしいと求めました。","respondent":"小林保育課長","answer":"申しわけございません。該当項目をもう一度。","id":"exchange-118"},{"speaker":"西本委員","kind":"質問","question":"９６ページの保育園ＰＴＡ事業への負担金というのが収入で入っていると思うんですね。これの内訳、どういう物がこの中に入っているんか尋ねました。","respondent":"小林保育課長","answer":"現在、基本的には各事業を実施する際の参加費という形で、おおむね事業にかかわる費用の２分の１相当分を割り返す形でご負担いただいている。個々の講演等を目的とするもの、あるいは子どもの指人形の劇ですとか、いろいろな催し物に属するものの経費の負担金の部分です。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと時間がなくなりましたので、歳出のときにもう一度挙げさせてほしいと求めました。それからあと保険に入っていないというところでは、ちょっと時間がありませんので、それは歳出のほうで聞きたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところをちょっと教えていただきたいんですが、補助金の関係は、学童保育とどう違うのかということについて教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"学童保育の補助金についてのお尋ねですが、学童保育については補助金等はございません。","id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"学童保育事業についても、運営費補助ということでは、東京都からは全く出ていなくて、区単独でやってきたということなんでしょうか。多分、そこのところはあったんではないかと思うんですけれども、そこのところ、お願いします。","respondent":"日下部企画財政課長","answer":"失礼いたしました。学童保育クラブにつきましては、補助金という形はとっておりませんが、財調算定の対象になっているです。","id":"exchange-122"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すまいるスクールに関しては、財調算定には当たらないということなんでしょうか。この全児童対策の中に放課後児童健全育成事業、学童保育事業が入っているということではないのかどうか、そこら辺のところについて説明を求めました。","respondent":"日下部企画財政課長","answer":"これは極端なことを言えば、ある区でそれを実施しようが実施しまいが、それは標準算定の対象として組み込まれているという形をとっているんです。標準算定されたものについて、それが一般財源でありますけれども…","id":"exchange-123"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところがちょっと学童保育事業とすまいるスクールのところでの算定が変わっているのか、それともすまいるスクールの中に含まれているのか、そこのところについて教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"ちょっと説明の仕方が悪かったかもしれませんが、２３区が押しなべて、それはあくまでも学童保育クラブの算定対象ということで入っているものです。２３区に配分されていると、さっき申し上げましたけれども、それはそういう意味です。","id":"exchange-124"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、今までの学童保育事業と、今回のすまいるスクールになったことによって、変わりはないということで考えていいんか尋ねました。","respondent":"日下部企画財政課長","answer":"財調の算定そのものは変わっておりません。","id":"exchange-125"},{"speaker":"土井委員","kind":"質問・要望","question":"前も１回お伺いをしたと思うんですけれども、廃止をされるとかとなってくるわけですけれども、それらの選択をしているんだと思うんですね。自治体議員も悪いんだと、我々が悪者になっているところがありますものですから、そこら辺も含めて聞かせてほしいと求めました。","respondent":"日下部企画財政課長、桑村総務課長","answer":"あるいはそれほど大きな変更がない場合は、これについては課長名での通知という形で、中身を市区町村に周知する。そういう仕組みがとられているということです。 東京都の回答とすれば、まだ応じるわけにはいかないというのが、今のところの見解です。引き続き努力するというようなことで、やってまいりたいと考えています。","id":"exchange-126"},{"speaker":"土井委員","kind":"質問","question":"補助金というのは何分の１か負担しなければいけないわけですから、必ずそういうことになっているわけですから、選択をする余地を持っていると。いいものはたくさんやってもらいたいと思うものですから、時々あるようですから、いかがなんでしょう。","respondent":"日下部企画財政課長","answer":"いろいろ議論があるところですけれども、先ほども出てまいりました三位一体改革で、補助金か交付金かということです。そういう基本的な姿勢がまず第一ではないかと考えます。","id":"exchange-127"},{"speaker":"土井委員","kind":"意見","question":"今、お話があったように、この補助金、補助制度というものの中身は何だろう。それにはもう一つ反対側に、そういう区民のほうのニーズをとらえる施策の思いのほうもしっかりと進めていただくようにお願いしておいて、やめますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-128"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そのあたりの決算書の作成の仕方を教えてほしいと求めました。この中で見ると、単純に計算すると、１人１０万円ぐらいの返還があったようになるんですけれども、それもあわせて説明を求めました。","respondent":"日下部企画財政課長、太田税務課長","answer":"つまり平成１７年度の段階で、財調の再調整の分も出てまいりました。あるいはどうしても当初の予定を超過したもの、充用するということでありまして、執行するわけではないんですね。 その部分が平成１７年度から出てまいりましたので、通常の過誤納金が１４７３件、それから株式の過誤納金が８０５件と言う内訳になります。１億２,３００万円が１件、それから２,７００万円が１件…","id":"exchange-129"},{"speaker":"林（宏）委員","kind":"確認","question":"平成１７年度は入っていたように記憶しているんですけれども、これだけ減っているというのも何か理由があるんでしょうから、教えてください。そういうところは１００万人とも言われている昼間人口を計算に入れると、べらぼうな数字になって、べらぼうな数字が行っているんか尋ねました。","respondent":"日下部企画財政課長、太田税務課長","answer":"どうしても都区協議が難航して、これがどうしても年度内解決の見通しも立たなかったものですから、最終補正に計上ができませんでした。結果としてそういう形になっているわけです。 ただこの３件については、いずれも確定申告に伴うものということで、当初からは想定できないものとご理解ください。平成１８年度については、３,０００万円ほど当初から予算を増額したです。","id":"exchange-130"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"最後に時間がなくなったので、要望にしますけれども、今、トップの経営会議を開くとしたら、区長１人しかいないわけですね。それだけ、お願いをしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-131"},{"speaker":"三上委員","kind":"質問・要望","question":"どうお考えになっていらっしゃるかということを含めて、７２ページの民生使用料とか、ちょっとお伺いをしておきたいと思います。既に区の理事者の方も確認されているはずなんですけれども、具体的に挙げますと、平塚橋会館の第５集会室の壁のところに大きくひびが入っている。","respondent":"日下部企画財政課長、齋藤住宅課長","answer":"基本的に平成２０年度までに耐震診断、それから耐震補強を完了させるという予定で、必死になって取り組んでいるところです。それにつきましては平成１９年度の予算編成等を通しまして、その辺の具体的な取り組みを進めて… ２０年の契約期間終了後の区民住宅ですが、その集合住宅ごとにそれぞれ個性がありますので、契約期間満了時点で判断をします。そのように考えています。","id":"exchange-132"},{"speaker":"三上委員","kind":"質問・要望","question":"時間の関係でこれ以上申し上げませんけれども、よろしくお願いしたいと思います。どちらにも適用するとお考えになっていくかどうか、区長、どうお考えになりますか。","respondent":"濱野区長","answer":"区が行政サービスをするについて、その対価をお支払いいただくか、あるいはいただかないかということによって、そのサービスの仕方とかに差があるものではありません。","id":"exchange-133"},{"speaker":"三上委員","kind":"質問","question":"むしろ１カ所でもいいから、荷物を置いてでもそういったことができるということをやってほしいんだという相談も、私のところにはあります。少しずつでありますけれども、そういった点についての取り組みの修正を図っていっていただけないかなということでお願いしますが、いかがか尋ねました。","respondent":"濱野区長","answer":"その辺について、仮にできないことであるということであれば、十分な説明を差し上げることは必要になってくるんじゃないか。それぞれの所管が区民の皆さんによくご説明を申し上げ、できるだけのことをサービスするという、これが基本の精神だろうと考えています。","id":"exchange-134"},{"speaker":"宮崎委員","kind":"質問","question":"高橋前区長も以前、今後２３区では自治体間の競争が活発になるという認識で、政策能力や執行能力を高める。認識というか、前区長の言う自治体間の競争が激しくなる中での運営がどういうふうにしてきたのかということを伺いたいと思います。","respondent":"濱野区長","answer":"要するに都と区の財源配分とは別に、２３区の財源配分をきちんとしているという、それがいわゆるシビルミニマムというか、共通のベースというふうに。品川区にとって、最も必要な施策に予算を投入するという点では、それぞれ２３区に２３の色があってしかるべきだと思います。","id":"exchange-135"},{"speaker":"宮崎委員","kind":"質問","question":"競争ということであれば、何が勝ちで、どうなったら負けだという考え方というのは持っていたんでしょうか。区の競争という認識の中では、何を基準で考えてきたのか、そこのところを改めて伺いたい。","respondent":"濱野区長","answer":"よく地域のことを勉強して、地域に合った、あるいは区に合った政策を展開できることがよいことだという意味の競争だと。何区が勝ったの、何区が負けたのということではない。","id":"exchange-136"},{"speaker":"宮崎委員","kind":"質問・要望","question":"濱野区長も健全財政をかなり強調しておりましたけれども、ここのところで１つは人件費を減らす。私はこの区民に求められる施策を推進するというのであれば、見直していく必要があるのではないかと思いますけれども、いかがか尋ねました。","respondent":"濱野区長","answer":"そういう意味で言えば、今、品川区の世論調査の速報ですけれども、住み続けたいという方が増えて、９割になっている。そういう必然性が出てくれば当然に変えますが、今の時点で、おっしゃるような点での見直しは必要ないと思います。","id":"exchange-137"},{"speaker":"宮崎委員","kind":"質問・要望","question":"住民の要望する施策、先ほども特別養護老人ホームの話もありましたけれども、そういう住民の側からの要望というのが全然実現されていない。私はどう見ても、所得の少ない人の福祉はどんどん削って、改めてそこの考え方を伺いたいと思います。","respondent":"濱野区長","answer":"区自体が利益第一ということは全くあり得ないことでありまして、その辺はしっかりお考えいただきたいと思います。何かが足りないから、という言い方で区政を云々するというのは、ちょっと偏った見方だと考えています。","id":"exchange-138"},{"speaker":"宮崎委員","kind":"意見","question":"この仕組み自体が。区民の声をどういうふうに反映するのか、そこの仕組みをどういうふうに考えているのか、お聞かせほしいと求めました。","respondent":"濱野区長","answer":"もう一方で、政策というのは、区民の皆さんが何を望み、そして区民の皆さんに何が必要かということを判断して行うということです。そういう意味では、あることを行うためのマネージメントと、それから何を行うべきなのかを考えるというのは、また別なことだと思います。","id":"exchange-139"},{"speaker":"宮崎委員","kind":"質問・要望","question":"じゃ、政策評価というのであれば、特別養護老人ホームか、いわゆる有料老人ホームか、どっちをつくるのか、その評価はされたんですか。したのか、しないのか、したのであれば、その結果を教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"そういう意味では、先般、福祉高齢事業部長が答弁いたしましたように、特別養護老人ホームについては基盤が整備されているという認識です。今後は多様化するニーズに対応して、１つにはグループホーム、あるいは夜間対応型訪問介護。","id":"exchange-140"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それとは全く別に区民の要望とは違う方向で高齢者施策がどんどん進んでいるように見えてしようがないですね。ぜひこの高齢者の施設をどういうふうにするかを評価の対象にしてほしいと求めましたが、いかがか尋ねました。","respondent":"濱野区長","answer":"だから、それをもって品川区は高齢者福祉のことを考えていないというような言い方は、これを正しく読んでいただいていないと思います。はそれを正しく読んでからご発言をお願いします。","id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問","question":"今、何が必要なのか、この政策評価でやってほしいということを言っているんです。改めて答えをお願いします。","respondent":"濱野区長","answer":"こういう決算特別委員会というような場が、まさに区民を代表する皆さん方が平成１７年度の仕事に対して、どう評価されるかということを議論する場でありますので、こういう場が最もビビットなといいますか、活力ある政策評価の場だと考えています。","id":"exchange-142"},{"speaker":"宮崎委員","kind":"質問・要望","question":"区民の暮らしは今、火の車ですからね。そこのところはしっかり住民の声を聞いてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-143"},{"speaker":"須藤委員","kind":"質問","question":"ページ９２、ページ９３、財産収入に関連して質問します。いろいろな控除をもとに戻す、この部分で一般財源として入ってくるものについての取り方はどうあるべきかというお考えを聞かせてください。","respondent":"日下部企画財政課長","answer":"先行き三位一体でありますとか、いろいろな制度改正の関係もあって、楽観できないという状況があります。そういったことも踏まえまして、基本的には中長期の視点の中で、しっかりとした活用を図ってまいると、このように考えてあります。","id":"exchange-144"},{"speaker":"須藤委員","kind":"質問・要望","question":"三位一体というのは地方にはどうしても予算が下がってくるというのはわかっているわけなんですから、その辺を踏まえながら、今すぐやるべきこと。品川区の進むべき道は第三次長期計画にあるわけですから、それに沿って、そのあたりはいかがか尋ねました。","respondent":"濱野区長","answer":"国なり都ですけれども、我々ももし何かを考えるんだったら、品川区にやってもらったらどうだろうかというようなスタンスでものを考える。管理職の仕事であり、それはまた私の姿勢でもあると考えていますので、この姿勢は緊張感をもって持続させていきたいと考えています。","id":"exchange-145"},{"speaker":"須藤委員","kind":"質問・要望","question":"そこに立てるんだよというのではなくて、全体的に目線がどうなんだというようなものを見ていただきながら、しっかりつくっていくと。そういういろいろなことも出てくるから、その辺もいろいろ選挙があるときに考えていただきたいと思うんですが、いかがか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"そういった意味では、来年の４月の区議選挙につきましては、一定期間がありますので、有権者の視線の部分も十分考慮していきたいと思ってあります。２点目の投票所の氏名等掲示については、くじで決めるということに定まっておりますので、ご理解いただきたいと思います。","id":"exchange-146"},{"speaker":"須藤委員","kind":"質問・要望","question":"９３ページ、まるっきり同じ利率で利子収入を得ているのかどうかということと、それは利子収入として入っていない。そのあたりはどうなっているのか、説明を求めました。","respondent":"冨田副収入役、日下部企画財政課長","answer":"基金につきましては、現在５００億円を超える基金があるわけですけれども、約３００億円ほどが債券購入、国債等にあてております。それから公共料金支払基金で、こちらのほうは基本的に決済用預金のほうに入れておりますということで… それから下から２つ目の義務教育施設整備基金利子、利子はそのまま、その基金に積み増しをします。それからみどりの基金利子でありましたら、生け垣助成とか、そういう形で運用益を活用しているという状況です。","id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/754385?Template=document&Id=1260#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":117005,"voices":341}},{"id":"h18-20061016-4","meetingId":"h18-c-settlement","date":"2006年10月16日","dateIso":"2006-10-16","committee":"決算特別委員会","time":"午前１０時０３分～午後５時４７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を169件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"最初に１０３ページの生活安全推進事業、その後で１０６ページの防災対策費について質問していきます。そういった部分もうまく連携がとれているのか、その辺のところをお聞かせほしいと求めました。","respondent":"金子生活安全担当課長","answer":"今後もさらに連携を深めて、空白期間、間隙が生じないように活動をしていきたいと考えています。教育委員会、まちづくり事業部と連携をさらに図りまして大いに活用していきたいと、こう考えております。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"そういうところはスピーディーな対応が求められて、その辺のところも重点を置いて、さらにお願いしたいと思います。品川区内でも５カ所のうち４カ所が用途変更、１カ所が廃止と告げられまして、そういった部分についてお聞かせほしいと求めました。","respondent":"金子生活安全担当課長","answer":"お話のありました用途変更４カ所につきましては、警視庁の管理のもと、仮称ではありますけれども、地区安全連絡所として活用すると聞いております。もう１点、育てていくような防犯拠点、こういったものにしていきたいと考えております。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"よろしくお願いしたいと思うんですけれども、例えば環状６号線等、その辺をお聞かせほしいと求めました。","respondent":"金子生活安全担当課長","answer":"交番の統廃合によりまして、これまで以上にパトロールできる警察官が生じることは間違いないと聞いております。したがいまして、そういった敷地等をうまく活用できないかという方法をこれから検討して、警視庁にも働きかけをしていきたいと考えております。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"今年の６月より施行されました国の放置駐車違反なんですけれども、都内１２区４３署での取り締まりということで実施をされておりますが、その辺をお聞かせほしいと求めました。","respondent":"松嶋交通安全担当課長","answer":"こうした中で、昨年から新法制を踏まえまして、各署におきましては駐車規制の見直し、そういったものを実施をしております。これは区としては警察と連携をとっていきまして、いろいろな対応をとっていきたいと、このように考えております。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"続いて１０６ページの防災対策費に移ります。平成１７年度からということで、その辺のところを教えていただきたいのと、その辺をお聞かせほしいと求めました。","respondent":"桑村危機管理室長、久保田防災課長","answer":"平成１７年１月に危機管理室を設置いたしまして、通常では予測できない事態ということに対処するということでやってまいりました。その後の対応につきましては、危機管理室は基本的に対応に一緒に入って、対応について進めていくと。 例えばジャッキとか破壊工具の展示と、それから実際に町会の人が参加して、そういうものを経験するというようなこともやってあります。全部の地区というわけではないんですけれども…","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"１０４ページの広報費、情報公開に関連して質問させてほしいと求めました。前年度１年間で陳情数は大体どれぐらいになったのかということと、話し合いが年間どれぐらいあったのか、それをまず教えてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"所管に回答依頼をしたり、その間、所管で必要に応じて区民の声に対して部課長が説明されたりしていることと思います。件数については把握はしてございません。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"２４０件とＥメールで７００件、約１,０００件というんですけれども、この寄せられた１,０００件の回答というのは、大体すべてにわたって回答されているんか尋ねました。","respondent":"中川原広報広聴課長","answer":"そのうち住所氏名が書いてあって回答が可能なものが２４０件で、そういったインターネットの特性で住所氏名を書かれていない方です。２４０件の中でも、答えが欲しいという内容と、その中で回答をさせていただいているのは２４０件です。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"そうすると区の基本姿勢というのは、区民の声が出されて、回答可能なもの、回答が求められているものについては回答していくという姿勢なんか尋ねました。","respondent":"中川原広報広聴課長","answer":"住所氏名がありまして回答可能なものについては、すべて回答をします。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"それは区民個人であっても、区内にあるさまざまな住民運動団体だとか、町会なんかも入るかもしれませんけれども、それは団体であっても問わずということか尋ねました。","respondent":"中川原広報広聴課長","answer":"お答えができるような状況になったときにお答えするという形で回答します。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"それは大変すばらしいことですし、今後も続けてほしいと求めました。４月に入ってから、東京春闘共闘会議が公契約条例など勤労施策充実のための懇談会をやる、これに対してはどのような態度をとったんか尋ねました。","respondent":"中川原広報広聴課長","answer":"それについては区民の声という形では受け付けておりません。広報広聴課にはそうしたご要望が来ていません。","id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"どこかの所管にこのアンケートと、それから懇談の申し入れが回ったと思うんですが、それはいかがでしょうか。受け取った所管で回答願いたいと思います。","respondent":"桑村総務課長","answer":"懇談といいますと、ちょっと私も記憶があいまいなところがありますけれども、そのようなお話があるのではないかと思います。ちょっと内容についてはどういう形でお答えしたかあれですけれども、懇談については行われていないということだと思います。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問・要望","question":"それなのに回答しないで、しかもアンケート用紙を突き返したというのはどういうわけなんでしょうか。どこか知っている方が絶対にいるはずですから、答えてほしいと求めました。","respondent":"桑村総務課長","answer":"いわゆる区民の方の、いわゆるご意見ですとか、そういったものについてお答えできるものはお答えをしているということだと思います。お答えしない場合もありますし、それについてはアンケートにお答えできないというふうなことはあるかと考えています。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"部長クラスだとどうですか。自分の我が身に照らしてこうした問題が、総務部長、どうですか、覚えがあったらちょっとお答え願いたいんですが。","respondent":"本間総務部長","answer":"いろいろな団体がいろいろな考えで活動しています。区のそれぞれの考えで対処するケースは一般論としてあろうかと思いますが、今の具体的なお話につきましては、私も記憶が定かではございません。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"そうなっているのに、担当課長、部長が記憶が定かでないというのが私はちょっと解せないと思います。とりわけ不安定雇用を少しでも前に進めようとしたこの種のアンケートが出てきた場合に、今後は回答するんでしょうか、しないんか尋ねました。","respondent":"本間総務部長","answer":"出されました時点につきまして、中身をよく読みまして、区としての態度を決めさせていただきたいと、さよう考えているところです。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"どんな団体であれ、回答できるものについては誠実に回答するという区民の声と同じ対応をしていただくように要望しておきたいと思います。品川区政の基本的な姿勢として貫いてほしいと思ったわけですけれども、改めて、思いなどをお聞かせ願えればありがたいんですが。","respondent":"濱野区長","answer":"この基本方針は、高橋区政の時代においても、これはきちっとなされていたわけであります。所管も含め、あるいはまた実行する段につきましても、地域の実情というのをよく知った上で行うという基本方針を述べたと。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問・要望","question":"私どもの考えを聞いてほしいと言っても、その後やっと会合が持たれるという、こんな状況が結構繰り返されてきたんです。区民の声、話し合いについては極力受ける姿勢に立ってほしいと思いますが、改めてもう一度聞かせてほしいと求めました。","respondent":"濱野区長","answer":"いろいろな団体がいらっしゃいます。過去、今後ともそういった団体がどういうお考えなのかということもさることながら、そういう点はきちんとした判断をしてまいりたいと思います。","id":"exchange-016"},{"speaker":"沢田委員","kind":"質問・要望","question":"だけど、排除して、議会で取り上げなければ会わない、区長答弁があって初めて実現をしたというようなことを繰り返さないように要望したいと思います。その上で品川区の情報公開の手数料はやっぱり他区と同じように無料にすべきだと、そこを私はぜひやってほしいと思いますが、いかがか尋ねました。","respondent":"濱野区長","answer":"情報公開の手数料については従来どおりと考えております。","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問・要望","question":"５区ぐらいが有料化を検討して、私は区民が自分の情報を手に入れるわけですから、企業が営利のために入れるのは別ですよ。それは有料化してもいいと思いますけれども、区民が区政の問題で情報を公開してほしいといった場合には無料にすべきだと、こういうふうに思います。","respondent":"中川原広報広聴課長","answer":"品川区の考え方としましては、一定の職員の労力等々がかかりますので、受益者負担という考えに立ちましてやらせていただいています。なお、品川区の場合、何人も情報公開請求ができますので、参考までに申し上げますと、区外の事業者と区外の方の請求が７割という現状です。","id":"exchange-018"},{"speaker":"沢田委員","kind":"意見","question":"権利の保障、それからもう１つ、だれが受益者かというのは、情報を区民に渡すことによって受益は区民自身が受けると思います。新しい区長のもとでぜひ再検討をすることを要請して、時間ですので終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"１０４ページの「しながわガイド」、１０６ページの防災対策費、時間がありましたら１０３ページの生活安全推進事業についてお伺いしたいと思います。じゅうたん、また窓ガラス、その辺の掃除はこの庁舎維持管理費の中でよろしいんか尋ねました。","respondent":"中島経理課長","answer":"庁舎内の清掃等につきましては、こちらの庁舎管理維持費に含まれておるものです。","id":"exchange-020"},{"speaker":"武内委員","kind":"確認","question":"命綱をやっているんですかと言ったらやっていないと、仕事ですからということでやっていまして、もう結構だから。万が一、もしそういうところから落下して事故が起きた場合の区の責任というのは何か問われちゃうんでしょうか、どうなんか尋ねました。","respondent":"中島経理課長","answer":"契約の中では当然清掃作業員の方が事故等、けがをした場合につきましては、その事業者の責任で対応するということになってあります。今、作業方法につきましては安全性を確保してきちっとした状態の中で作業をするようにというのは、日ごろから指導をしています。","id":"exchange-021"},{"speaker":"武内委員","kind":"質問・要望","question":"１０４ページの「しながわガイド」に移りますけれども、目黒区ですから目黒ガイドなんでしょうけれども、つくったと伺いました。１０月１日から配布なので、一部しかまだないので、そういう形でやっていくということについての考え方を教えてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"本年度、私どもの区でも「しながわガイド」の全戸配布を予定しておりまして、そういった会社も視野に置きまして検討させていただきました。今回、いろいろなことを考えまして…","id":"exchange-022"},{"speaker":"武内委員","kind":"質問・要望","question":"そういった区内のいろいろな情報なんかもあれば非常に喜ばれるんじゃないかなと思いますので、ぜひご検討してほしいと求めました。一応防災対策費の中でお願いしたいんですが、これについてお聞きしたいんですけれども、そういうのはどうなっていますか尋ねました。","respondent":"久保田防災課長","answer":"町会全体では２０３町会というのが私どもに登録しているところなんですけれども、そのほか、近くの公園等を利用して建てている場合があります。両方合わせますと、まだ１３５町会ということで、大体６７％ぐらいにはなりますけれども、そういう形で今、やっている状況です。","id":"exchange-023"},{"speaker":"武内委員","kind":"質問・要望","question":"１３５町会で持っているということで、無償でやっているとはいえ、なるべくなら早く出ていってほしいということを言われているらしいんです。さっきおっしゃっていた地域の公園ですとか、また、そういった防災広場みたいなところに場所をお借りすることは可能なんか尋ねました。","respondent":"久保田防災課長","answer":"民間でお借りしている町会が、やはり時代の変遷というんですか、その持ち主の関係でほかのところに移ってほしいという要望が幾つか出てあります。そこに設置することが可能であれば、そして調査をして、なおかつやっていきたいなというふうには考えているところです。","id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"ぜひ、またその際にはよろしくお願いしたいと思うんですが、その場合、倉庫はもう建物というか、プレハブみたいなのがあるんですけれども、その場合の移動する費用なんかはやっぱりこれは町会が負担するんか尋ねました。","respondent":"久保田防災課長","answer":"移動する費用も原則的には町会でご負担していただくことになりますけれども、よくあるケースで、私どもがお手伝いをすることはあります。一緒になってものを外したり、私どももお手伝いをして移設するということもありますので…","id":"exchange-025"},{"speaker":"武内委員","kind":"質問","question":"ぜひよろしくお願いします。最後に１０３ページの生活安全推進事業の中でお伺いしたいと思うんですけれども、そういうところというのはデータとしてあるんか尋ねました。","respondent":"金子生活安全担当課長","answer":"ひったくり、あるいは性犯罪等、あるいは痴漢も含めたものなんですけれども、これに関しましては町丁別のデータがあります。暗がりで、比較的狭い通り、それで女性を対象とした事件がほとんどです。","id":"exchange-026"},{"speaker":"武内委員","kind":"質問","question":"それで、ひったくりの多発地域だよと、ここで多発していますよというものをその自治体は歩道にはってあるんです。そういったものを例えば区で今後工夫していくというのはどうなんか尋ねました。","respondent":"金子生活安全担当課長","answer":"あるいは性犯罪等に関する対応につきましては、これは蛍光色で非常に目立つ看板をそれぞれ設置して、評判がいいことから。なかなか目立たないような点もありますので、その点はちょっと検討して、最も効果ある方法を見つけていきたいと考えています。","id":"exchange-027"},{"speaker":"川西委員","kind":"意見","question":"子どもの出生がどういう理由であろうとも、そして区からも、子どもの利益を最優先で仕事をしなさいよということを指示されて今日に至っています。そういう気持ちが私なんかに寄せられながらも、やはり子どもの権利最優先という立場から…","respondent":"濱野区長","answer":"それからもう１つは、そしてもう１つは戸籍の制度というものを考えなければならない、この３点が１つの判断のポイントだと考えています。もう１つ、その点については最高裁の判断云々の時期に至るまでも、行政としてのサービスは十分にさせていただいていると考えております。","id":"exchange-028"},{"speaker":"川西委員","kind":"質問・要望","question":"変えていく姿勢をぜひ、これから任期４年間ありますので、新しい姿勢もお考えほしいと求めました。平成１７年度は約３年目になるんでしょうか、平成１７年度中にはどういうコミュニティ組織づくりの骨格を積み上げられたのか、内容について伺います。","respondent":"田村地域活動課長","answer":"１地区３０万円ということで、赤十字の活動等、地域との連携を深めるための活動として実施しているものです。やはり広く皆さんに情報を知ってもらうという趣旨ですので、今後検討させていただきたい、このように思っております。","id":"exchange-029"},{"speaker":"川西委員","kind":"質問・要望","question":"やはり区として地域のコミュニティをどういうふうにつくっていくかというのをもう少し積極的に出されていかれる必要があるんじゃないかというふうに…指定地域を主要駅とその周辺だけじゃなくて、もうちょっとまちの中に広げていただきたいと考えていますが、いかがか尋ねました。","respondent":"田村地域活動課長","answer":"私も先ほどいろいろと美化活動を各町会で実施しておりまして、各町会、積極的に啓発活動を実施しているというような内容です。町会と連携をとりながら、その他の地域についても啓発活動について行政も支援してまいりたい、そのように思っております。","id":"exchange-030"},{"speaker":"川西委員","kind":"質問・要望","question":"次に、毎度言っている区民保養所のことですが、平成１７年度の調査の中で、今後の方策はどのように今、なっておりますでしょうか。伺います。","respondent":"鷹倉区民課長","answer":"暖景苑は数的には４７名程度の施設なんですが、それにかわる代替的なものを何とか確保したいなということで、今、詰めを行っているところです。１１月に入った早々に委員会がありますけれども、そのときには具体的な報告ができるのではないかと、このように考えているところです。","id":"exchange-031"},{"speaker":"川西委員","kind":"質問・要望","question":"そのご答弁で結構ですが、私は行財政改革特別委員会というところに所属しています。新しい方策をとったものがあまり区の手間ひまのかからないような段取りで、できるだけ合理性を持ったものにしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"それと１０２ページの職員研修費と職員互助会補助金についてお伺いしますが、まず退職手当についてお伺いしますが、いわゆる退職のピークというのはどのぐらいに来るのかを教えていただければ。","respondent":"榎本人事課長","answer":"その中で、その部分ぐらいのペース、３０億円ペースが大体年間トータルで続くような感覚です。その中の３０億円ということになりますので、人数等の関係でいけば、特に支障なく支払えることができるのかなと考えております。","id":"exchange-033"},{"speaker":"藤原委員","kind":"確認","question":"退職手当は問題ないということで確認をさせていただきましたが、その人材確保をどういうふうに考えているのか、この２点についてお伺いします。","respondent":"榎本人事課長","answer":"検討中ですけれども、中途採用ということで経験者採用というものも検討していますので、そういうもので人材を確保していこうというものです。技能系につきましては民間委託等で対応しておりますし、中途採用ですとか…","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"その辺の問題というのはまだすぐにはあらわれていないと思うんですけれども、将来的において、採用がなかったときに関してというのは問題というのはないんか尋ねました。","respondent":"榎本人事課長","answer":"ただ、平成１５年２７名、１６年４８名、１７年４１名、１８年５１名という形で、それぞれ一定程度の数は採用してきてあります。実際上入ってきた年代がばらけますので、確かに２０代が今、それをもってだけで採用ゼロの影響が出るということではございません。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問・要望","question":"当時、私も質問させていただいたんですが、大阪の自治体でいろいろ問題があったということが指摘されました。内容もいろいろ変わってきたと思うんですけれども、まず見直しの経過と、それと内容がどのように変わってきたかを教えていただきたい。","respondent":"榎本人事課長","answer":"職員互助会の部分ですけれども、大きな見直しは平成１７年度に見直しをしておりまして、特に互助会に対する補助金を約半分にしたという形です。それによって事業規模が縮小しまして、一定程度いろいろな給付金、それから宿泊補助等を整備したところです。","id":"exchange-036"},{"speaker":"藤原委員","kind":"意見","question":"この互助会に関しては、職員の方の福利厚生ということで、前高橋区長もこれに関してはバランスよく職員に対して必要だというお考えであったと思いますが、この互助会の制度に関して、新区長はこれからどういう方針を持たれているのかをお尋ねいたしますとの意見を述べました。","respondent":"濱野区長","answer":"これは当然のことながら、民間企業の従業員との均衡ということは１つ重要な要素、それからもう１つは、品川区も１つの雇用者です。あるいは従業員に対する雇用者責任という、この２つの観点からバランスを考えて物事を進めていくという、この基本に変わることはございません。","id":"exchange-037"},{"speaker":"三村委員","kind":"質問","question":"私からは成果報告書１０５ページの企画調整費、また１０１ページの総務部、また女性の自立支援についてお伺いしたいと思います。平成１７年度にボランティアのホームページのシステムが立ち上がって、今、またどういう契約になっているのかを最初にお伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"開発委託が５５０万円という形です。事業部支援プロジェクトの中に含まれてあります。","id":"exchange-038"},{"speaker":"三村委員","kind":"質問","question":"とてもその団体がどういう団体なのか、そこの団体がどういう活動をしているのか、その点についてご意見をほしいと求めました。それに対してどういった問題点があるのか、現状把握されていることをお伺いできればと思います。","respondent":"堀越行財政改革担当課長","answer":"どういった分野でやりたいかということをまずお考えになっているだろうと考えまして、そういう形の構成にしてあります。今のところはそういう形でございまして、今後も受け付けていきたいと考えています。","id":"exchange-039"},{"speaker":"三村委員","kind":"質問","question":"どの程度このサイトを通じて利用者が実際にボランティアの活動に参加されたとか、そういった実績や何かは把握していらっしゃいますでしょうか。もし把握されているようでしたら、教えていただければと思うんですけれども。","respondent":"堀越行財政改革担当課長","answer":"こちらはボランティアの登録という形ですので、登録者数、それからアクセス件数等も順調に伸びてきております。それから短期でやられている方ですとか、さまざまな状況がありますので、今のところは細かい活動状況を把握しているという状況にはございません。","id":"exchange-040"},{"speaker":"三村委員","kind":"質問","question":"行動計画には残念ながら１００％という数字はならなかったんですけれども、利用実績はどのぐらいになったのかの実数を教えてほしいと求めました。この行動計画をつくる前は実績ゼロということだったんですけれども、変化があったのかどうか、その点についてお伺いしたいと思います。","respondent":"榎本人事課長","answer":"それで、出産支援休暇の取得率７５％ということに対して、平成１７年度の実績でいきますと７７％という形になってあります。男性の育児休業についてはゼロだったのが、平成１７年度が育児休業がおりまして、取得率で申しますと１３.６％の取得という形になってあります。","id":"exchange-041"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひ実数でも教えていただければと思うんですけれども、ぜひこの数字も今後上げていっていただきたいと思うんですけれども、その点についてもお伺いしたいと思います。","respondent":"榎本人事課長、堀越行財政改革担当課長","answer":"失礼しました。実数ですけれども、男性の育児休業が対象者２２名中３名取得です。 厚生労働省で指定されております次世代育成支援対策推進センターというのがございまして、その作成と実施等について指導。東京都では東京商工会議所等６団体等が指定されておりまして、啓発…","id":"exchange-042"},{"speaker":"三村委員","kind":"質問","question":"そういったところで次世代育成支援の啓発の紙面や何かは打ち出されているのか、その辺については。ほかにもいろいろ働きかける方法等はあるかと思うんですけれども、それについて、もしされていることがあればお伺いしたいと思います。","respondent":"堀越行財政改革担当課長、金子産業振興課長","answer":"商工会議所の方と、もちろん事務レベルもそうですし、役員の方等ともお話を十分にしています。推進マニュアル等も展開していくというお話を聞いておりますので、そういった状況を見ながら、区としても支援をしてまいりたいと考えていま… 今、行財政改革担当課長が答弁したとおりでありますが、そういった情報も含めて、私どもは事業者向けに「産業ニュース」というものを出しております。こういった媒体をさまざまな啓発、それから私どもが支援する啓発セミナー等々を載せ…","id":"exchange-043"},{"speaker":"三村委員","kind":"質問","question":"努力義務の中小企業、品川区内の中小企業の行動計画の策定状況等をもし把握をされていれば、お伺いしたいと思います。公募委員がかわった理由について、その辺についてもし何か理由があるのであれば、教えてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"３００人以下の企業についてはデータが厚生労働省からも公表されておりませんので、現在までのところ、把握はしてございません。継続という形ですが、継続というのは、委員の方を選ばせていただいているという作業を進めているところです。","id":"exchange-044"},{"speaker":"三村委員","kind":"質問","question":"委員のほうは了解をさせていただきました。どういった意見が交わされていて、それが品川区にどのように反映されたのか、もし事例等があれば教えてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"全体的な意見といたしましては、いろいろな総合的な施策をおおむねきちんと展開してきているというようなご意見をいただいております。今後とも協議会としてしっかりと意見を言って、行政と一体となって…","id":"exchange-045"},{"speaker":"三村委員","kind":"質問","question":"すまいるスクールでは６時半までということで対応がされているんですけれども、それが小学校に上がってしまうと、そこの時点で切れてしまう。高学年になってくればいいんですけれども、この点については区としてはどのように判断をされているのか、その点についてお伺いしたいと思います。","respondent":"新美企画部長","answer":"次世代育成支援対策推進協議会ですが、３月に開きましたので、すまいるスクールに関するご意見を何点かいただきました。私どもは今までは拡大をしていくということで取り組んでまいりましたが、そういったことについて十分ご説明をし、いろいろなご理解をいただきながら。","id":"exchange-046"},{"speaker":"三村委員","kind":"質問・要望","question":"もちろんすまいるスクールを延長してほしいとか、とてもニーズの高い要望だと思いますので、ぜひ検討をしていってほしいと求めました。品川区としては改正されたことによってどういった行政施策、変わっていないのか、その辺についてお伺いできればと思います。","respondent":"武内人権啓発課長","answer":"今、均等法の改正が４月１日からスタートということできておりまして、今後、厚生労働省とこのポイントを各企業等に説明会を２月に開催する予定になっておりまして、そのような形で今後進めていきたいなと考えています。","id":"exchange-047"},{"speaker":"三村委員","kind":"質問","question":"すいません、男女雇用機会均等法ではなくて、改正ＤＶ防止法をお伺いしたんですけれども。","respondent":"諸岡児童課長","answer":"児童課におきまして、女性に関する福祉といたしまして相談を行っています。ＤＶ等の相談に応じ、また必要に応じて一時保護等に、被害者の保護につなげているというような状況です。","id":"exchange-048"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"私のほうから２点確認と質問をさせてほしいと求めました。山北町のほうが１００万円前後でずっと推移しているんですけれども、内容に相当違いがあるのかどうかを確認させてほしいと求めました。","respondent":"鷹倉区民課長","answer":"早川町の場合、直接行かれる方々には直にやるような形態をとってありますので、そこでも少し開きが出てくるのかなと考えています。１５年がぐっと落ちて、１６年、１７年で少し回復してきているという内容かと思います。","id":"exchange-049"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"それからもう１点は、平成１６年から契約延長をしてあるわけなんですが、そういう条項は入っているんでしょうか。山北町との話し合いの中でどういうふうにされているのかなということなんですが、わかりましたら教えてほしいと求めました。","respondent":"鷹倉区民課長","answer":"１０年延長したということで現在進めてあります。最終的に使わなくなったときには現状回復という条項が入っているです。","id":"exchange-050"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"品川区のほうへは１月のマラソン大会には来ることができなくなってきていますので、その辺のところの考え方をちょっと教えてほしいと求めました。事業の内容についての見直しも今後の中ではしていかなきゃいけないのかなと思うんですが、その辺のご見解を説明を求めました。","respondent":"鷹倉区民課長","answer":"昭和６３年から始めてきておりましてもう１９年、大井権現太鼓についても当初から立ち上がっているときからやっている事業です。そこのところである種の見直しという形で、より活性化させるような形で効率的に活性させていただきたいと考えているところです。","id":"exchange-051"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"それともう１つは、これは一般的に区民の方からのご要望で、検討する材料にもなるから見ると。スペースの都合もあるでしょうけれども、そこに期日前投票の案内も載せたらどうかという話が来ているんですが、その辺の考え方はどうか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"特に区議・区長の選挙期間は１週間という短い期間です。１晩かけて校正するという関係もありますので、ちょっと工夫させてもらわないと、なかなか難しいという状況にあります。","id":"exchange-052"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"どういう方が出るのかどうなのかという部分も。それは確かに出る方の数が増えれば、そのぐらいの努力はされてもいいのではないかなと思うんですが、ご意見を聞かせてください。","respondent":"野田口選挙管理委員会事務局長","answer":"載せ方の工夫はしますけれども、校正等とかを短期間で誤りなく発行するということでは、なかなか難しいところもあります。そういうことも踏まえて、可能性については検討させていただきたいと思います。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"現在のこの防災計画には、この人数がどういうことでこれだけの数が出てきたのかということをまず伺いたいんです。１０年ほど前の平成５年当時の資料を見る機会がありまして、その辺もあわせてどういう検討の経過があったのかを教えてほしいと求めました。","respondent":"久保田防災課長","answer":"これは相当前からこういう考えでやられていたんですが、学校も避難所として位置づけていこうという形で、新しく考え方が出てきたのが平成８年です。それぞればらばらですけれども、そこで収容できる人数として定めて…","id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"その辺はどういうふうに考えていけばいいのか、どういうふうに予想をしておられるのか、その辺を伺いたいと思うんですね。この計画によると、それでの数なのかなと思うんですけれども、あふれちゃう方々をどうするかというところをちょっと伺いたいと思います。","respondent":"久保田防災課長","answer":"品川区の人口が３３万人ということを考えますと、被害予想で出ている避難者は４万５,０００人ですから、十数％になるかと思います。そういう方でも収容できるような２段階、３段階の体制を区としては考えているという状況です。","id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"改めて伺いますけれども、２カ月とか、そういうことだってあり得るわけですよね。教えていただきたいということと、それともう１つはマニュアルの関係なんですけれども、その辺についての状況も教えてほしいと求めました。","respondent":"久保田防災課長","answer":"この災害時の対応は、確かに１区だけの、品川区に起きたら品川区の対応だけでは限界があります。それからもう１つは、事業所のほうともその辺の支援、私ども品川区の中でもそういう検討を進めているところです。","id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"ですから、その辺の見解と、すべての防災区民組織の役員には伝わっているということで認識していいんでしょうか。１人でいなくちゃいけないという場面にお知らせをするサインを設置してほしいと聞いたんですけれども、それについてはどうか尋ねました。","respondent":"久保田防災課長","answer":"この３日間しのぐために最低必要なものというのは、３日以後は支援が来ますので、洗濯機も支援されることだろうと私も思っております。今後も私どももなるべくそういうところは温度差を埋めるような形での努力をしていきたいと考えております。","id":"exchange-057"},{"speaker":"若林委員","kind":"質問","question":"私のほうからは１０３ページの青少年対策、２点目に同じく生活安全推進事業、生活安全サポート隊を中心に質問します。そこで、全体的にとらえまして、まず予算の配分の仕方、それから、これらの事業内容の健全性についてご説明ほしいと求めました。","respondent":"田村地域活動課長","answer":"一括１３地区からお連れしていますが、あるいは宿泊でしない場合もありますし、それぞれの地域ごとにさまざまな取り組みをしているものです。人数も１回行ってまた戻ってくるとか、各地区から上がった数字を集計したものが、委員ご指摘の数字です。","id":"exchange-058"},{"speaker":"若林委員","kind":"意見","question":"今後とも有意義な地区委員会の運営をお願いしたいと思います。課長もおっしゃられました健全育成が目的だというところで、どのような成果を得てこられたのか、何点かお答えほしいと求めました。","respondent":"田村地域活動課長","answer":"さまざまな取り組みを地区委員会、９００人弱で、各地区ごとのさまざまな活動をしていますので、それぞれ具体的に挙げるというのはかなり難しい。実態を調べて、あるいは場所を移動させてくれということで…","id":"exchange-059"},{"speaker":"若林委員","kind":"質問・要望","question":"次に、この地区委員会の構成についてですが、ある程度固まった構成員、メンバーになっていると思います。そこで、新規の参加も含めまして、地区委員会への参加というのはどのような過程を経て、どういう決定がされるのか、お知らせほしいと求めました。","respondent":"田村地域活動課長","answer":"区のほうからの２年の委嘱ということで、まず時期が来ますと、切れる前に各地区ごとの所長会にお願いして、各地区の町会長に推薦依頼を出します。それと９９名、全体の１１.５％がそれぞれのＰＴＡの方が委嘱されて、地区委員会として活躍している。","id":"exchange-060"},{"speaker":"若林委員","kind":"質問・要望","question":"メンバーが参加を受け入れるといいますか、来ていただきたいというか、こういう観点です。昨年１年間でも１,０００名超のそういう児童相談を受けているということで、今後どのように検討させていくかをお知らせ願います。","respondent":"田村地域活動課長","answer":"今後連携を密にしていく必要があるだろうということで、地元の児童センターと連携を図って、式典を含めて事業を出しております。１３地区連携しながら児童センターと、連携を密にして事業を進めていこうということで、このような実態です。","id":"exchange-061"},{"speaker":"若林委員","kind":"質問・要望","question":"生活安全サポート隊のほうでパトロールの車を回しておられますけれども、こういった稼働率等が現在どのようになっておりますでしょうか。その効果、具体的に犯罪を未然に防いだとか、また具体的な犯罪に対応したことなど、そこら辺をまずお知らせほしいと求めました。","respondent":"金子生活安全担当課長","answer":"生活安全サポート隊の活動実績についてご説明します。近隣セキュリティシステム、いずれも初期的対応については警察に頼らず、一時的にはサポート隊が対応して難を免れているといった状況です。","id":"exchange-062"},{"speaker":"若林委員","kind":"質問・要望","question":"これに対して区はどのように受けとめておられるか、１点伺います。パトロールの機能が強く求められているという都民の世論になっているようですけれども、なぜこのパトロールへの要望が多くの区民、お伺いいたします。","respondent":"金子生活安全担当課長","answer":"警視庁の考え方によりますと、これからも警視庁管理のもと、所定の人員を置いて活動するように聞いております。大きなことは言えませんけれども、補充するような形で実施をして、結果として安全が確保できればと考えています。","id":"exchange-063"},{"speaker":"若林委員","kind":"意見","question":"ぜひとも池田山交番、これは今回請願が出されましたが、そのほかにも区内で３カ所見直し計画が出されております。特に池田山地域につきましては、パトロールの強化についても特段のご配慮をお願いしたいと思いますけれども、ご答弁をお願いいたしますとの意見を述べました。","respondent":"金子生活安全担当課長","answer":"これまで以上に警察と連携をとって、穴のないように対応していきたいと考えております。","id":"exchange-064"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、先ほど確認したところによれば、いわゆる外に出した仕事の人件費はカウントされていないわけであります。やっぱり確認したいのが、初めて正当に評価できると思うんですが、そのことについてのご答弁をお願いいたします。","respondent":"日下部企画財政課長","answer":"例えば平成１７年度の実績で見ますと、これはあくまでも概算でありますけれども、例えば６億円程度人件費の削減という実績が出ております。そうすると、３億５,０００万円ほどということで、おおむね全体として６割程度の執行の実績という形で切り替わっているという現状です。","id":"exchange-065"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、そういうことからトータルコストを含めた上で、数字は確かに減っていると思います。指定管理者が増えていくわけですから、しっかりとそれを把握していってほしいなと、答弁をまた改めてお願いいたします。","respondent":"日下部企画財政課長","answer":"先ほどもちょっと触れましたけれども、区のほうといたしましては、いろいろな手法の見直しによってコストを削減する。そういう手法も含めて、経年的な変化も含めてきちんと検証し、次の見直しに生かしていくということで取り組んできているという状況です。","id":"exchange-066"},{"speaker":"伊藤委員","kind":"質問・要望","question":"すぐに答えを求めるのは難しいとは思うんですが、品川区のサービスである責任をどう最後までとっていくかということと、区の内部ではやっていますね。さまざまなことも絡めながら最終工事を進めていくべきと考えますが、いかがでしょうか、答弁をお願いしたいと思います。","respondent":"宍戸施設担当課長","answer":"連絡会議になるのか、そういった検討委員会になるのかというのはこれから決めるべきものと思いますけれども、何らかの組織はつくらなければいけないと考えております。","id":"exchange-067"},{"speaker":"伊藤委員","kind":"確認","question":"もう１つ確認しておかなくてはいけないのが、ぜひそのことについては十分な区の対応をここではお願いをしておきますので、よろしくお願いいたします。犯罪マップに基づいた大きな意味の防犯体制をつくっていくべきだということを非常に思いましたので、そのことにつきましての答弁をお願いいたします。","respondent":"金子生活安全担当課長","answer":"平成１７年度については７回ほど発行しているんです。先ほど委員のほうからご提案のありましたボランティア活動、パトロール活動、そういった点に結びつけていきたいと考えております。","id":"exchange-068"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、もう少し踏み込んで、これだけ貴重なデータが今あるわけですから、例えばまちづくりの観点からも考えられるわけじゃないですか。ですから今、せっかくそういう犯罪マップがあるわけですから、ハードの部分の対応はどうですかということをお伺いしておりますので。","respondent":"山田区民生活事業部長","answer":"大変大きな視点からの、全区にわたる防犯活動はどうあるべきかというご提案かと思います。かなり多岐にわたる所管に入ってまいりますし、しばらくお時間をいただいて、研究させていただきたいと思います。","id":"exchange-069"},{"speaker":"伊藤委員","kind":"質問","question":"犯罪が多発している地域とそうでない地域が明確にわかっているわけですから、集中的に品川区の持っている資源を投入して犯罪を防止したらどうでしょうかという観点で質問しております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"山村委員","kind":"質問","question":"私は１０１ページの総務管理費の関係で２点お伺いさせていただきまして、同じく１０４ページの広報経費関係で１件、防災対策費で１件質問します。総務管理費の関係で質問しますが、それを同じように雇ってしまうのか、そこら辺をどのように考えていらっしゃるのか教えてほしいと求めました。","respondent":"榎本人事課長","answer":"区の場合につきましては、先ほど１０年間で４割が退職するという形ですけれども、それはすべて新規採用で補充するという考えは持っておりません。どれぐらいそういうスリム化が図れるのかというのは、いろいろと検討をしていかなければいけないと考えています。","id":"exchange-071"},{"speaker":"山村委員","kind":"質問","question":"まず民間委託をどう我々が審査していくというか、まず民間委託が増えていくことを考えて、何かしら対策なりをとってほしいと求めました。飲酒運転をした職員に対して、品川区ではどのような対応をとるおつもりなのか、今まではどうだったのかと、今後変えるのか等を教えていただければと。","respondent":"吉岡総務部副参事","answer":"今般の福岡市の飲酒運転を受けまして、非常に社会的に飲酒運転に対する目というのは厳しいものがあります。あるいは社会やその他の職員に与える影響、過去の処分例等を勘案いたしまして、処分の重さを決定してきているところです。","id":"exchange-072"},{"speaker":"山村委員","kind":"質問・要望","question":"私は飲酒運転をすることはありませんので、どんどん聞かせていただいてもいいと思うんですけれども、とにかく私はお酒が全く飲めない人間ですから。とりあえず現状はどういう処罰になっているのかと、今後その処罰を重くする等を考えられているかを教えてほしいと求めました。","respondent":"吉岡総務部副参事","answer":"今ご説明申し上げましたように、都の基準ですとか、社会通念等を勘案しまして決めております。今後の方向ですけれども、今申しましたように、処分基準は統一的なものはございませんので、それを策定するような方向で検討しています。","id":"exchange-073"},{"speaker":"山村委員","kind":"質問","question":"次に歩きたばこ防止キャンペーンのほうを。なかなか心が痛いところですが、よくはげる代物ですが、現状はどういうふうに変えられたのかということをまず教えてほしいと求めました。","respondent":"田村地域活動課長","answer":"実はまだ在庫がありまして、大井町からこちらに来るところに、新しいシールを年度明けましてはりました。予定では大井町、五反田についても路面表示を１１月以降、まだ現在のところはございません。","id":"exchange-074"},{"speaker":"山村委員","kind":"質問・要望","question":"県外ですとか区外の人間がどこまでそれに気づけるかというのはあるでしょうから、そこら辺はもう少し目立つようにしてほしいと求めました。もしやられていないんでしたら、その理由を教えてほしいと求めました。","respondent":"田村地域活動課長","answer":"ご質問が前にあったときに目黒区と調整しまして、目黒区は条例自体はあります。合同でマナーアップのキャンペーンを１１月に予定しようということで、今、暫時調整しています。","id":"exchange-075"},{"speaker":"山村委員","kind":"質問","question":"１０４ページの広報経費の関係でちょっとお聞きしたいんですが、ある程度課金制という、現在は無料ですけど。ですから、特に働いている年代ですとか、新しい分野に対してどういう方向性をとっていこうと思われているのか教えてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"ホームページが３０％、ＣＡＴＶが３０％の方が、区の情報をそこから得ていらっしゃるということです。対象者と情報内容と、それからメディアについてのバランスを考えながら、さらに研究をさせていただきたいと思います。","id":"exchange-076"},{"speaker":"山村委員","kind":"質問","question":"どんどん攻めていただければと思うんですが、とにかくぜひこれからも時代に乗りおくれないよう頑張っていただけるとうれしいと思います。最後に１０６ページ、今後想定されて対策というか、シミュレーションされていくのかということをお聞きしたいと思います。","respondent":"桑村危機管理室長","answer":"その中では一定のそういう対外的な被害についてどのように対応していくかということで。それが実際上区民の避難、あるいは救援のためにどういう形で使えるかという意味での考え方について、検討させていただければと考えています。","id":"exchange-077"},{"speaker":"山村委員","kind":"意見","question":"とにかくさまざまな事態を想定してシミュレーションしていくということ自体をやめないでいただいて、防災というのは自然災害だけじゃないということは肝に銘じて、これから頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それから、１００人ぐらいの退職で再任用を求める人はどのくらいの方々がいらっしゃるか、その数字だけでも教えていただきたい。まさに危機管理ですから、そういうものが平常のときに話し合われて検討されているのかどうか、その辺を説明を求めました。","respondent":"山田区民生活事業部長、榎本人事課長、桑村危機管理室長、上川内戸籍住民課長、中川原広報広聴課長","answer":"最初の１点目のご質問ですけれども、いわゆるお子さんのプライバシーという配慮のことかと思います。いわゆる一般的な法律論であるとか… １１６人、１２７人と、１００人台がずっと続いてまいります。ボランティアもあるでしょうし、自分の趣味もあるでしょうし… これまで平成１７年１月からやっておりました、いわゆる宿直の体制ですとか、東京都から立ち上がった情報がいかにこちらに早く入ってくるか。… 除籍簿についてのお尋ねですが、８０年保存しております。これは戸籍の規則によって全国一律８０年で…","id":"exchange-079"},{"speaker":"林（宏）委員","kind":"意見","question":"だから僕聞いたんですよ。あるいは避難してきた人と一緒にあれを生かしていくのかというのが、意味がよくわからないので、その辺答えてくださいとの意見を述べました。","respondent":"久保田防災課長","answer":"拡大して考えますと、こういうものをおっしゃっているんでしたら、これは全校に配備してあります。いずれにしても、今後ともその辺についてはよく区民の皆さんのお話を聞いて、整備できるものは整備していきます。","id":"exchange-080"},{"speaker":"林（宏）委員","kind":"意見","question":"あら、うちにはそれはないというような疑問が起きてくるから、もう１回点検をしておいてください。お願いしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"山路委員","kind":"質問","question":"時間があったら１０４ページの防犯設備整備助成事業についてもお伺いしたいと思います。どういう内容を今まで平成１７年度やってこられて、今後どういう計画を持って進めていかれるのか、お伺いいたします。","respondent":"武内人権啓発課長","answer":"それで昨年、平成１７年から第１１期の行動計画推進会議を立ち上げておりまして、来年の３月に報告書を区長に提言していただく予定になっております。生涯を通じた女性の健康支援、第３部会が、それを区政の施策に反映していきたいと考えております。","id":"exchange-082"},{"speaker":"山路委員","kind":"質問","question":"大変参考になりました。今言われています、どういうふうにバランスをとったらいいかいろいろ言われておりますが、何か今後考えていらっしゃるかどうかお伺いいたします。","respondent":"武内人権啓発課長","answer":"この１１月２５日に行う部分についてはワーク・ライフ・バランスということをテーマに、シンポジウムを予定しています。今後また男女平等啓発紙「マイセルフ」等を通じて、このような課題について広く区民の方に知らせていただくというように考えております。","id":"exchange-083"},{"speaker":"山路委員","kind":"質問・要望","question":"色覚の方にお伺いしたんですが、非常にホームページが優しくなったということを言っておりましたので、ここでお伝えをしておきます。非常に努力をされてバナー広告と発音するんですか、５つぐらい出されていますが、お聞かせをほしいと求めました。","respondent":"中川原広報広聴課長","answer":"この間、そういった作業が進むにつれ、バナー広告を出したいという業者が手を挙げてきてくださるようになりまして、今、少しずつ増えております。その広告の営業とともにバナー広告の営業もやってこようと思いまして、今、リストアップをしまして動いているところです。","id":"exchange-084"},{"speaker":"山路委員","kind":"質問","question":"インターネット美術館ですけど、ちょいちょい見せてもらったんですが、９月にリニューアルされたと思うんですが、すごくよくなっているんですね。載せられるんじゃないかと思ったんですけど、作品が少ないわけじゃないと思うんですが、その辺の理由はどういうところにあるんか尋ねました。","respondent":"鷹倉区民課長","answer":"平成１７年度についてはさらに１００点ということで４度ということです。その辺をどのような形でその要望をかなえていけるかというところは研究してまいりたいと考えています。","id":"exchange-085"},{"speaker":"山路委員","kind":"提案","question":"平成１３年の決算特別委員会の総括質問の中でも、インターネット美術館の中身についてのいろいろご提案を申し上げているところに。こういうものをせっかく設備を整えていらっしゃるので、作品の中をもっとあたってほしいと求めましたけど、その辺のお考えを説明を求めました。","respondent":"鷹倉区民課長","answer":"現在のやり方が公募という形で平成１６年度からやってきているわけです。この辺のアクセス数を踏まえながら、今後いろいろなアクセスが増えるような形の研究をしてまいりたいと考えています。","id":"exchange-086"},{"speaker":"山路委員","kind":"質問・要望","question":"ずっとこの方の作品を１０品ぐらい見て、そこまで研究をしていただきたいということなんですけど、その辺のことはいかがか尋ねました。","respondent":"鷹倉区民課長","answer":"確かに動画的なことができないかということも我々研究している部分もあります。ただ一定の経費がかかってまいりますので、その費用対効果等も踏まえて研究してまいりたいと考えています。","id":"exchange-087"},{"speaker":"山路委員","kind":"質問","question":"芸術、美術を支援する企業というのはよくありますよね。そういう考えをしているんですけど、芸術作品を見せるための企業広告も考えられると思いますけれども、この辺をどのようにお考えか尋ねました。","respondent":"鷹倉区民課長","answer":"財団法人品川文化振興事業団に対する委託事業という形でやってありますので、その辺との兼ね合いも含めて、これも研究課題とさせていただきたいと思います。","id":"exchange-088"},{"speaker":"山路委員","kind":"質問・要望","question":"くれぐれもよろしくお願い申し上げます。昨年行われまして１年で、調査状況でどういうことが品川区であったのか、そういうことがあったらお聞かせほしいと求めました。","respondent":"鷹倉区民課長","answer":"実施しているときも委員会の中でいろいろご質問があってお答えしているとおり、調査に対してもうちょっと十分説明してほしいとか。調査員の方も協力をしてやっていただいているわけですけれども、こういう形で調査対象の方から言われたという話がございました。","id":"exchange-089"},{"speaker":"山路委員","kind":"質問","question":"調査員の方が調査票をお家に持ってきて、回収に来なかったという方をお伺いしたんですね。せっかくの国勢調査で、来年の住民のニーズが反映されるかと思うんですけど、それに関しては品川区ではありませんでしたか。","respondent":"鷹倉区民課長","answer":"捨てたとか、そういう不謹慎な話は特に聞いてございません。","id":"exchange-090"},{"speaker":"山路委員","kind":"質問","question":"１２月には内容が発表されますので、来年の区の予算または区政にも影響があると思いますので、また改めて質問いたします。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０４ページの生活安全サポート隊についてお聞きしたいと思います。１７年と拡充されて、各警察署ごとに２名の警察官ＯＢと、また取り組んできた効果についてお聞かせほしいと求めました。","respondent":"金子生活安全担当課長","answer":"非常に犯罪が、こういった街頭犯罪を含めた細々とした犯罪についてはとても対応ができないということで、それで犯罪を抑止していこうという趣旨です。いきさつにつきましては、委員のお話があったとおり年々拡大をいたしまして、現在は１１名、車５台で対応しています。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういう中で、区民の中には安全な安心できるまちにしたいという願いが、本当に切実な思いであると思うんですね。街づくり特別委員会の中でもテーマの１つになっていますし、品川区として交番の役割について、どう考えているかについて説明を求めました。","respondent":"金子生活安全担当課長","answer":"そのまま地域の交番の警察官をパけトロール強化とあわせて交番の強化、こういったものを含めてより安全なまちづくりをしていこうという趣旨です。お金のかかる、まちの裏側隅々までのパトロール…","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は品川区が、警視庁が出した交番廃止の計画に対してどう思うかということではなくて、品川区が交番の役割をどのように考えているか、交番の役割についてお聞きしましたので、そのことについてお願いします。","respondent":"金子生活安全担当課長、早津区民生活事業部次長","answer":"特に近隣の住民の方に対する不安という観点から申し上げますと、非常に心配をかけているところです。警視庁の考え方、一定の考え方があると思いますので、できることを考えていかなきゃいけないのかなと考えております。 交番の役割ですが、東京都の警視庁の管轄物件でありますので、警視庁がどういう位置づけなのかというのと必ずしも一致しないかもしれません。しかしながら、地域における…","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"中学校、地域にとってはこの荏原町駅前交番をなくさないでほしいというすごい大きな運動が起こりまして、区としてはご存じでしょうか。それと、区としてどういうふうに受けとめているか、そのことについてもお聞かせほしいと求めました。","respondent":"早津区民生活事業部次長","answer":"品川区としてどう対応するかというご説明をいたしましたときに、請願を取り下げる方向で検討するということが町会長会議の中で合意されております。したがって、品川区としての対応策について一定のご理解も得られていると考えているところです。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"縦・横の長さと平米数を教えていただきたいのと、それとあとは、私は地域の要求としては交番を残してほしいというのが皆さんの思いで。そういうことで本来であれば交番を存続してほしい、区として東京都の警視庁のほうにぜひ働きかけていただきたいと思うんですけど、いかがか尋ねました。","respondent":"山田区民生活事業部長","answer":"区民委員会の中で審査をしていただきまして、それから本会議の中でも、全員の中で議決をいただく予定です。その中で警視庁のほうで、そこを交番とするという考え方は持たないということを明言され、荏原警察署の署長を含めて私どものほうにご説明に来ました。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"あそこのところには建物はもう建つわけですから、警視庁管轄ではなくて、警察官ＯＢを配置するというのは可能だと思うんですよ。パトロールの強化をするためにこういう統廃合をやっていくのだというのが警視庁の言い分ですから、今、ここら辺の見解についてはいかがか尋ねました。","respondent":"金子生活安全担当課長","answer":"自治体管理の用途が変更した施設につきましては、今回の区設置の安心安全ステーションに関しましては、なかなか難しいという話は聞いております。何で難しいのかについては検討中であり、具体的なことは警視庁のほうの考え方でありますので…","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは９月２８日の警察・消防委員会の中でも、この議事録をいただきましたけれども。せめてこの自治体管理の交番と同じように、警察ＯＢの配置を最低でも置くようにということで取り組んでいただきたいと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"大沢委員","kind":"質問・要望","question":"１０５ページ、職員被服貸与費ということで教えてほしいと求めましたが、まず最初に１０５ページの会計管理費のほうからということで伺います。会計事務が７つありますけれども、それが来年４月に施行されるということで、どのような方向で向かっていくのか教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"確かに地方自治法が改正になります。来年４月から収入役の廃止ということで施行になるわけでありますけれども、今後具体的な検討に入ってまいりたいと考えているところです。","id":"exchange-099"},{"speaker":"大沢委員","kind":"質問・要望","question":"１つ疑問に思ったのをぶつけしますけれども、収入役は特別職ということで、お互いにチェックとバランスの関係を持っていると私は理解しております。独立性というのか保たれるのか、それとも独立性を保つ何か担保というのは、きちんとしたものがあるのか教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"実際の収入役が執行権をいわば分担するという形で、今ご指摘にありましたように、お互いのチェック体制というものがとられていたわけであります。そういう兼ね合いも含めまして、どういう組織体制をとっていくのか、具体的な検討を進めたいです。","id":"exchange-100"},{"speaker":"大沢委員","kind":"質問・要望","question":"単なる表示板ということではなくて、地域のコミュニティーという部分でちょっと話をお伺いしたいと思うんです。このような住居表示をちょっと変えるというか、旧名を復活させたいなという議論がかつてあったのかどうか、説明を求めました。","respondent":"上川内戸籍住民課長","answer":"住居表示がされてから議論としてあったかどうかということですが、私の認識ではございません。","id":"exchange-101"},{"speaker":"大沢委員","kind":"質問","question":"私のサイドではないということは、地域ニーズもなかったと理解をしなければいけないんか尋ねました。","respondent":"山田区民生活事業部長","answer":"ご指摘された自分のまち、古い歴史を持っているまちの愛称という形でつないでいきたいという思いが、この中に私はあらわれていると考えています。昭和３７年の法に基づいて、利便性等を勘案し、効率的な施行ということで定着はしてきていると認識しています。","id":"exchange-102"},{"speaker":"大沢委員","kind":"質問","question":"１０年や２０年ではできない。僕は非常に重要なことだと思いますけれども、私の意見を述べた後に、その意見についてのご所見をお伺いしたいと思います。","respondent":"山田区民生活事業部長","answer":"今の歴史を考えて伝えていくという作業の中で、町名が非常に大事だと、私も考えてあります。そんなところと連携しながら、区は順次進めさせていただきたいと考えています。","id":"exchange-103"},{"speaker":"大沢委員","kind":"質問・要望","question":"日本というのは騎馬民族じゃなくて農耕民族ですから、定着性があるわけですから、本区の品格にもかかわってくると思います。この３つなんですけれども、予算に対して決算が半分という予算の立て方というのはどういう意味合いがあるのか、説明を求めました。","respondent":"榎本人事課長","answer":"年度内の欠員をどれぐらいの状況で見込むかということで、前年度までの状況、それから今年度の新たな状況等を加えて見込んでいるところですけれども。平成１７年度につきましても、若干破損時対応ということで、そういった意味で執行率が下がったというものです。","id":"exchange-104"},{"speaker":"大沢委員","kind":"意見","question":"より決算額に近いような額になっているんですけれども、これは今、３つとも倍なんですよ。今、半分の決算になったことについて説明をいただきましたけれどもとの意見を述べました。","respondent":"榎本人事課長","answer":"この中で予算に対して決算が同規模になるのは互助会の補助金だけでございまして、残り２つにつきましては、当年度の新たな予測というのがありますので、その中で執行していきたいと考えております。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"確認ですが、先ほどの交番の統廃合についてというお話で、さまざま委員のほうからもご質問がありました。西大井の３丁目、４丁目のところの交番もありますが、これはどのようになるのか尋ねました。","respondent":"金子生活安全担当課長","answer":"現在、警視庁の考え方ですと、交番から地区安全連絡所、仮称ですけれども、こういった形をとって、人員的にはそこに安全連絡員という形で警察のＯＢを何名か配属をするというふうに聞いております。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"要望として、しっかりと見守りをしていただきたいということで、これは要望にさせてほしいと求めました。もう決めてしまっていることなので、なかなかそれを変えろというのは難しいとは思いますが、その辺の事情を教えてほしいと求めました。","respondent":"田村地域活動課長","answer":"それと、やっぱり地域の歴史を、どういう形で変遷してきたかというのをやはり若い世代に引き継ぐという形がすごく大切かなと思います。それに合わせて再編というのは、もう長い歴史があるのでなかなか難しいかなと、そのように考えております。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"これは要望です。１００％やられているのかについてお尋ねします。","respondent":"久保田防災課長","answer":"学校の避難所連絡会議の開催状況ですが、設置は５８校全校で設置しておりますけれども、昨年度は３４校で実施しているという状況です。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"そうすると、１００％はされていないというところだと思いますが、その理由はどういうものでしょうか。避難所連絡会議がとれない、会議がやれない事情というのは何かおありになるのか尋ねました。","respondent":"久保田防災課長","answer":"やはりいろいろ、例えば学校長が異動でかわってしまったときとか、そういうときになるとブランクがあいてしまうというのが傾向としています。引き続き、私どももそういう形で声をかけて、できるだけ開催されるように今後もやっていくつもりです。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"やはりこれは、まず、避難所連絡会議そのものがあるというのがどこまで周知徹底しているかなというところがまず疑問にあります。今の状況だとわかっている、やはり末端までそれが周知されていないのではないかなというふうに感じるんですが、その辺はいかがか尋ねました。","respondent":"久保田防災課長","answer":"それは町会の役員たちを通じて、それぞれ町会員の方にはご周知はしておりますけれども、必ずしも隅々ということではありません。ただ、その役員が指示できるようになっていますので、一般の町会の方が来られてもその辺は支障がないかなというふうには思っております。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"町会等々の役員たち、非常に一生懸命地域の安全を守るために頑張っておられるのはよくわかります。中心になる人、声をかける人はだれになるのか、責任者はどこにあるのかということをまず確認させていただきたいんです。","respondent":"久保田防災課長","answer":"避難所連絡会議の議長は、そこに指定されている町会の町会長が議長になってあります。それだけではやっぱり十分ではありませんので、副校長先生が一緒に事務局として、これは町会長たちを支えて運営しているというのが実態です。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"学校の中に何かをしようというふうにはなかなか持ちにくい部分があるかと思います。そういう形でもう少し町会の方たちをサポートするような形で、やはり枠組みとしては学校単位があるわけですから、いかがか尋ねました。","respondent":"久保田防災課長","answer":"これではなかなか１つにまとまっていきませんので、私ども、各地区の防災協議会というのを毎年開催しております。ほかの地区にも今後そういう形で呼びかけて、今、委員がおっしゃっているような趣旨で充実していきたいというふうには考えております。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"もう１つ、この間、クラスにちゃんとここの避難所の対象になる地域の方は何番から何番地の人ですよというような表示があったんですね。それは全校には今後展開していくということはありますか尋ねました。","respondent":"久保田防災課長","answer":"教室の割り振りについては、ほとんどの学校がやってあります。今お話ししたように、それの対応ができていないところは一部あると思いますので、今後そちらのほうも充実させていきたいと考えています。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問","question":"次に、国際友好都市交流事業ですが、歳入が６５０万円余、歳出が７,７３０万円余あるんです。これは今後どういう形で、かなりの歳出になってしまっているんですが、考え方はいかがか尋ねました。","respondent":"桑村総務課長","answer":"昭和６２年度から始めているわけですけれども、区のほうがそこに補助金を出すような形で、そこの事業をそういう意味では支援していく。そういう意味で、７,０００万円の歳出につきましては、友好協会の補助金が主なものです。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問・要望","question":"これは要望で終わりたいと思います。大体年収によって違うというのはわかりますが、比較できる層、所得の層の中で比較ができれば教えていただきたいんです。","respondent":"高橋幼保一元担当課長","answer":"そして、私立の場合は、平均２万４,０００円。就園奨励費等、今、８,０００円と９,０００円の差ということで１,０００円ぐらいの差があるというところが私立幼稚園と公立幼稚園の差です。","id":"exchange-115"},{"speaker":"西本委員","kind":"質問","question":"済みません、保育園のほうはいかがですか。保育料との比較はいかがか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"どの階層が幾らというようなことではなく、一律応益負担ですので、私立幼稚園の場合は８,０００円になっています。４歳、５歳について一番高い方が１万９,６００円ということで、ちょっと比べることが難しいかなと思います。","id":"exchange-116"},{"speaker":"西本委員","kind":"質問","question":"例えば保育園の場合は２１階層ありますけれども、それの１０階層が大体の中間といいますか、そのできれば１０階層ぐらいのところとの比較はいかがか尋ねました。","respondent":"小林保育課長","answer":"年齢によって保育料相対に大分差がありますから、大体真ん中はどの辺になるかというと、大体Ｄ６ぐらいのところがメジャーに相当するかなと思います。Ｄ１０ですけれども、Ｄ１０ですと、幼稚園の場合は、四、五歳児ですけれども、Ｄ１０で１万９,６００円になっております。","id":"exchange-117"},{"speaker":"西本委員","kind":"質問・要望","question":"今後、受益者負担になっていくというところにおいては、この辺の私立幼稚園、保育園、それから保育園のほうの保育料の整合性というのは、今後どのように考えているのかだけ教えてほしいと求めました。","respondent":"小林保育課長","answer":"基本的には、幼稚園と保育園で保育時間等が違うというところはありますが、その辺の時間、それから保育・教育の内容を含めて勘案して、０－５歳トータルで公平性を確保するように保育料ないしは幼稚園の保育料を含めまして、体系については検討してまいりたいと思います。","id":"exchange-118"},{"speaker":"石田委員","kind":"質問・要望","question":"私は頑張っていただきたいなと考えていますが、そうなってくると、ネットワークをつくったらどうですかという答申があったと思います。こういうもののどことどことどこの課にどういう事業があって、そういうものも全部わかるようになっているかどうか、それを最初にお聞きします。","respondent":"堀越行財政改革担当課長","answer":"次世代育成支援の行動計画をつくりまして、その子育て支援のネットワークに関しましては、どういった形で示していけるのかというのも検討していきたいなというふうに思っています。","id":"exchange-119"},{"speaker":"石田委員","kind":"質問","question":"それをどういうふうにスタートさせるんだ、各学校で校長先生が頑張っていらっしゃって、いろいろなことをやっていらっしゃる。横串をしていくことが子育て支援にとっては本当に必要だと思うんだけれども、そこら辺の点のご見解をもう一度お聞きしたい。","respondent":"堀越行財政改革担当課長","answer":"協議会で進捗状況を管理しながら進めているわけですけれども、その協議会を開くに当たりまして、庁内で検討会を設けております。その中で、今、委員ご指摘のありましたような形についても検討を進めていきたいなというふうに考えております。","id":"exchange-120"},{"speaker":"石田委員","kind":"質問・要望","question":"済みません、そういう意味では、なかなか我々にも、我々が不勉強なのかもしれませんが、なかなか目に見えていないのが事実です。そこに課長なり係長なりいるのか、そういうものをつくるべきだと考えていますが、その考え方についてご意見をいただきたい。","respondent":"新美企画部長","answer":"近年また子育て支援が地域の中でやはり重要な問題になってきているという、支援室をつくることで可能かどうかも含めまして、どういう形で進めるべきか十分検討をしていきたいというふうに考えております。","id":"exchange-121"},{"speaker":"石田委員","kind":"質問","question":"区民に向けてみんなで一緒にやりましょう、横串はそこの課の人なら通せますよみたいなものをつくるべきだと思うんだけれども、そこら辺の考え方を説明を求めました。","respondent":"新美企画部長","answer":"私ども、組織をつくって、その機能がすぐ発揮できるのであれば組織をつくりたいと思いますが、組織だけで十分行くだろうかということもありまして、きょうのご質問も十分参考にさせていただきながら、来年度に向けて検討をさせていただきたいと思います。","id":"exchange-122"},{"speaker":"石田委員","kind":"質問・要望","question":"いろいろなものは前で質問していただきましたのでそれはいいんですが、例えば今言いましたように幼稚園、民間のものがある。区としては、数字だけでいいです、押さえているのか押さえていないのかだけ説明を求めました。","respondent":"日下部企画財政課長","answer":"私ども区といたしましても、例の事務事業評価、そこでコストの把握をする。イコールではございませんけれども、より合理的な１つの仕組みづくりということで検討を進めている、そういう経過があります。","id":"exchange-123"},{"speaker":"石田委員","kind":"質問","question":"私はそこの部分をしっかり人材育成ではないけれども教育をしてほしいなと思ってこの質問をしているわけです。教えていただいて、私はされていないと思っているんだけれども、そこら辺のところの話を説明を求めました。","respondent":"日下部企画財政課長","answer":"よく言われますように、官の場合は、例えばストックについての把握がなかなか十分にできていないとか、いろいろそういうご指摘もあります。例えば公会計のいろいろな検討なんかも今、今後の検討に生かしてまいりたい、このように考えています。","id":"exchange-124"},{"speaker":"石田委員","kind":"質問・要望","question":"そんなことは絶対にないわけで、行政側はどうしてもそういう、そこの部分が走りやすいのじゃないのかなと思っています。そういう方には、ぜひそういうのを伝えていただきたいと思うんだけれども、その考え方だけお聞きします。","respondent":"日下部企画財政課長","answer":"民間委託化に向けての検討を私ども企画部中心で各所管と連携しながらやっておりますので、そういう１つの検討の中で具体的なその辺の伝え方、その辺も含めて検討させていただきたいと思います。","id":"exchange-125"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうからは、２点教えてほしいと求めました。これは前、青少年広島の旅という形で行われていた事業がございましたけれども、これの目的と現況についてちょっと教えていただきましょうか。","respondent":"桑村総務課長","answer":"平成１５年度から、長崎については青少年対象で５名ということで、あるいは体験者の講話等を聞いていただいて平和について考えていただく。学校のほうにも伝えていただくというふうなことで、平和の意識というものを高めていただく、そういうことが目的です。","id":"exchange-126"},{"speaker":"堺委員","kind":"質問","question":"現在では長崎が平成１５年からということのようですが、中学校の２年生が各学校から１名ずつですか、そのような選出方式に改められたと。本人からの申請というんですか、その辺の決め方というんですか、それはどうなっているのか。","respondent":"桑村総務課長","answer":"平成１８年度につきましては、１名ずつ、１名参加していくような形になってあります。現在、大体８名から９名ぐらいの応募ということで、その中で抽選で５名の方に行っていただくような形になってあります。","id":"exchange-127"},{"speaker":"堺委員","kind":"提案","question":"私も平成４年、あのひめゆりの塔で有名な沖縄を含めた派遣事業に拡大をしていただきたいと、このように提案をさせていただいた経緯があります。こういう意味から、ぜひ拡大をしていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"桑村総務課長","answer":"その中で非核平和事業をどうやって進めていくかということで、１つは、１つは規模の拡大をいたしました。少しご検討の時間をいただきたいと思います。","id":"exchange-128"},{"speaker":"堺委員","kind":"質問・要望","question":"平和事業につきましては、ぜひひとつ拡充の方向で前向きにご検討ほしいと求めました。時間の関係で２点目に移りますが、約３００万円支出されておりますが、これの中身についてちょっと教えていただけますか。","respondent":"久保田防災課長","answer":"それから２つ目が、簡単な軽症に対応できるものということで、これを２セットずつ配備しております。その３つで３００万円弱です。","id":"exchange-129"},{"speaker":"堺委員","kind":"質問","question":"それと合わせまして、私はこういう地域センター単位に決めた１３の学校には、救護所という明確に位置づけられたところがあるわけですから。その辺も含めましてご答弁いただけますか。","respondent":"久保田防災課長","answer":"必ずしも地域センターに近いところだけではないんですけれども、ほとんどが地域センターに近いところであります。それから、トリアージをするということになっていますので、そのための訓練を学校を会場にするところについてはほとんどやってあります。","id":"exchange-130"},{"speaker":"堺委員","kind":"質問","question":"ほとんどということですが、例えば、今回も私、ある防災訓練をやっている学校に２カ所行きましたら、こういう形を含めた防災訓練になっていなかったと思うんですが、いかがか尋ねました。","respondent":"久保田防災課長","answer":"第二延山小学校でもやったことがあると思います。これからもそういう形で充実します。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"成果報告書の１０２ページの庁舎等維持管理費の考え方と、各種団体分担金、これは特別区人事・厚生事務組合と特別区協議会について質問します。新築すれば私のちょっと考え方で６０億円ぐらいでできてしまうのではないかと思うんですけれども、実際大丈夫なのかどうか、その辺。","respondent":"宍戸施設担当課長","answer":"１００億円前後かかるのではないかということもありますし、あと、今のところ補強工事という方法がいいのではないかと考えているところです。耐震補強工事をすれば、躯体の耐用年数からすれば、２５年前後はこれから使い続けられるのではないかというふうに考えております。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問・要望","question":"２５年もつということなんですが、しっかりしていれば、ちょっとその辺はしっかり今後業者と検討しながらやっていってほしいと求めました。ある建設業者に聞きましたら、３億円か４億円で直角の建物なんかは筋交い等を入れれば補強できるという話なんですが、その辺はどうなんでしょう。","respondent":"宍戸施設担当課長","answer":"今回のことに限らず、改修工事というのは、１つは古くなった建物自体、設備も含めてですけれども、それを更新するという側面があります。もう１つは、機能自体が古くなったために更新するというふうな考え方もございまして…","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、品川区のほうでは、２億３,０００万円、毎年分担金として出しております。これの収支等につきまして、監視体制はきちんとできているのか、また品川区の職員もここに派遣されているのか、その辺をちょっと説明を求めました。","respondent":"桑村総務課長","answer":"もう１つは、それについては別のいわゆる地方公共団体ですので、その中で一定の職員がおります。執行機関等につきましても、先ほどと同じような状態です。","id":"exchange-134"},{"speaker":"須貝委員","kind":"意見","question":"そして、さらに有価証券として２６億円ありまして、預金も１５億円ストックされていると。それに対して、毎年一定の応分の分担をしていると、積み上げているということに関して、ちょっとご意見を説明を求めました。","respondent":"桑村総務課長","answer":"それからもう１つは、区政会館の運営ということをやっておりますので、かなり大きないわゆる維持管理費をつくっているものです。それから、各区の分担金でやっているような形ですので、必要な事務について各区の議会等の議決をいただいて歳入として計上しているものだと思います。","id":"exchange-135"},{"speaker":"須貝委員","kind":"意見","question":"実際これだけどんどんストックが増えているわけなので、それに対して各自治体が毎年２億３,０００万円の分担金を出すというのは、ちょっといかがなものかなというふうに思いますので、一応それだけ意見を言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-136"},{"speaker":"築舘委員","kind":"質問・要望","question":"毎月第１日曜日を決めていて、この効果の度合いがどの程度になっているのかなというのをお聞かせいただきたいということ。その辺のことをどうしていくのかというのは、もう少し詳しくお聞かせいただきたいということと、そのあたりを聞かせてください。","respondent":"桑村総務課長、田村地域活動課長、鷹倉区民課長","answer":"ただ、その意味では親善訪問団だということで３８名の方に行っていただいたわけですけれども、向こうで十分な交流事業をやっていただきました。… ２点目の地域食事サービスの件ですが、やはりもともとの設置の考え方が、毎週火曜日と木曜日で週に２回です。やはりできるだけ外に出たり… その分、従来からお話が出ています民間の施設複数、４７人分を選択的に確保できるような方式を今のところ進めようとしております。先ほどお尋ねの品川荘な…","id":"exchange-137"},{"speaker":"築舘委員","kind":"質問・要望","question":"家庭が基礎ですから、一番のもとなので、そのあたりはある意味では区だけでやるのかどうかという問題にもなってくるわけだと思うんです。やはり週２回ということですから、少しずつ改めていかなければいけないのではないかというのが１つ、この点についての私の意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-138"},{"speaker":"土井委員","kind":"質問・要望","question":"さてそこで、これが今どうなっているのかなというところをちょっとお伺いをしたいと思うんです。アベレージ的にはどうなんだろうかということをまずお伺いをしたいと思います。","respondent":"榎本人事課長","answer":"必ず面談をするという形に変わりまして、その職員を呼び出して健康状態がどうなのだろうかという形できちんと面談を進めている状況です。働き方、その家庭生活を見直していくという形もありますので、引き続き時間外勤務の縮減を進めていきたいというように思っております。","id":"exchange-139"},{"speaker":"土井委員","kind":"質問","question":"１００時間を超えるのが二、面談をしてやっているというお話だったんですけれども、どういう部署なんでしょうか。それによっても対策が違いますので、対応、対策を含めてどう考えているのかというところをひとつもう１回。","respondent":"榎本人事課長","answer":"そのほか、短期的に１００時間を超える者につきましては、選挙管理委員会事務局の職員がやはりそういうものに該当しているという形です。平成１７年度につきましては大体５０人ぐらいがその月１００時間を超えるところに該当してくるという形です。","id":"exchange-140"},{"speaker":"土井委員","kind":"質問・要望","question":"選挙のときに選管事務局の皆さんが残業するのは、ある意味ではそれが仕事ですから選挙事務のところについてくるんでしょうね。どういう残業時間等になっているのかなというのをちょっと考えてしまったものですから、どのように掌握、把握をされているのか尋ねました。","respondent":"榎本人事課長、野田口選挙管理委員会事務局長","answer":"そのほかの応援職員は兼業という形で扱っておりまして、事業費の中にその兼業に対する部分が対応しております。決算特別委員会対応のときの時間外の把握ですけれども、その中だけをちょっと時間対応を切り出すというのが… 事務従事者の経費がどこに載っているかですけれども、選挙費のところで、投票事務の従事者については投票事務、開票事務のところに、それぞれのところの事業で掲載されてあります。","id":"exchange-141"},{"speaker":"土井委員","kind":"質問","question":"問題といいますか、改善を要するという部分で、そしてそれは今後も含めてどのようにしていくのかということをちょっと伺いたいと思うんです。ただ問題は、そこら辺についてちょっと認識をどうされているのか、これからどう考えられていくのかを少し伺わせてください。","respondent":"野田口選挙管理委員会事務局長","answer":"回示する、この２つが第２回、それから個別に回った部分の数をなかなか確認しがたいというところが改善すべき問題点かなというふうに思います。それからもう１つは、一たん積載台のほうに移動したものを…","id":"exchange-142"},{"speaker":"土井委員","kind":"質問・要望","question":"開票事務ですからどんどん進んでいくんですね。それをさらに確認が終わったよと持ってくる、少なかったのか、まさか二度勘定しなかっただろうなとかという話になってしまう。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-143"},{"speaker":"三上委員","kind":"質問・要望","question":"成果報告書１０６ページ、情報伝達的な部分についての件でちょっとお伺いしたいと、こう思います。それから、同じく受水槽遮断装置設置５１校ということでありますが、これについても少々説明をいただきたいと。","respondent":"久保田防災課長","answer":"そこに組立式の仮設トイレを設置して使用する、こういうふうになってあります。下水道を流すための水を一たん受水槽にためて、そこを防ぐために地震をセンサーで感じて自動的に遮断する装置をつけていると、こういうことです。","id":"exchange-144"},{"speaker":"三上委員","kind":"提案","question":"ついでですから質問していきますけれども、これも簡単でいいですからお伺いしたい、こう思います。最後にもう１つ、時間があれば、崖崩れ等についてお伺いしたいと思いますとの意見を述べました。","respondent":"久保田防災課長","answer":"それから、安否情報についてなんですけれども、安否情報は２つの考え方があると思うんです。例えば、ＮＴＴの伝言ダイヤル的な１７１の災害電話の活用とかというものがあるかと思いますので、これはＮＴＴと一緒にＰＲしているという状況です。","id":"exchange-145"},{"speaker":"三上委員","kind":"提案","question":"仮設トイレの件については、そういったことについてのせっかく新しい学校をつくっていこうとする状況下にあるわけですから、こう思います。こういう考え方の中から提案しているわけでありまして、あそこに１,５００ｔあるからいいや…","respondent":"久保田防災課長","answer":"今一番考えているのは、やはり災害情報の伝達ということで、ケーブルテレビをより活用しようということでいろいろ検討を重ねてあります。委員がお話になった携帯電話についても今後もっともっと研究を進めていきたいというふうに考えております。","id":"exchange-146"},{"speaker":"三上委員","kind":"提案","question":"いずれもしっかりと研究をしていっていただきたいということで提案しますので、真剣に受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-147"},{"speaker":"宮崎委員","kind":"質問","question":"私は、成果報告書１０３ページ、品川文化振興事業助成金に関連しましてアルゼンチン国債の問題について改めて伺いたいと思います。この不正を許さない高い倫理意識、そういう決意で区政運営に当たるのかどうなのか、まず初めに伺いたいと思います。","respondent":"濱野区長","answer":"そのとおりです。","id":"exchange-148"},{"speaker":"宮崎委員","kind":"質問・要望","question":"初めに伺いたいのは、文化振興事業団からアルゼンチン国債の問題では、結局、損害が幾らになったのか、その報告は受けたでしょうか。受けてあれば、その金額、内容についてもお知らせほしいと求めました。","respondent":"鷹倉区民課長","answer":"文化振興事業団の委託元という立場で、私が答えします。結果につきましても、文化振興事業団の理事会あるいは評議員会において、平成１７年度の事業報告という形で了承済みというふうになってあります。","id":"exchange-149"},{"speaker":"宮崎委員","kind":"確認","question":"ということは、それはもう文化振興事業団の内部で報告しているからそれで終わりという態度なんでしょうか。そこのところを確認したいと思います。","respondent":"鷹倉区民課長","answer":"私ども区から補助金が出ているわけですけれども、その補助金が適正に執行されているかどうかの区の監査についても既に済んです。適正に執行されているということを私ども報告を受けてあります。","id":"exchange-150"},{"speaker":"宮崎委員","kind":"確認","question":"当時の副理事長ですね、購入した直接の責任者、そして指示を受けて購入した元事務局長に対する処分等はあったんでしょうか。あればその内容、事業団のほうの処分、そして役員を派遣していた側の区としての処分があったかどうか確認したいと思います。","respondent":"山田区民生活事業部長","answer":"文化振興事業団におきますアルゼンチン債の問題については、この間、再三お答えをしています。文化振興事業団の中で評議員会、理事会という組織があり、それぞれのところで審議をいただいて、決定をして、今、粛々と進めているところです。","id":"exchange-151"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、そういうことをしっかりこの損害が確定した時点で受けるべきだという、そういう問題意識から質問しているんです。区の理事者に伺います。","respondent":"山田区民生活事業部長","answer":"それぞれ都の監査、区の監査も受けて、適正な会計管理は実施をしている。責任、その問題については自分の管轄の中として理事長を辞任するという形で私どもは一定の終了を得ているというふうに考えてあります。","id":"exchange-152"},{"speaker":"宮崎委員","kind":"確認","question":"こういう場合には、処分を受けるようなことはないのでしょうか。公金を不正なやり方で使ったということは、そういう場合の処分というのはないのか尋ねました。","respondent":"山田区民生活事業部長","answer":"これは区としての立場としてはお答えしがたいと。それは区が申し上げることではないというふうに解釈しております。","id":"exchange-153"},{"speaker":"宮崎委員","kind":"確認","question":"どこの判断ですか。それを確認したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-154"},{"speaker":"宮崎委員","kind":"質問","question":"それを半年間、高橋区長に報告しなかったということなんですけれども、この調査報告書では、なぜ半年間報告しなかったのかということが書いていない。当時の調査団、その調査団はなぜこの半年間報告しなかったのかということを報告書に書いていないんですが、これは事業団にただしたのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-155"},{"speaker":"宮崎委員","kind":"質問","question":"委員長、ちょっと説明すると、これは平成１４年３月４日に総務委員会に提出された資料。財団法人品川文化振興事業団の財産管理に関する調査報告、これについて質問しております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-156"},{"speaker":"宮崎委員","kind":"質問","question":"この点がちょっと不十分ではないのか、この点を聞いたのか、ただしたのかということを聞いているんです。その点について、なぜ答えられないのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-157"},{"speaker":"宮崎委員","kind":"質問","question":"だから私は質問しているんですよ。調査したんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-158"},{"speaker":"宮崎委員","kind":"質問","question":"私はこの報告書に基づいてやっているんですから、議会への説明ですよ。なぜ当時の副理事長の濱野現区長が調査委員会の責任者になったのか、ここのところは高橋前区長からどういう指示を受けたのか尋ねました。","respondent":"山田区民生活事業部長","answer":"既に文化振興事業団の中で、理事会、評議員会という形で議論する場としています。それも何年もたってそれぞれのところでやってきているわけですから、このことの部分で、今、私どもに聞かれましてもお答えできないです。","id":"exchange-159"},{"speaker":"宮崎委員","kind":"質問","question":"それ以降、じゃあどうだったのかというと、理事会への報告、決算報告等でも、このアルゼンチン国債のアの字も、外国債のガの字もないんです。あるいは外国債と書かなかった理由について、ここのところでは調査団のところでは、調査委員会はここのところはどういう調査をされましたか。","respondent":"山田区民生活事業部長","answer":"今、アルゼンチン債か国債かというご指摘がありますけれども、この点も含めて、理事会、評議員会という別の団体、法人の中で、きちんと議論されることが一番進むことだということで、区としてもそう考えているです。","id":"exchange-160"},{"speaker":"宮崎委員","kind":"意見","question":"購入を事後承認させたというのは、非常に外から見たら、くさいものにふたをしてもみ消したというふうにしか受け取られないです。このことを指摘しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-161"},{"speaker":"須藤委員","kind":"意見","question":"１つは、補助金といろいろな事業費の関係というのはどういうふうになるのかなというのと、それから助成金と補助金との兼ね合いがどうなるのか。その辺を１回、そのあたりは１回整理をされたらどうかと思うんですが、まずお考えを聞かせてくださいとの意見を述べました。","respondent":"日下部企画財政課長","answer":"そのうちの１つとして、事業全般の中で町会連合会に対する助成金という形でそれを内訳として計上させていただいていると。そのような形で計上については区分けをしているというものです。","id":"exchange-162"},{"speaker":"須藤委員","kind":"質問","question":"そういったことが考えられてくるので、そのあたりを一度整理されたらいいと思うんですがいかがでしょうか。１０７ページの区民斎場運営費と、それから臨海斎場については５区で運営をしていくという形になるので、そのあたりがわかれば説明を求めました。","respondent":"日下部企画財政課長、鷹倉区民課長","answer":"助成金等についての考え方ですけれども、整理につきましてはもう少し工夫をするように努めてまいりたいと、検討させていただきたいというように思います。 その影響で平成１６年度については、区民斎場なぎさ会館は落ち込みました。ただ、お客様が私どものほうのなぎさ会館のほうに復帰されているというのが平成１７年度の状況というような状況です。","id":"exchange-163"},{"speaker":"須藤委員","kind":"質問","question":"臨海斎場で品川区民の利用はどの程度あったのかというのを教えてください。今までと同じような絵でつくっていくのではなくて、何らかの策をしていかなければいけないだろうと思うんですが、いかがか尋ねました。","respondent":"鷹倉区民課長","answer":"全体が１,３８８件、うち品川区が３３４件ということで２４.１％というような形で、前年に比べれば伸びているような状況になってきてあります。したがいまして、利用が伸びていくのではないかと、このように考えているところです。","id":"exchange-164"},{"speaker":"須藤委員","kind":"質問","question":"それから、補助金がやはり１,７００万円で、実際に執行がそれにプラス９００万円ぐらい足されたような費用になってきている。このあたりもどういう育成の仕方をされているのかなというのを教えてほしいと求めました。","respondent":"久保田防災課長","answer":"大きくは２つありまして、それに基本額を掛けまして、その分を支援しているというのが１つです。あくまでも防災区民組織、使用する内容については、各防災区民組織でこれは任せていろいろなものに活用していただいているというのが実態です。","id":"exchange-165"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほど来いろいろあると思うので、そのニーズに合うように、今後いろいろ検討されていってほしいと求めました。ページ１０４に関係して、品川区としては、このことについてどういう経緯でタッチされてきたのかお知らせください。","respondent":"金子生活安全担当課長","answer":"もともと交番の統廃合がある以前から廃止ということがかなり高度な確率で実施されていることを聞いております。したがいまして、他の４つの交番と荏原町駅前交番については全く趣が異なりまして、そういう考え方で取り組んでまいりました。","id":"exchange-166"},{"speaker":"須藤委員","kind":"質問","question":"自民党でもそのことを討議しまして、第４回定例会で一般質問させていただきました。そのときに、所轄の署長にお会いになったりといろいろやっていただいたという経緯があるんですが、いかがか尋ねました。","respondent":"金子生活安全担当課長","answer":"そのとおりです。","id":"exchange-167"},{"speaker":"須藤委員","kind":"質問","question":"それはどういうふうに対応するんですか。おい、とっ捕まえようというのでやったところが過剰防衛になってしまったというようなときは、今度はどういうふうになるんか尋ねました。","respondent":"金子生活安全担当課長","answer":"非常に難しい問題です。行き過ぎのない、過剰防衛あるいは犯罪に抵触するようなことのないように、いろいろな形でお話をする機会を設けていきたいと考えております。","id":"exchange-168"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、きちんとそういった保険だの何だの手当てをしていただけるようなシステムを構築しておいてほしいと求めました。いかがか尋ねました。","respondent":"金子生活安全担当課長","answer":"十分検討させていただきたいと考えます。","id":"exchange-169"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/754385?Template=document&Id=1262#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":117097,"voices":379}},{"id":"h18-20061017-4","meetingId":"h18-c-settlement","date":"2006年10月17日","dateIso":"2006-10-17","committee":"決算特別委員会","time":"午前１０時０２分～午後６時１５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を145件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"それと１１５ページの障害児放課後生活サポート事業、その後１１３ページの介護予防ですとか、その辺を質問させてほしいと求めました。１１５ページの障害児放課後生活サポート事業なんですけれども、その目的がどこまで達成できているのか、その辺をまず説明を求めました。","respondent":"蓼沼高齢福祉課長、西島障害者福祉課長","answer":"平成１７年度につきましては３３名就職をいたしまして、このうちの２２名が区内の法人、あるいは関連の事業者。残りの１１名が区外の法人等というような状況です。 １日あたりの利用者数で申し上げますと、平成１５年度が４.４人、それから平成１６年度が６.８人、それから平成１７年度が７.５人となっています。平成１７年９月から実施した事業でございまして、そういう意味では…","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"その辺はしっかりとやっていただきたいと思うんですけれども、例えば高齢者の問題で、その辺ちょっとお聞かせいただきたいと思うんです。障害児に対しても、介護福祉専門学校で「この部分が大事だ」というような部分をカリキュラムでどのように吸収できるのか、その辺を説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"特に、認知症高齢者が今後増えてくるということで、認知症ケア、認知症対応の時間を増やしているというところが最近の傾向です。ご質問のありました音楽療法ですとか、そういった音楽療法に関する取組についても、カリキュラムの中に取り入れているところです。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"そういう取り組みもあるということなので、これは学校に限らずいろいろな現場でも視野を広げてほしいと求めました。そうでないところにはそれなりの対応という、その辺の社会全体でのニーズが高まっていると思うんですが、その辺の考え方について説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"今後の予算に対する考え方につきましても、あるいはニーズの変化に対しまして、適切に対応してまいりたいと思います。こういった点でも、介護職の育成・確保というところでは、区として全面的なバックアップをしているという状況です。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"これからの高齢化に対しての対策ですから、もう何年も前なんですけれども、健康増進ということでぶら下がり健康器が一時期はやりました。もちろん、今、取り組まれている高齢者への対策としてはほんとうにありがたいと思いますが、ちょっとだけ教えてほしいと求めました。","respondent":"冨岡高齢事業課長","answer":"平成１７年度にモデル実施をさせていただきまして、２回行っておりましたが、平成１８年度におきましては拠点を３カ所広げる予定でございまして。それから関ヶ原の竣工に伴いまして、こちらのほうでもコースを開始する予定で、多くの方にご利用いただきたいと考えています。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私からは、１１４ページの支援費関係と、民間賃貸住宅の家賃助成についてお伺いします。ここでぜひお伺いしたいんですが、国の悪政をただして区民を守る地方自治体の立場に立っていただきたいんですが、いかがか尋ねました。","respondent":"西島障害者福祉課長","answer":"おっしゃっていることは私も十分納得できる部分もございましたけれども、私が感じましたのは、説明が少し不足しているんではないかと。障害者自立支援法、さまざまな３障害を１法にするとか、今後とも進めていきたいと考えているところです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区長にお尋ねしたんです。スウェーデンの８分の１、ぜひしっかりと示していただきたいんですが、いかがか尋ねました。","respondent":"西島障害者福祉課長","answer":"障害福祉サービスを充実・発展させていくためには、あるいは障害者以外の理解を得るためには、一定の負担というのは必要であろうと考えています。それから、それにあわせて東京都、それから品川区もそれに上乗せする形で軽減措置を実施しています。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"この間のご答弁でよく伺うのが、「これは多過ぎる」とか、「不公平である」とかいうような声がどこからか出ていたんでしょうか。私は、税金の無駄使いをただせはこんなひどいことを言わなくて済むと考えているんですが、裏づけは何なんか尋ねました。","respondent":"西島障害者福祉課長","answer":"今回の法律改正につきまして、私ども、懇切丁寧に説明をさせていただきました。私だけでも各団体、あるいは各法人に行って説明をしてくれというのは、おそらく１０回では足らないぐらい説明いたしました。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"ほんとうにこの負担が大変だということは、この間、多分区のほうも伺っていると思うんですね。今、答えていません。","respondent":"西島障害者福祉課長","answer":"負担率がおそらく１％ぐらいだというふうに思っております。障害者福祉サービスを充実していく、サービスを向上させていくというふうに活用していくことが大事ではなかろうかと考えているところです。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ガイドヘルパーの点なんですけれども、たびたび要望がいっぱい出ているわけですけれども、ぜひこのガイドヘルパーを無料に。そして、ぜひ全身性の障害のある方にも利用できるようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"西島障害者福祉課長","answer":"２点目の地域生活支援事業、特に移動支援にかかわるお尋ねですけれども、地域生活支援事業。４月から６月までの数字を見ましたところ、あるいは負担の公平性を考えて、このまま実施して参りたいと考えているところです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"区によって１０倍ぐらい違う区があるというので、もっと使い勝手がよくなってほしいなと思うのでその辺が１点と、一体この額的にはどのぐらいなのか。今回の自立支援に移った場合にどのぐらい差があるのかというのと、負担軽減策の総額を、品川区はどのぐらいではじき出しているのか説明を求めました。","respondent":"西島障害者福祉課長","answer":"いわゆる支出事業と言われている４事業を実施するということで、おそらく１億３,０００万ぐらいが地域生活支援事業に該当するのではなかろうか。実績割と人口割ということになってきましたので…","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"負担増になった部分は障害者の皆さんに返してていただきたいなと思うんですが、自治体の中で、区の独自策を行っているわけなんですね。今回の障害者福祉を根底から崩すような応益負担、これを少しでも負担をなくすための努力を、ぜひ区でしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"１１６ページのシルバーセンター運営費、１２０ページの生活支援型一時保育の３点をお伺いしたいと思います。具体的にはどんな内容をされているのかということと、この平成１７年度で結構なので、実績を説明を求めました。","respondent":"志村生活福祉課長","answer":"ホームレス地域生活移行支援事業の事業内容についてご説明を申し上げます。そのうち、生活保護の申請に至った方は５人というような事業内容です。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"非常に詳しくありがとうあります。それは民間のアパートにお住まいなんでしょうか、６区が増えている、その辺の事情等がわかりましたら教えてほしいと求めました。","respondent":"志村生活福祉課長","answer":"ですので、私ども平成１６年度にホームレスの調査を実際に行いまして、あの人はホームレスじゃないかな」ということでカウントしたです。この駅舎の１７人につきましては、今、考えているところです。","id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"ＪＲの大井町の東急のところに、１人小柄の男性が、あの辺を通るとよく見かけるんですね。ああいう方には具体的にはどんな対応をされているのか、それともしようとされているのか、具体的に教えていただけますか。","respondent":"志村生活福祉課長","answer":"健康状態等も含めて、そうしたところで１カ月間、健康の回復を図るという方法もあるんじゃないでしょうかということを何回も申し上げてあります。特に平成１８年度からは、こうした訪問相談事業というのを開始しています。","id":"exchange-014"},{"speaker":"武内委員","kind":"質問・要望","question":"それから１１６ページのシルバーセンター運営費のところで、それでパブリックコメントが求められて、それでこれは決定されたんでしょうか。それとも、決定されていないとすれば、西大井のシルバーセンターについてはいつごろ決定するんか尋ねました。","respondent":"日下部企画財政課長","answer":"西大井のシルバーセンターですけれども、今、委員ご指摘ございました原小学校跡への移転ということですが、今、検討を進めているという状況です。議会、それから地域からもいろいろご意見をいただいているということで…","id":"exchange-015"},{"speaker":"武内委員","kind":"質問・要望","question":"これについての有効活用というのが図られなきゃいけないんじゃないかなと感じておるんですけれども、まだ先の話にはなると思うんですけどね。原小学校の跡についてパブリックコメントをやられましたけれども、そのパブリックコメントを求める基準みたいなのは何かあるんか尋ねました。","respondent":"日下部企画財政課長","answer":"前回、第一日野小学校のときにもホームページに掲載をしてご意見をいただくということで進めてまいりました。幅広く区民の皆様のご意見をいただくような、そういう必要性があるものについては、そういう取組みを進めてまいりたいと考えています。","id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"比較的４０代、５０代の方の健康ということで、これはぜひ参考にしてほしいと求めました。平成１６年度、１７年度、もしわかりましたら教えてほしいと求めました。","respondent":"小林保育課長","answer":"平成１７年度は、６月より５園を追加し、１０園で６,３６５名です。平成１８年度は、現在９月までの集計ですが、同じく１０園で３,２４３名です。","id":"exchange-017"},{"speaker":"武内委員","kind":"質問・要望","question":"９月までで３,２４３ということなので、保育園では狭いんじゃないかとかいろいろそんな声も聞いているんですけれども、その辺の課題みたいなところがありましたらお知らせほしいと求めました。","respondent":"小林保育課長","answer":"需要に対する対応ですけれども、感触といたしましては、現在の１０園で、各地区の需要にはほぼ対応できているかなという感触は持ってあります。あるいは学校の参観日への対応、これを在宅子育て支援事業の一つの柱として、在宅支援に取り組んでおります児童課との連携を持って。","id":"exchange-018"},{"speaker":"武内委員","kind":"質問・要望","question":"うちの若林議員も児童センターの拡充ということでやらせていただきましたが、そういった児童センターの活用について、今後の何かがありましたら教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"在宅子育て支援ということで、あるいは乳幼児親子の居場所づくりということで、親子サロン等整備を進めてきたところです。今後におきましては、保育課のほうとも連携を進めまして、一体的に地域における子育て支援を進めていきたいと考えております。","id":"exchange-019"},{"speaker":"阿部委員","kind":"質問・要望","question":"諸先輩方を見習い、そして理事者の方々のお知恵をお借りしながら頑張っていきたいと思いますので、お手やわらかにお願いいたします。本日私が質問させていただきたいのは、１１９ページ、それぞれの金額について教えてほしいと求めました。","respondent":"小林保育課長","answer":"教材費の関係ですが、保育園の教材、もしくは教材的な消耗品ということで、２,６００万円弱。その他、行事用の消耗品、維持管理の消耗品、厨房関係等あわせまして、こちら３億１,９００万円余の金額になっております。","id":"exchange-020"},{"speaker":"阿部委員","kind":"質問","question":"今、教材費が２,６００万円弱ということだったんですけれども、これ、保育園の定員３,２６２人、実際にはもうちょっと多いかと思うんですが、ざくっと計算しますと８,０００円弱ぐらいと計算できるかなと思うんですが、よろしいか尋ねました。","respondent":"小林保育課長","answer":"賄費・教材費、今年度３億３,７００万円余です。訂正します。","id":"exchange-021"},{"speaker":"阿部委員","kind":"質問","question":"幼稚園の平成１７年度の在籍児童が５３９人とお伺いしておりますので、かつ、一方で保育園のほうは子どもを平均８時間ぐらい在園している。登園日数につきましても、幼稚園は保育園の３分の２程度であるということを勘案しますと、この辺についてはどのようにお考えか尋ねました。","respondent":"小林保育課長","answer":"１万円を切れる金額という点がありますが、この間、保育園におきましても教材・教具の整備を進めている点があります。ただ、今後、幼児教育の充実等のニーズがありますので、幼稚園・保育園問わず、教材・教具の充実には努めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"阿部委員","kind":"質問・要望","question":"３歳から５歳児、保育園におきましても、教材費の一層の拡充というものを行っていただきたいと考えています。就学前の子供たちの育っていく環境の条件をそろえていくという意味でも、この辺の改善があってしかるべきだと思うのですが、いかがか尋ねました。","respondent":"小林保育課長","answer":"園の間の調達、それから多少ルール外であっても必要なものは、保育課のほうで調達するようにしています。今後も、その辺の状況に応じて、現場で十分な保育ができるようにという配慮は継続してまいりたいと考えております。","id":"exchange-023"},{"speaker":"阿部委員","kind":"質問","question":"次の質問に移りたいと思います。先ほどもちょっと質問で出てきたオアシスルームなんですけれども、ちょっと私理解不足でして、一時保育のところでよろしいのか尋ねました。","respondent":"小林保育課長","answer":"ページ数から申しますと、お手元の成果報告書１２０ページの上のほうにあります。こちらの金額につきましては、経費として計上しているのは、人材派遣の経費等が主なものとなっております。","id":"exchange-024"},{"speaker":"阿部委員","kind":"質問・要望","question":"すみません、これは不確かな話で、間違っていたらご指摘いただきたいんですけれども、このオアシスルームについて、今後、保育園と切り離して部分委託をするようなお考えも、区役所の中にあるのではないかという話を聞きまして、そういったお考えがあるかどうかというのをまず確認させていください。","respondent":"小林保育課長","answer":"どういった体制でやっていくのが子育て支援として一時預かり、臨時の在宅支援のニーズに対応できるのかという形で、対応を検討しておるところです。保育かという子育ての担当部署と連携することによって、サービスの向上と資源の活用を進めていくということを…","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"すみません、まだちょっと言葉遣いに慣れなくて。その中で執行体制を考えていく、工夫をしていくということことは、委託も含めて考えていくというふうな理解でよろしいか尋ねました。","respondent":"古川児童保健事業部長","answer":"在宅の子育て支援の大きな柱というふうにとらえておりますし、１０園で６,０００名、決算が約６,０００万ということをとらえましても。お子さんに対して公平に提供していくか、こういう観点から全体を見て判断していくものだろう、このように考えております。","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"私としては、そのように評価していたものですから、そういった視点もできれば加えていただいた上で総合的に判断をしてほしいと求めました。これは仕組みとしてお伺いしたいんですけれども、その仕組みについてお伺いしたいんですが、保育園ではかなり多く見られることと思うんですが。","respondent":"小林保育課長","answer":"その場合に転園希望が出てまいりますが、基本的にはこちら、転園も通常の入園申し込みと同じルールで、その必要性に応じて対応しております。ただ、全く同水準であった場合には、お１人入っているという点での若干の考慮はしています。","id":"exchange-027"},{"speaker":"阿部委員","kind":"質問","question":"既にどちらも入所している子どもの転園についてお伺いしたんですけれども、一つ動けば一つは空きが出るわけですから、理屈としては。要は、ある保育園への転園と、その保育園でないところでもいいという希望がある場合には、どちらが優先されるのか尋ねました。","respondent":"小林保育課長","answer":"できれば一緒にしたいので、Ｂの弟さんを、お兄ちゃんのいるＡ園のほうへ転園を希望するというような形で申請が上がってまいります。Ｂに空きが出るというところにつきましては、このＢを単独で入園希望されている方の中から入所者を決定している、そういうシステムです。","id":"exchange-028"},{"speaker":"阿部委員","kind":"質問","question":"手続のことを長々と聞いて失礼いたしました。なかなか利用者にとってわかりにくい部分があるものですから、結果どうであったというのを、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"１１９ページの保育園運営費と、時間がありましたら１２１ページの家庭あんしんセンターについてお伺いいたしますが、まず保育園ですが、ここ数年の申込者数と、入園決定者数を説明を求めました。","respondent":"小林保育課長","answer":"平成１７年度の推移といたしましては、申込者数が１,１９５、入園者数は９９６。平成１６年度は１,１４４に対しまして９６０と、ほぼ同程度で推移しています。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"すみません、もう１回数字をお伺いしますが、この年度でいいので、待機児の推移と、それと特徴についてお伺いします。","respondent":"小林保育課長","answer":"具体的に４月をまたぎまして、残念ながら４月１日に入園できなかった未入園者ですので、意思表示をしていただくんですね。こちらの意思表示、４月２日以降もまだ入れていないので入園を希望しますよとご回答いただいた方は、９０名弱の水準です。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"その辺の減らす展望についてお伺いしたいのと、雑誌等を見ていますと、いろいろな施策がある中でも子育て支援が特にいいよ」という形で出ております。子育てするならば品川区という形で思っている方が多いと思うんですけれども、それを考えつつ、待機児の解消はどのように考えているのか尋ねました。","respondent":"小林保育課長","answer":"これに対する対応といたしましては、広く言えば幼保一体等の動きも含めまして、乳幼児に対する待機児の解消に努めてまいりました。１歳、ゼロ歳児の定数を１歳児に振りかえる等の対策によりまして、１歳児の入園促進に努めているところです。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"お伺いしたんですけれども、そういうことを実施していくと、当然保育のコストというのは増加していくと思います。一部を民営化するお考えがあるのかというのが１点と、濱野新区長は、できましたら理由も含めてご答弁してほしいと求めました。","respondent":"古川児童保健事業部長","answer":"さらなる保育行政、子育て支援の充実を図っていきたい、このように思ってあります。そういう考え方には、現時点では立っていないというふうに、私は考えております。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"成果報告書の１２１ページの生活保護費と、１１６ページの社会福祉施設費の心身障害者福祉会館運営費についてお伺いをしたいと思います。その点で要望、困っていることとか、そういった要望は区のほうには届いていないか尋ねました。","respondent":"志村生活福祉課長","answer":"実績報告にありますとおり、８７億のうち、医療扶助は４５億、半分以上を占めているものです。生活保護世帯の子にはそういうカードがありませんので、これはあくまでも、この中で解決すべき問題だろうと考えております。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"今の、子どもたちにとってどうなのかって、すごく大切な問題だなと思っています。すべての人に受給者証をということではないにしても、そこのところを品川区で検討してほしいと思いますけれども、その点についてはどうか尋ねました。","respondent":"志村生活福祉課長","answer":"ですので、先ほどご答弁したとおり、これは私ども一自治体でというのはなかなか難しいと思ってあります。最終日に「こういった要望がありました」ということで伝えていって、東京都からでもそうしたことを発信していただくようにお願いしたいと思います。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ、品川区として積極的に働きかけをしていただいて、実施いただきたいと要望します。それからもう１点、移行する前と後で相談件数がどのように変わったかということをお尋ねしたいと思います。","respondent":"諸岡児童課長","answer":"いわゆる先駆型といわれるものの変更ですが、大きくは虐待防止に関しまして、虐待防止の機能を持ったセンターであるということの意味です。平成１７年度の延べ件数が２,８００件ですので、相談件数については伸びているということが言えるかと思います。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"１年間期間を広げたということは、実家でお産をして帰ってきて１カ月たってしまったらそれを利用できないというような要望もたくさんありましたから。この辺のところを予防としてどういうふうに考えていらっしゃるのかということをお伺いしたいと思うんです。","respondent":"諸岡児童課長","answer":"育児支援ヘルパーというふうに改めまして、産後１カ月であったのを１年、産前も含めて行うです。一緒に育児を行う、助言を行うというようなことで、育児不安とか出産に対する不安を軽減していきたいと考えているところです。","id":"exchange-037"},{"speaker":"井上委員","kind":"質問","question":"その産前のヘルパーということでは、実績としてはどのぐらいあるんか尋ねました。","respondent":"諸岡児童課長","answer":"産後支援ヘルパーの派遣実数ですが、平成１７年度で６５人。これは平成１７年度の産後支援ヘルパーでございまして、産前につきましては平成１８年度からです。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問・要望","question":"妊婦への訪問事業などもありますので、ぜひ、そちらのほうと連携をとっていただいてお願いしたいと要望します。次は、心身障害者福祉会館運営費なんですけれども、このことについてどういう変更があったのか内容を教えてほしいと求めました。","respondent":"西島障害者福祉課長","answer":"改修工事を行いましたので、改修工事費が７,１００万、それから改修工事に伴います初度調弁が２,０００万ほどございました。実は、そこにかかわる人件費ならびに事業費がそれに加わってこの差になったものだというふうにご理解いただければと思います。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"この会館は４月から指定管理者制度を導入されておりますので、そのことについて、運営委託費の中で６,０００万ぐらいの増があって、それは人件費ということなんですが、指定管理者になっての経費の変化というものはあったんか尋ねました。","respondent":"西島障害者福祉課長","answer":"直営でやっていたときに比べて、人件費等ありますので、そういう意味では約８,０００万から９,０００万の金額は効率化できていると思ってあります。指定管理者になって以降も、受けた側も努力の部分は努力として評価をしながら…","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"製品ですから品川荘にも置いてあるし、そういう部分で低下するのではないかという利用者の不安なんかがあるんです。コストもさることながら、その辺の低下が絶対にないのかということを利用者はすごく心配をしているわけですが、いかがか尋ねました。","respondent":"西島障害者福祉課長","answer":"利用者に対する説明の際も、ちょっと枠組みは変わりましたけれども、やっている事業については基本的に同様であります。それから工賃等についても基本的にお支払をしているです。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっと時間がありますので、１１５ページの放課後サポートについてお伺いしたいと思います。平成１９年度からは、何ら方向転換はあってはいけないと思うんですが、その辺のこれからの先行きの見通しなどはどうなるんか尋ねました。","respondent":"西島障害者福祉課長","answer":"この点につきましては、今年度は既に実施をしている事業ですので、このまま実施をしてまいりますけれども、来年度以降どうするのか。キャパシティーの問題も含めて、十分検討させていただきたいと考えているところです。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"全児童対策として、コストの面では１時間１,６００円というところでは、何らかの対応をしていただきたいというふうに要望しました。送迎をすれば１日５００円がかかるというところで、利用者の声を聞きながら、推進していただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"午前中の最後にも児童虐待の件でお伺いさせていただきました。の各活動の実績についてご報告をいただきたいということと、これが実際防止に役立ったという実例がどのぐらいあるのかを含めてお伺いします。","respondent":"諸岡児童課長","answer":"地域分科会につきましては、この１１月から各地域において実施をするべく準備を進めているところです。この中でさまざまな虐待ケースについて検討されまして、早期発見、早期対応に向けた効果を上げてきているです。","id":"exchange-044"},{"speaker":"原（雅）委員","kind":"質問","question":"そしてケース会議のほうは５回行ってきたということで、防止に役立っている面はあるかという質問もしましたので、その辺のところのご事情を説明を求めました。","respondent":"諸岡児童課長","answer":"全体会の場で趣旨等につきまして説明し、弁護士による講演会も行いまして、このあんしんネットについてのご理解をいただいたです。ケース会議のほうで対応を進めているわけですが、早期対応ということで対応を図りまして、地域で見守りを行ったりといった対応を図っているです。","id":"exchange-045"},{"speaker":"原（雅）委員","kind":"質問","question":"関係機関も非常に多い中で、ケース会議それだけでも、人数的にも何人かがかかわっている。その守秘義務については規定なり、要綱なりが統一されているのかどうかというのも含めて、実際の中でどういう形をとられているのかについて伺います。","respondent":"諸岡児童課長","answer":"必ずしも関係機関の連携、それぞれの機関が必要な範囲において情報交換、情報提供を行う。そういった、あんしんネットの多くの利点がありますので、これを活用して、私どもとしましては虐待防止対策を進めていきたいと考えているところです。","id":"exchange-046"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"全体会で１９という数字が出てきていますから、個人情報も含めて連携をして、しっかり守っていっていただきたいというのが一つ要望です。児童虐待については警察の立ち入りを促進していこうという話が出ていると思うんですが、これはどういうふうに受けとめていらっしゃいますか。","respondent":"諸岡児童課長","answer":"緊急対応の場合、警察に言おうか、あるいは児童相談所にただちに通報するべきかという躊躇ということがあるかと思います。警察もこれに伴って迅速な対応を図るということで、危険の場合はただちに立ち入るというふうなことで全国的に徹底をしたということを聞いております。","id":"exchange-047"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"乳幼児の虐待についても、ゆさぶられっ子症候群というんですか、そういったことについての心配もあるわけです。そして具体的な活動がしっかりできるような体制を、よりつくり上げていっていただきたいと思うんですが、その辺のご決意を聞かせてください。","respondent":"諸岡児童課長","answer":"私ども、相談がいろいろございまして、緊急対応を図る場合には、まずは児童相談所のほうへ通告をします。児童相談所は法的権限を持っておりますので、立ち入り調査、それから一時保護という権限を持っておりますので、児童相談所ではそういう対応をする。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"私は、１２０ページの児童センターについて伺わせていただきます。こういう特色づくりも進められているようですので、そこら辺のアピールも含めて、今後の流れを教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"児童課におきまして、平成１５年に内部検討ということで、一定の児童センターの改革についてまとめたところです。コミュニティーブロックに対応した児童センターの活動といったことが必要であるということで、そういう意味でのシフトをしてきているところです。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"館長と地域の町会長また、実際に使っているお母様方からもあの館はどうだとか、この館はいいとか悪いとかといういろいろな評判を聞きました。こういう観点で、もう１回児童センターの今後の改革について、ご所見を伺います。","respondent":"諸岡児童課長","answer":"児童センターの改革につきましては、委員がおっしゃられたことは大変重要な視点だと考えています。地域のゼロ歳から１８歳までの児童の健全育成の拠点として、地域と連携を図りながら、さまざまな活動を行っていきたいと思っているところです。","id":"exchange-050","title":"町会・自治会支援"},{"speaker":"若林委員","kind":"意見","question":"児童センターというのは、今、子どもが親から離れて友達と来る屋根つきの遊び場というふうにしか見ていない地域もあるわけです。もう一遍、特に地域と児童センターとの距離感をどのように縮めていくか、これについてもう一言お願いしますとの意見を述べました。","respondent":"諸岡児童課長","answer":"児童センターに来ていただくことで、児童センターを認識していただき、児童センターのいいところを見ていただくということが大事だと思っています。この両方をあわせて…","id":"exchange-051"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほどの課長のご答弁ではゼロ歳から１８歳というお言葉もありましたが、あいた施設で、児童センター内で応援をしてほしいと求めました。今回は児童センターということでご要望しますが、そういう方たちへの目的外使用として、こういう目的外使用に対してご所見を伺いたいと思います。","respondent":"諸岡児童課長","answer":"その他社会教育団体、児童育成団体等の方々にご利用いただいておりまして、平成１７年度も合計で２,５０９回という利用回数になっておりました。そういったところを中心に、今おっしゃったような青少年の健全育成といった事業を積極的に進めていきたいと考えています。","id":"exchange-052"},{"speaker":"南委員","kind":"質問","question":"私は１１８ページの子どもすこやか医療費助成についてお伺いしたいと思います。そこから伺いたいと思います。","respondent":"諸岡児童課長","answer":"平成１７年の１月から小学校６年生まで所得制限をなしということで実施をしてきております。具体的には経済的支援になろうかと思いますけれども、強力な子育て支援施策の一環として品川区が先進的に行っている事業です。","id":"exchange-053"},{"speaker":"南委員","kind":"提案","question":"今年の第１回定例会で中学生まで拡大を求めて条例提案をいたしましたけれど、時期尚早だとして、この条例提案については否決をされてしまいました。これは東京都内のようでありますけれども、この制度に対する拡大を求める声というのは住民だけでなく、その点についての見解はいかがか尋ねました。","respondent":"諸岡児童課長","answer":"子どもすこやか医療費助成事業につきましては、この間、制度運営が順調に推移してきているです。やはり子育て支援策、経済的支援、それ以外のものも含めて全体として総合的に考えていく施策だろうと理解をしております。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"多方面から出ていることについての認識も伺ったのですが、答弁がないので、改めてしてほしいと求めました。私どもは改めてこの委員会の中で、中学生までの義務教育期間、子育て支援をしていくという角度からの要望をさせていただきたいと思っています。","respondent":"諸岡児童課長","answer":"それぞれ区に応じて中学校まで入院だけを延長しているところとか、そういったところがあるということは承知をしております。それから、先ほどのすこやか医療費助成制度についての考え方のお話ですが、そういう努力をしてきているところです。","id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"しかも、所得制限についてもほとんど求めていない状況があるわけですね。やはり私はこれだけ切実な住民の要望があって、そこの状況というのはどんな事情があるのか、改めてちょっと伺わせていただきたいと思っています。","respondent":"古川児童保健事業部長","answer":"これからもそのように考えてありますけれども、品川区が実施する区民のための施策というのはさまざまな観点から実施していくべきものであると。今直ちに中学３年生までどうかというご質問には直ちにはお答えできないというのが現実です。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"その点からして、やっぱり検討していく方向を示すべきではないかと思うんですけれども、その点についてどういうふうにお考えかどうか伺います。お財布を確認しないと医者に連れていけないということであってはならないと思うので、大きさ、この点について伺います。","respondent":"古川児童保健事業部長","answer":"品川区が行うさまざまな子育ての支援策、その一環について、先ほど申し上げた「直ちに」ということは慎重な検討が必要であるです。この問題だけを取り上げてというわけにはまいりませんので、全体の中で慎重に検討していくべき課題、このようにお答えしたわけです。","id":"exchange-057","title":"町会・自治会支援"},{"speaker":"南委員","kind":"質問・要望","question":"私が１つ申し上げたいのは、この私のほうに要望を持ってこられた方は、設備のところにむしろつけてもらいたいんだということなんですね。ですから、整備されているのかちょっとそこを伺って、それを積極的に進めていただきたいということを申し上げたいと思うんですが。","respondent":"西島障害者福祉課長","answer":"災害時の避難につきましては、災害用援護者名簿を各町会に登録をして準備をしています。各施設につきましては、大きな施設についてはそういったものもありますけれども、細かいところまで調査をさせていただきたいと考えています。","id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"障害者のための施設に限らず、調査をするのであれば、できたら公共施設全般に広げて、やっぱり整備しなければいけないところは整備するという方向でぜひ取り組んでいただきたいという要望を強く求めて終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"大沢委員","kind":"質問","question":"次に１１１ページのホームレス地域生活移行支援事業と障害者福祉サービスの評価向上、最後に１２２ページの生活保護について伺いたいと思います。１２１ページが１項目、この中で都支出そして国支出の返還金が１２回出てくるんですけれども、これはどういうことを意味しているのか説明を求めました。","respondent":"日下部企画財政課長","answer":"大きくは２種類ありますけれども、毎年度、年度当初の段階で利用見込みを立てまして申請をする。ただ、年度当初の見込みの段階と最終の年度末の実績ということでは、どうしてもその差額が出てまいります。","id":"exchange-060"},{"speaker":"大沢委員","kind":"意見","question":"成果報告書で、今、平成１７年度をやっているわけですけれども、以前においてこれだけたくさんの返還金が出ていなかったと私は記憶をしておりますけれども、それはそれで今年の場合は何かいろいろな面で事情があったと思うんですけど、聞かせてくださいとの意見を述べました。","respondent":"日下部企画財政課長","answer":"これは私どもも年度の当初の見込みを立てる段階で、あるいは制度改正があればそれを踏まえて、先々１年間の見通しをしっかり立てる。ただ、例えばその対象者が個人にわたるような場合とか、どうしても一定の当初見込みとの違いが出てくるのはやむを得ないという面があります。","id":"exchange-061"},{"speaker":"大沢委員","kind":"質問","question":"その都の事業と同じように区が同じ形で出ていますけれども、先ほど品川区はホームレスが増えたということを伺いました。若干、個人情報とかいろいろな面で難しいところはありますけれども、そういう傾向には変わりないということで理解してよろしいわけか尋ねました。","respondent":"志村生活福祉課長","answer":"先ほど午前中にもお答えしたとおり、私どもも平成１６年度に個別の調査を実施させていただきました。それと、先ほどご説明いたしました。","id":"exchange-062"},{"speaker":"大沢委員","kind":"意見","question":"ちなみに、私がちょっと聞きたかったのは、アルミ缶を集めて生業としている。あれが間接的には就労支援になっていると私は思うんですけれども、どのようにお考えになっていますかとの意見を述べました。","respondent":"志村生活福祉課長","answer":"ですから、区内で集めますと、そこまで持っていくということで、生計を立てたといいますか、収入を得ているというふうには聞いております。私どもが行っている就労支援からしますと、やはりハローワーク等を通じて、アルミ缶の収集についてはそのようにとらえてございません。","id":"exchange-063"},{"speaker":"大沢委員","kind":"質問・要望","question":"ですから、何かまた機会がありますれば光を与えていただくような何かお考えを持ってほしいと求めました。ちなみに、やはり精神障害の方もいらっしゃるでしょうし、それに対してどのように体制を整えていらっしゃるのか聞かせてください。","respondent":"志村生活福祉課長","answer":"いわゆる生活保護、適宜、そこの所管する窓口に的確に誘導していくことが私どもの本来的な業務だろうと認識しています。ですので、そういう意味では一体として私どものほうでは今後も取り組んでいきたいと、かように考えてあります。","id":"exchange-064"},{"speaker":"大沢委員","kind":"意見","question":"私は第１回の定例会でも出させていただいたんですが、これは内部障害をお持ちで、外に見えにくい。オストメイトに対する対策の区のお考えを、この内部障害の方をどのようにとらえていらっしゃるのか聞かせてくださいとの意見を述べました。","respondent":"西島障害者福祉課長","answer":"具体的なサービスといたしましては、いわゆるストマ用器具の支給を申請に基づいて行っているというようなことがあります。年内の予算額でいいますと、約３,０００万円程度をストマ用器具として支給しているという実績があります。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"ちなみに、都ではオストメイトの方を集めてというか、オストメイトの方たちの講習会というか集まりをされている部分があるんですが、品川区ではそういうのはやっているのか尋ねました。","respondent":"西島障害者福祉課長","answer":"東京都、あるいはオストメイトの方たちが自主的に団体を構成して、それぞれ研究会なりそういう講習会をやっているというのは聞いてありますが、品川区では特にオストメイトの方だけを対象にしたそういった催し物は実施してございません。","id":"exchange-066"},{"speaker":"大沢委員","kind":"意見","question":"ちょっと款が違ってまいりますけれど、私が一番心配しているのは、やはり災害のとき彼らがどういうふうに対処をするのかということ。やはりこれは非常に難しい問題だと思いますので、ちょっとそこのところを重く考えてほしいと求めました。","respondent":"西島障害者福祉課長","answer":"先ほど言いましたストマ用器具は、実は１０月から地域生活支援事業の枠組みに入ってまいりました。区が単独で実施できるということで、納めていただく業者と防災協定を結ぶことを現在検討して、そういったことを考えているところです。","id":"exchange-067"},{"speaker":"大西委員","kind":"質問・要望","question":"それから成果報告書の１１４ページの年賀状等送付、それとひとり暮らし高齢者福祉の中の食事の配食についてちょっとお尋ねしたいと思います。子どもの命にかかわることであろうと思いますので、そういう形で区が直接的にそういう現地調査をするという考え方があるのかどうかを説明を求めました。","respondent":"原国保年金課長、蓼沼高齢福祉課長、小林保育課長、諸岡児童課長","answer":"数字としてはそういった数字ですけれど、国民健康保険料の支払いができない方につきましては、ご相談の中で分納をしながらお支払いをいただく。… 年賀状に関するお尋ねですけれども、通常の年賀状の様式に「何かお困りのことがありましたらご相談ください」という一文を付して送付しています。… オアシスルームは利用予定日の１カ月前から３日前まで、それぞれ希望する保育園のほうに申し込んでいただく形になっております。… 虐待についてのお話ですが…","id":"exchange-068"},{"speaker":"大西委員","kind":"質問・要望","question":"大変生活に困っている人たちに関しては適宜要望するだけのものを高齢福祉事業として提供しているのかどうかというのを教えてほしいと求めました。もう明らかに身体的な虐待等はわかるわけですから、その点での答弁をもう一度ほしいと求めました。","respondent":"原国保年金課長、蓼沼高齢福祉課長、小林保育課長、諸岡児童課長","answer":"もう少し１年、２年滞納していて、高額の滞納者につきましては資格証というのをお出ししています。例えば７０歳以上の高齢者についてはそういった資… ケアプランに基づいて適切に提供するということで、おおむね週に２回程度、低栄養の予防ということで提供をしているものです。調査活動… このオアシスルームの性格上、予定が立つカルチャーですとか買い物、あるいは学校行事等の関係があってそのようにしております。… 虐待防止に関するご質問ですが、先ほど原則的な流れについてご説明をさせていただきまし…","id":"exchange-069"},{"speaker":"築舘委員","kind":"質問","question":"１１３ページの認知症高齢者ケア事業、それから介護予防モデル事業、特にいきいき脳の健康教室ということで質問します。その辺の動機というか、実行性というか、その点を説明を求めました。","respondent":"濱野区長","answer":"初日にもお答え申し上げましたけども、高齢者福祉については、高齢者の方々の数がこれからも増えていくと、これが大前提です。そういう意味で、まず第一が高齢者福祉だ、こういう趣旨で申し上げたところです。","id":"exchange-070"},{"speaker":"築舘委員","kind":"質問・要望","question":"症というのはそういうことですか。その辺は国が決めていますが、区としての見解はどうかというのを教えていただきたい。","respondent":"蓼沼高齢福祉課長","answer":"名称が変わった経緯につきましては、たしか今委員がおっしゃったような問題も議論として経過にあった記憶があります。いろいろ総合的に勘案して、そういういろんなもろもろの論議の中で認知症というふうに決まったというふうに記憶しております。","id":"exchange-071"},{"speaker":"築舘委員","kind":"意見","question":"第３期の品川区の介護保険の事業計画、いきいき計画２１では、やはり認知症の高齢者ケアの体制というのをしっかり築いているわけですね。この点に関して、それとも要するに在宅でかなり負ってもらうところは負ってもらうということを重視していくのか…","respondent":"蓼沼高齢福祉課長","answer":"そういう意味で、施設整備、それから在宅、どちらも対応していくということになろうかと思います。認知症高齢者を十分意識したサービスですので、双方兼ね合わせながら今後認知症高齢者への対応を進めていくというふうに考えてあります。","id":"exchange-072"},{"speaker":"築舘委員","kind":"質問・要望","question":"品川の福祉カレッジで、そのときに在宅施設介護にかかわるすべての現場スタッフを対象としているということなんですね。第３段階というのを人によって使い分けるというか、実際うまくいっているのかどうかという具体的なところをちょっとお聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"福祉カレッジにおきます認知症ケアの専門コースの実施状況につきましては、今ご指摘のとおりです。その施設での認知症ケアの実践を講師の方が同行しながら検証するというような仕組みでフォローしながら実際の施設における認知症ケアに実践的に役立…","id":"exchange-073"},{"speaker":"築舘委員","kind":"質問","question":"そういうことで、現場対応には欠かせないという、やっぱりノウハウをしっかりと教えておいてあげるということは大切なことだというふうに思います。それを家族もわかっていないと、その辺の対応の仕方、家族に対する支援というのが適切に行われているかどうかをちょっと聞かせてください。","respondent":"蓼沼高齢福祉課長","answer":"例えば各法人で家族懇談会等を実施したりとか、家族に対する研修、日帰り研修あるいは宿泊研修というものを実施しております。これにつきましては、あるいは家族同士の情報交換等を図れるような形で家族の方を支援しているという状況です。","id":"exchange-074"},{"speaker":"築舘委員","kind":"質問","question":"本当に施設入所者では８割ですか、認知症だということもありますし、そういうことでの今後高齢者も増えてくるということもあります。７０歳以上じゃなくて、もう少し下げたほうがいいと思うんですけど、その点説明を求めました。","respondent":"冨岡高齢事業課長","answer":"平成１７年度は７０歳ですが、今年の平成１８年度からは６５歳ということでやらせていただいております。会場も増やして積極的に事業をいたしている状況です。","id":"exchange-075"},{"speaker":"中島委員","kind":"提案","question":"皆さんがお持ちになっていただけたらなと常々思っているんですが、そのことを１点、区の見解をお伺いしたいと思います。今月から介護度が要支援と要介護１の方のベッドの貸与対象者、品川区としてはどのように取り扱われるのか、この３点を先にお伺いしたいと思いますとの意見を述べました。","respondent":"蓼沼高齢福祉課長","answer":"事業者を紹介して対応してきたところで、その４月実施のところが経過措置ということで、９月まで措置されていた期間が終了したです。社会福祉協議会で実施運営をしておりますほっと・サロン、昨年の１０月に開設をいたしましたけれども、これの工事費用等です。","id":"exchange-076"},{"speaker":"中島委員","kind":"質問","question":"この点の費用とか、そういったものはどのようになるのか、これを１点お伺いしておきたいと思います。このベッドがあったらいいなという声もあるわけなので、これは市区町村が助成事業をやらなければ、東京都は補助しないということなんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"夜間対応型訪問介護の利用料ですけれども、基本料が一月１,０７２円です。そういう場合については、また個別にベッドの寝具ですとかの工夫で対応できるところは対応していただければというふうに思います。","id":"exchange-077"},{"speaker":"中島委員","kind":"提案","question":"これは平成１１年に私も枚方市まで行って視察をして提案をさせていただいたものなんですが、３園で約８７８万円と出ております。１１８ページなんですが、１園４７０人で６６０万円とあるんですが、これはどういうふうな違いがあるのかお知らせくださいとの意見を述べました。","respondent":"小林保育課長","answer":"こちらの１園というのはどんぐりで、４７０人というのは、延べの人数です。このどんぐりの実施分につきまして、区が保育助成をしているものです。","id":"exchange-078"},{"speaker":"中島委員","kind":"質問","question":"そうしますと、区立保育園のほうの３園の８７８万円というのは、これは何名なんでしょうか、人数を説明を求めました。","respondent":"小林保育課長","answer":"病後児保育の区立分ですけれども、こちらが西大井と、それから清水台、西五反田、この３カ所です。それぞれ西大井が３７７人、清水台が１８５人、西大井が７８人、年間実績で６４０名になってあります。","id":"exchange-079"},{"speaker":"中島委員","kind":"質問","question":"これが妥当なのかどうかちょっと今数字に弱いものですから、やっぱり３園で何名とか、載せなかった理由が何かあったのかなと思ってしまいました。私も平成１２年の第２回定例会で発言をしておりますが、この幼児教育というのは、保育園の園児に対する幼児教育か尋ねました。","respondent":"高橋幼保一元担当課長","answer":"こちらにつきましては、平成１５年度から１６年、３カ年におきまして、保育園におきましての幼児教育ということで、３７園に実施したものです。","id":"exchange-080"},{"speaker":"中島委員","kind":"意見","question":"先ほど教材の話が出ておりましたけれども、保育園の場合というのは、人数割では年齢の幅が０歳からありますので何とも言えないと思うんですが、単純に割るものではないと思いますけども、やはり教材をもっと充実してほしいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"須貝委員","kind":"質問","question":"成果報告書１２１ページの児童センター事業費についてお伺いいたします。品川区では、主に児童センターで児童の虐待の相談を受けておりますが、この品川区役所の職員の中に、児童福祉士は何人ほどいるんか尋ねました。","respondent":"諸岡児童課長","answer":"区の職員の中に、児童課の職員の中に児童福祉士はいるかですが、非常勤で１名おります。それから、東京都のほうの体制ですが、児童相談所のほうに児童福祉士ということで１６名配置されているです。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問・要望","question":"子どもが突然助けを求めてきたり、そういう数はわかるでしょうか、件数。","respondent":"諸岡児童課長","answer":"これは児童相談所のほうで平成１７年受けた虐待実件数ですが、品川区内を対象として品川児童相談所が受けた数は９２件です。","id":"exchange-083"},{"speaker":"須貝委員","kind":"質問・要望","question":"今ちょっとその中に踏み込んでお聞きしたんですけど、突撃とか、急に子どもが助けを求めてきたとか、職権保護したという数はわかりませんか、今は。","respondent":"諸岡児童課長","answer":"児童相談所のほうで取り扱ったケースですが、虐待で施設入所ということで、一時保護したという形ですが、３７人です。品川児童相談所が品川区、目黒区、大田区を管轄しておりますので、３７人のうち品川区は１１人です。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問","question":"その場合に、保護施設というのは、品川区にも東京都の保護施設があるかと思うんですけど、これはちょっと参考までに足りているんでしょうか。実際、そこに一時預かるとか、そういう場合に、保護する場所はあるんか尋ねました。","respondent":"諸岡児童課長","answer":"児童保護につきましては、東京都のほうでも役割分担という形でやっておりますが、かなり施設はいっぱいだというふうに聞いております。","id":"exchange-085"},{"speaker":"須貝委員","kind":"質問・要望","question":"今親の置かれている状況がわかるとか、精神状態がわかる、そういうことがやはり一番求められていることだというふうに聞いております。今品川区の中で非常勤で児童福祉士が１人、誤って虐待をしちゃうわけですから、その辺についてご見解を説明を求めました。","respondent":"諸岡児童課長","answer":"虐待の対応につきまして、私どもとしましては、この中で連携を密にしながら迅速な対応を図っていくということで取り組んでいるところです。地域におきましては、やはり早期発見、早期対応、迅速な対処が必要です。","id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"職員がすぐとりあえずそのお宅に行ってベルを押せるような対応ができるんでしょうかということをちょっと今もう一度もし回答いただければお願いした…そういうこともちょっと取り組んでいただければと思うんですけど、すみません、その２点について再度お願いします。","respondent":"諸岡児童課長","answer":"迅速な対応ですが、通報があった場合、すぐ児童センターの職員が駆けつけられるというような体制はできているつもりです。大人向け、要するに通報先、そういったことも含めて周知を図っているです。","id":"exchange-087"},{"speaker":"石田委員","kind":"提案","question":"ある程度もちろんシルバー人材センター本体の提案、どのように進んでいこうとしていると把握をしているのか教えていただきたいなと考えています。そういうことではないんだという話が余りにも少ないので、そこら辺のところの見解をもう一度お伺いしますとの意見を述べました。","respondent":"西島障害者福祉課長、志村生活福祉課長、諸岡児童課長、冨岡高齢事業課長","answer":"それから愛の手帳１、２度の方ということで、駐車禁止除外になっているです。なお、これは身体障害者本人または同居の親族が現に保有している車両と… 私から大田寮の中での事故等についての対応はというお尋ねです。ホームレスの自立支援システム、それから自立支援システムということで… こういうものを子育て支援として理解をしていただこうと取り組んでおりまして、親子のデイキャンプ等、楽しい取り組みがたくさんあります。毎年… シルバー人材センターの今後の本体をどのように把握しているかです。…","id":"exchange-088"},{"speaker":"石田委員","kind":"質問","question":"そういう施策をある程度要介護者とか障害者の部分にはやっていくべきだろうなと思っているんですが、そこら辺、もう一度答弁をお願いします。こういうことだって、楽しい面がこれだけあってやっているんだということをぜひ打ち出してほしいなと思いますが、ご意見をお願いします。","respondent":"志村生活福祉課長、松嶋交通安全担当課長、堀越行財政改革担当課長","answer":"お尋ねの大田寮の中での事故ですけども、基本的には保険の中で対応していくということであります。といいますのは… 事情を説明すれば、すべてがだめということではありませんので、そこら辺は駐車許可可能かと考えております。 地域をつなぎ、子育ての楽しさをしっかりとＰＲしていくようなという形に位置づけておりますので、これからしっかりとやっていきたいと思います。","id":"exchange-089"},{"speaker":"石田委員","kind":"質問・要望","question":"ぜひ障害者とか介護者のは窓口があるわけですから、そういう形の困っていらっしゃる方というのは、たぶん品川区でも把握ができると思うんですね。ご相談に行ってくださいじゃなくて、やっぱり仲介ぐらいはぜひとっていただきたいなと考えていますので、それはぜひ要望だけして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国民健康保険会計と介護保険についてお伺いをしたいと思います。そして、先ほど滞納世帯の数についてはご答弁がありましたので、直近の短期証と資格証の世帯数をお聞かせほしいと求めました。","respondent":"原国保年金課長","answer":"そういった中で、先ほどの率になってありますけれど、短期証です。今年の平成１７年度末が２０７世帯、今年の９月末で１７３世帯、こういった数字になってあります。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして、その中でも、住民税非課税から課税となって値上げとなった方の人数も教えてほしいと求めました。そのために、増収となった額もわかったら説明を求めました。","respondent":"原国保年金課長","answer":"それから、６５歳以上の方ということでとらえるのが妥当かと思いますけれど、４万９,０００人ぐらいの方が６５歳以上の被保険者になるところです。今回の税制改正で老年者控除の廃止、この人数ですけれど、両方で対象になっている方が９,０００人ということで把握しています。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"緩和措置が必要だということを国に対して要望書を出しているということをお聞きしましたけれど、その結果、対策がとられることになったかどうか。国民健康保険料に連動すると思われる人数についても教えていただきたいんですが、１３％から１０％に下がる人数を教えていただけないか尋ねました。","respondent":"原国保年金課長","answer":"住民税のフラット化に伴う対応です。課長会におきましても影響が当然あるということで今考えておりますので、課長会として、何らかの対応ということで現在検討している最中です。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"住民税の１８２％ということになるかどうかというのは検討されてくるとは思うんですけれども、それにしても、下がる方もいるわけですからね。緩和措置というのは、いずれは上がるということですから、これに対してはしっかりと対応を求めていただくように強力にお願いをしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"決算書で申し上げますと、２５７ページにこの基金の運用状況報告書が記載をされてあります。金額につきましては、約１８億５,０００万円です。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"かなり９６万円というのが品川区の制度の対象の年収の額ですけれども、また、ぜひ減額制度の改定を要望させてほしいと求めました。３月時点で介護ベッドを使われていた方が８５８人、車いすが５９６人、その方が９月末でどうなったのかについて教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"この間、１月以降、この制度の説明をして、複数の代替案を示しながら対応を適切に図ってきたところです。そして、自費でレンタルに切り替えた方が２５.５％、そして保険給付の対象と引き続きなっている方が約１.２％というような傾向です。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この数、対象から関係ない方は３.５％しかいないということで、そこのところについて改めてお伺いしたいと思います。一般質問の答弁では、ベッドは軽い方でも必要だというふうなことだと思うんですけど、その点についてはいかがか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"その中でも、引き続き対象になる方は自力で起き上がりができない、寝返りが打てないという方ですが、これについて約１.２％の方が該当しているです。そのほか、この制度改正の趣旨に、説明してご理解いただいて、特段の自費で購入、レンタルをされなかった方が３.５％いるです。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区が必要かどうかと、そのことについてしっかりと答弁していただきたかったんですけれども、私は今回現場の声をずっと聞いてきたんですね。区としてもこれを受けてしっかりと区独自の施策を現場では求めていますから、ぜひとっていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"堺委員","kind":"質問・要望","question":"小規模多機能型居宅介護という件について３点確認の意味で教えていただきたいと思うんですが、確認の意味で何点かお伺いをしておきたいと思います。そういう中で、これに関連をして最初にこの辺の事業の内容および最近の利用状況はどうなっているのか、その辺からお尋ねをしてまいりたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"高齢者人口の５％程度の見込みが厚生労働省の見込みですが、この方たちを主な対象として介護予防事業をこの４月から順次進めているところです。高齢事業課のほうで実施するものが主ですけれども、こちらのほうが１４カ所で実施されていまして、３４５名の参加という状況です。","id":"exchange-098"},{"speaker":"堺委員","kind":"提案","question":"平成１８年度の事務事業概要の中には、例えば身近でリハビリですか、これなんかですと、実施場所が３カ所出て、それなりの件数が出ておりますね。ぜひこの事業についても各地域に順次拡大をしていただきたいということをこの際提案させていただいたわけですが、それとまた違うんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"先ほどの介護予防モデル事業の中でいきいき筋力向上トレーニング事業というのがあります。これは平成１７年度にはモデル実施を品川保健センターで実施した部分ですが、そちらのほうでも実施をいたしまして、拡大を図っているところです。","id":"exchange-099"},{"speaker":"堺委員","kind":"提案","question":"同じく平成９年の１０月に行われました決算特別委員会の席でも、このグループホームの早期確保、設置という点について提案をさせていただきました。この辺につきましても、またそういう方向でつくっていっていただきたいと思っているわけですが、その辺についてのご見解はいかがか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"都南病院跡地に整備が予定されておりますけれども、それから八潮のほうにも民間の事業者によるグループホーム等の整備が予定されております。今後とも地域バランスを考慮しながら、認知症高齢者の施設整備について対応を図っていきたいというふうに考えてあります。","id":"exchange-100"},{"speaker":"堺委員","kind":"質問・要望","question":"そう思いますので、今ここでその辺のところを確認させていただいたわけですので、ぜひひとつこの件についても取り組んでいただければと考えています。この辺についてのご見解を最後にお聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"お尋ねの小規模多機能居宅介護につきましては、亀田邸、都南病院跡地で実施してまいる予定です。はこの２カ所の実施状況を十分検証しながら今後の方向については検討していきたいと考えています。","id":"exchange-101"},{"speaker":"伊藤委員","kind":"質問","question":"私は１２１ページの生活保護費、それから、生活保護受給者就労促進事業に関連して質問いたします。お願いします。","respondent":"志村生活福祉課長","answer":"それから、その申請を受理しますと、１２日間の間で保護の決定を行います。その後、私どものほうではこの方についての処遇方針ということを決めまして、これからどういう方向に処遇を持っていこうということを定めるものです。","id":"exchange-102"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そのことを後で教えていただきたいのと、民生委員の方の率直な感想として、保護は受けませんと頑張っている方も中にはいらっしゃる。このことの判断基準といいましょうか、それをどういうふうに品川区としては見つめていきながら、そのことについての答弁を改めてお願いいたします。","respondent":"志村生活福祉課長","answer":"ですので、これにつきましては、それぞれの世帯の構成によって保護費が変わってまいります。私ども福祉の場合、私どもから一方的にちょっと見た目、生活に困っているんじゃないでしょうかということで保護をかけるというものでもありません。","id":"exchange-103"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認したいのが、そういう働けると思われる生活保護対象者の方々に対して、まずどういう報告を対象者から求めているのか。それから、どういう頻度でそういう報告を求めているのかということが一つ。","respondent":"志村生活福祉課長","answer":"先ほど私が説明しましたこういう方が例えば保護の申請に参ります。そちらのほうと連携して、就労に向けた取り組みをしていくと、こういうことになってあります。","id":"exchange-104"},{"speaker":"伊藤委員","kind":"質問・要望","question":"後で教えていただきたいのと、それから、生活保護というのはそれまでの間のつなぎとしてぜひ使っていただきたいという思いでずっといるわけです。例えばどういうふうに報告を求めて、できれば就労自立につなげていくかということについてのもう少し具体的な答弁をお願いいたします。","respondent":"志村生活福祉課長","answer":"いわゆる世帯主の傷病、あるいは家族等が急病になったということで保護を開始しましたのが４５％ほどです。この自立の助長に向けて取り組んでいこうということでありますので、取り組んでいきたいと、かように考えてあります。","id":"exchange-105"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今年度５０世帯、それから７８人の方々の生活保護が廃止になったということは、これは非常にすばらしいことだと思います。お伺いしたいのが、これは今後ぜひ拡大していっていただきたいと考えていますので、今後の拡大の方向性についてを説明を求めました。","respondent":"志村生活福祉課長","answer":"ですので、先ほど申し上げたとおり人件費は国から１００％まいります。こうした事業展開はこれからも続けてまいりたいと、今はこのように考えてあります。","id":"exchange-106"},{"speaker":"伊藤委員","kind":"質問・要望","question":"時間がありませんので、要望だけしておきますけど、生活保護自体を否定するわけではありません。ただ、あくまでもそれを私たちは一つの通過期間として考えておりますので、ぜひ自立支援の方向を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"それから、１２０ページの保育園ＰＴＡ活動支援、それと１１９ページの延長夜間保育とそれにあわせてオアシスルームを質問いたします。どういった方が主に、それから体調などはどういう状態の方が多く来られているのか、まずそこをお聞きします。","respondent":"冨岡高齢事業課長","answer":"概ね６５歳以上の区民の方、あるいは事前の事業説明会と体力チェックに参加が可能な方、あわせて自力で会場への往復が可能な方を対象としているものです。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"今、平成１７年度の実績として荏原地区なんでしょうか、幾つかできているということで、今後広がっていくんだという話がありました。それに対しての助成金が出るはずなんですが、区の持ち出しと、どのぐらいの助成金が出ているのかお聞きしたいと思います。","respondent":"冨岡高齢事業課長","answer":"マシンにつきましては、１カ所１５０万円ということで、東京都から出ているものです。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"１５０万円で今何台か入っていると思うんですが、それで全部賄えているという理解でよろしいんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"１カ所に４台ありますけど、ワンセットで１５０万円、こういうことです。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、継続性はどうなんだろうかということがあります。タオル１本でできるような、例えばレインボー体操とかいろんな種類があるんですが、その辺の導入は今後考えることはあるんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"それからもちろんストレッチとか、あるいは家庭で継続してできるような使わないプログラム、こういうものも入れて行っているところであります。ほかにもバランスボールとかチューブ、そういうものも含めて一体としまして筋力向上トレーニングということでやっております。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、そういう意味では、もっと違う方法を使って広めていただきたいというふうに要望で終わります。その中で、委託先の変更というのはどのように今後考えられているのか、その辺についてはいかがか尋ねました。","respondent":"小林保育課長","answer":"給食代行の委託につきましては、入札に応じて業者を変えておりますので、そういった意味では業者が変わる可能性は来年度以降あるかと思います。しかしなから、質も安定し始めていますので…","id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"それなりにノウハウを蓄積して実績をつくられていったということを踏まえると、また来年度、年度契約になっているんでしょうか。入札に入ると、その関係できちんと保育課の要望を考慮した業者の選定になっているのかについてはいかがか尋ねました。","respondent":"小林保育課長","answer":"契約担当のほうでは私ども主管課の意見も踏まえて公平性を担保することを前提としながら対応していただいているというふうに思っております。私ども主管課としましては、しかるべく公平かつ的確な業者の選定ということが実現できるように対応してまいりたいと考えています。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"その中での特徴を入れて、特色を入れていくとか、子どもたちのためにいろんな工夫をしていただきたいなというふうに要望したいと思います。それに対してどうやっていくかということが当然必要になってくると思いますが、そのお金に関することはどういうふうに今後検討していただけますか。","respondent":"小林保育課長","answer":"特に子育ての楽しさを感じ取ってもらうという意味からも親子のかかわりを深めていくという形でＰＴＡの役割もあるのかなというふうに認識しておりま…もちろん結果的に多くの方が参加されて、それが全員参加であれば…","id":"exchange-114","title":"町会・自治会支援"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、子どもさんがなかなかほかの方だとミルクも飲まないという状況なのに、１時間という約束なのに帰ってこない。そこは保育士なり、事業を展開する中で、その辺の改善点はいかがか尋ねました。","respondent":"小林保育課長","answer":"ある意味では総需要は安定して対応しているんですけれども、どうしても必要なところへ集約しつつあるのかなという一定の効果を感じております。事情等もありますので、随時保育士が働きかけの中で、子どもと長くご家庭で生活するようにお話をしてまいりたいと考えています。","id":"exchange-115"},{"speaker":"川西委員","kind":"質問","question":"１１３ページのシルバー成人式、１１４ページの高齢者住宅、この高齢者関係３点一括で質問します。そういう意味で、この平成１７年度の中で、民間事業者のスタッフの福祉カレッジへの参加状況を説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"福祉カレッジですが、例えば臨床ケア専門コースで申し上げますと、約２００人の受講者が参加をしているという状況です。そのうち、民間事業者につきましては、約３割ぐらいの参加です。","id":"exchange-116"},{"speaker":"川西委員","kind":"確認","question":"いわゆる派遣事業者のことなんですが、３割というと、例えば１年間のうちに全然研修会に参加させない事業者もいるんでしょうか。そういう方々がちゃんと福祉カレッジに参加の強い意思があるのかどうか、そこを確認したいんです。","respondent":"蓼沼高齢福祉課長","answer":"民間事業者の研修への参加率等ですけれども、先ほど３割と申し上げましたけれども、基本的にはそれぞれの事業所で独自の研修が行われております。ですから、そういう独自のものとこういう外部の福祉カレッジへの参加とあわせて質の向上をそれぞれ取り組んでいるです。","id":"exchange-117","title":"議員研修会の内容と所要時間"},{"speaker":"川西委員","kind":"質問・要望","question":"しかし、催し物というんですか、昨年まで品川区の島倉さんという方が来ていまして、今年からかわりました。その内容はとやかく言うといけないのですが、どういう内容の企画の方法なのか、説明を求めました。","respondent":"冨岡高齢事業課長","answer":"それで、歌謡ショーの内容が変わったですが、実は平成１７年から、去年ですが、去年から変わりました。前の島倉さんが１０年と長く出ておられたということで、今回変えてみようということがきっかけで、かえさせていただいたという状況です。","id":"exchange-118"},{"speaker":"川西委員","kind":"質問・要望","question":"２０歳になる成人式は実行委員会というんですか、皆さんでご希望を出し合いながら区の予算の中で決めていくというような方式をとっていますよね。ご意見を伺いたいと思います。","respondent":"冨岡高齢事業課長","answer":"いろいろ貴重なご意見をいただきましたので、さまざまな角度からまた検討しながら、そちらに向けて進めてまいりたいと考えております。よろしくお願い申し上げます。","id":"exchange-119"},{"speaker":"川西委員","kind":"質問","question":"歳入でいろいろ質問があって、ちょっと勘違いしているといけませんが、民間住宅家賃助成は平成１７年度で終わりでしたか。これからもやるんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"民間住宅の家賃助成ですが、これは平成３年７月に始まった事業ですけれども、平成１２年の４月に新規の受け付けを廃止いたしまして、本年度、つまり平成１９年３月末をもちまして助成を終了という形で進めしています。","id":"exchange-120"},{"speaker":"川西委員","kind":"質問","question":"それを去年たしか伺っていたような気がしましたので、質問がほかに行っちゃうといけないと思いました。高齢者の人が例えばひとり暮らし、比較的年金の低い人たちが入る住宅の対策というのは、これからはどういうふうにしていったらいいんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"住宅にお困りである方については高齢者住宅ということで、これは引き続き当然２２０戸ストックがありますので、進めてまいりたいと思います。転居等を迫られている場合の住宅のあっ旋という制度がございまして、これにつきましては、転居助成金という形で対応するということです。","id":"exchange-121"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、やはり、もう一度そういう住宅を考えていただく方策を来年度に向けてぜひ検討していただきたい。大きいものはそんなことをしていないのは知っていますが、やはり少しお金をかけて、家賃をとっていいんですから用意をしてほしいと求めました。","respondent":"諸岡児童課長、小林保育課長","answer":"先ほどお話し申し上げましたように、児童センターの改革の中で、児童センターのこれからの機能を充実させていくということを計画しております。家庭あんしんセンター的な役割も担えるような… 保育園におきまして特別支援児童の概況ですが、平成１７年度実績で３６名、参考までに本年度は４０名と若干人数は増える傾向にあります。自閉ないし自閉傾向の方がおよそ３分の１、あとは心臓疾患、脳性マヒ、その他いろいろとあります。","id":"exchange-122"},{"speaker":"川西委員","kind":"質問・要望","question":"心にやはり秘めたものといいますか、そういうものを相談したいというんですから、環境がよくなくちゃだめなんです。ですから、ああいうところは全面的に改築しまして、少し抜本的な児童センターのあり方の新しいものを模索していただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-123"},{"speaker":"須藤委員","kind":"質問","question":"１１２ページの高齢福祉費に関連してと、それから時間があれば、１１６ページのシルバーセンター運営費についてお尋ねします。要支援とか介護に該当しない、いわゆる元気なお年寄りというのは８割から８割５分というふうに推定をしているんですが、いかがか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"委員おっしゃるように、大体８割から８割５分です。","id":"exchange-124"},{"speaker":"須藤委員","kind":"質問","question":"年配者でどうのという見方をしているのか、あなたたちの生活をこうしてあげているんだというような考えが見えるような気がしてならないんだけども、そのあたりはいかがか尋ねました。","respondent":"冨岡高齢事業課長","answer":"いつまでも地域の中で元気でお年寄りに生活していただきたいということで、よりボランティア等で活躍していただきたいというような思いも込めまして、生きがいづくり等に取り組んでいる部分もあります。","id":"exchange-125"},{"speaker":"須藤委員","kind":"質問","question":"そういうほうにやらせていって、今の子どもたちが本当に体力低下だと騒がれているんだから、そういうところにやったらどうかな。どういうやり方があるんだということが出てくると思うんですが、そのあたりは筋力トレーニングの数字が少ないというのは、そのあたりの差は何か尋ねました。","respondent":"冨岡高齢事業課長","answer":"筋力トレーニングにつきましては、平成１７年度はモデル実施ということにさせていただきまして、２回分ということで延べ人員が出ております。その前の年にモデル実施をいたしまして、平成１７年度はある程度本格実施という形で始めたものですので…","id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"それはそれとしまして、いわゆる今言った８割から８割５分、元気な年配者の方々が品川区内で生活をされているわけです。快便というような、そういった健康体をキープしますということが必要だろうと思うんだけども、そのあたりはいかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"やはり、からだの筋力を維持していくということが、やはり今後寝たきりにしないための一つの有力な手法というふうに考えております。そういう意味では、このような事業につきましても、引き続き進めていきたいというふうに考えているところです。","id":"exchange-127"},{"speaker":"須藤委員","kind":"質問","question":"ですから、今シルバー大学が非常に人気が高いというか、高齢者の方々がそういうところに行かれていると。そのほうが結果的にはいい結果を生むんじゃないかと思うんですが、そのあたりはいかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"先ほどのご説明のところ、不十分な点がございました。そういう中で、必要があれば、そういう部分について何かいい方策がないかということについては問いかけていきたいというふうに思っているところです。","id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"１１６ページ、シルバーセンターになって、いろんな事業の変遷もあったと思います。そういったときに、その辺の全体的な絵の流れの中でつくっていったほうがいいんじゃないかと思うんですが、そういった考えはいかがか尋ねました。","respondent":"冨岡高齢事業課長","answer":"シルバーセンターにつきましては、時代の流れとともに変わってきております。３６万ということで、今後時代の流れとともに変わっていくものだというふうに認識しておりますので、それに対応する必要性は感じております。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問・要望","question":"あるいは地域センターの一部をどうするのかとか、いわゆる高齢者に対して、年配者に対して元気な状態で毎日が生活できる仕組みづくりをしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-130"},{"speaker":"三上委員","kind":"提案","question":"やはり、一歩そういう考え方に立った指導というものを徹底していただきたいということでお願いしたいんですけれども、お伺いしたいと思います。１回のゲーム、約２０分で終わるというような、ご意見をちょっとお伺いしたいとの意見を述べました。","respondent":"蓼沼高齢福祉課長、諸岡児童課長、冨岡高齢事業課長","answer":"そのほか、今あります法人の春光福祉会のグループホームには、スプリンクラーは設置しています。それから、今後整備されます亀田邸… これの導入につきまして、このゲームの内容につきまして、よく中身を検討させていただきまして。 シルバーセンターのいすの件ですけれども、積極的に対応するように職員と人材センター等を問わず、指示をしています。","id":"exchange-131"},{"speaker":"三上委員","kind":"質問・要望","question":"水道管直結ということもあるわけですから、それは国の制度にまでさせていった品川区であるわけですから、そういったことを活用するということ。そういったことで、ぜひお願いしたいと思うんですけれども、いかがでしょう。","respondent":"冨岡高齢事業課長、蓼沼高齢福祉課長","answer":"具体的な場所等をお伺いした上で、よく対応します。 消防設備と安全対策については、さまざまな制度の活用を含めて十分配慮していきたいというふうに考えてあります。","id":"exchange-132"},{"speaker":"沢田委員","kind":"質問","question":"成果報告書の１１７ページ、児童福祉費に関連してお尋ねいたします。それから、本来の職員の定数と、財政効果はどうなっているのかについて質問したいと思います。","respondent":"小林保育課長","answer":"保育士は５６３名、非常勤は３９４名、それと各種事業の派遣職員等が８７名という構成になっております。それで、事業を行っていく上での人材の活用ですが、基本的には各事業を行っていくのに十分な人員構成ができているというふうに考えております。","id":"exchange-133"},{"speaker":"沢田委員","kind":"意見","question":"十分な人員構成、私が聞いたのは、保育園職員が何名かということと、それから、非常勤等に置きかえたことによって財政効果は、昨日何か６億円の財政効果があったと言ったけど、保育の分野ではどれぐらいの財政効果があったと判断しているのか、平成１７年度は、それを聞いていますとの意見を述べまし…","respondent":"小林保育課長","answer":"定数を保育士で見ますと、定数は直近のものですと、５７１人というふうに考えております。逆に非常勤職員総体、派遣職員総体を全部正規職員でやったとしたらという仮定かと思いますが、それについては試算しておりません。","id":"exchange-134"},{"speaker":"沢田委員","kind":"意見","question":"５６３名の保育士と３９４人と８７人の非常勤、半々まではいかないけど、それで果たしてうまくいっているのかなというのが率直な疑問なんですね。そこらについての考え方をお尋ねしたいと思いますとの意見を述べました。","respondent":"小林保育課長","answer":"常に向上させていきたいというふうに日々努力しておりますが、現段階でうまくいっていないという印象は、実例も含めて感じておりません。１名の経験豊かな職員がいたときに、そういう思いで現場の職員は頑張っている、そういうふうに認識をしております。","id":"exchange-135"},{"speaker":"沢田委員","kind":"質問・要望","question":"もう少し実態をお尋ねしたいと思うんですが、あるいは新規にそこから募集をしているのかという数がわかれば教えていただきたいということと、わかったら教えてほしいと求めました。","respondent":"小林保育課長","answer":"概ね普通、１５時間の４週×１,２００円前後のケースが多いので、６万円から１０万円ぐらいの間なのかなというふうに思います。例えば平成１７年度の状況でご説明いたしますと、２０名前後の派遣職員の異動があったというふうに考えておりますが、お許しいただきたいと思います。","id":"exchange-136"},{"speaker":"沢田委員","kind":"質問","question":"非常勤の保育士でやると１,５００円ですから、月額１１万２,５００円、いずれも生活保護の基準を大幅に下回っている。雇用保険はどうなっているのかをあわせてお尋ねしたいと思います。","respondent":"小林保育課長","answer":"１０万円ということではなくて、３００万円から４００万円代の報酬、生活保護費と云々という水準ではないかというふうに考えております。もちろん派遣先の雇用の中で対応されているものですが、区統一の制度といたしまして、社会保険等の適用があるというふうに聞いております。","id":"exchange-137"},{"speaker":"沢田委員","kind":"質問・要望","question":"ですから、１年で切っちゃうんです。品川区の職員と負けず劣らず一生懸命働いてやっているんですから、根本からの待遇改善を求めたいと思いますが、いかがでしょう。","respondent":"小林保育課長","answer":"そして、ただ事業の責任からすれば、おのずと非常勤と正規職員とには違いがあるというのは事実だと考えております。８時間ということではなくて、それが単純に委員ご指摘の経費を節減するためにそういう制度をつくったというふうには認識しておりません。","id":"exchange-138"},{"speaker":"沢田委員","kind":"質問","question":"たしか３年前、これが導入されたときに、非常勤の方からこれをやらないでほしいというのがものすごい勢いで出ましたよ。労働条件劣悪なとは言いませんけれども、常勤と比べてかなりの差があるような状況をすることが、地方自治体としてのやるべきことなんか尋ねました。","respondent":"古川児童保健事業部長","answer":"変更したという話も確かにありますけれども、３時間のパート、こう考えています。これからも品川区の保育の中では、２時間、３時間でご近所の方々に大いに品川区の保育園の保育行政を担っていただきたいと、こう思ってあります。","id":"exchange-139"},{"speaker":"沢田委員","kind":"質問・要望","question":"あるいは今日の保育園の状況はどうなのかということが聞けないということが最大の親からの不安の声として出されています。これもパッチワーク保育と言っていますけれども、こういう不安定雇用をやった結果だということを示して、私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-140"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと細かい数字で申しわけないと思うんですけれども、決算の数字ですから、確認をさせてください。その方たちと地域がどういうふうに連携というか、コミュニティをつくっていくのかという、その辺をお考えになっていらしたら聞かせてください。","respondent":"原国保年金課長、日下部企画財政課長、小林保育課長、蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"これにつきまして、単価が７万円でございまして、掛けていただくと。実績を当然平成１７年度については計上していますので… 実は整理の期間が出納閉鎖の５月末ではなくて、３月３１日現在で、こちらの支出済額が計上されていると。次のもう１点の… 定員の弾力化ということで、年度当初１５％の範囲内等で調整できることになっておりますので、それを活用して調整を行っております。 二葉一丁目に開設予定のものだと思いますが、まず基本的に介護つき有料老人ホームということで…","id":"exchange-141"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"平成１７年度の決算書ですから、４万何がしかというのは１６年度のお金で、１７年度の決算額としては三千九百何万だという。いろいろ支援していっていただきたいなと思うので、まだあと２年ぐらいありますから、また機会があったら聞きます。","respondent":"冨岡高齢事業課長","answer":"後期高齢者の会計ですけれども、老健会計は清算の部分がありますので、２年ほど残ります。それから、新たに特別会計をまたつくりまして、保険料は区のほうで徴収いたしますので、それに対応するようになっております。","id":"exchange-142"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、老健会計というのはなくなって、後期高齢者医療会計と呼ぶのかどうかわかりませんけれども、新しい特別会計になると。じゃあ、７４歳までの人たちはどこで対応してくるのかなと、そういうここが変わりますよというのをちょっとわかりやすく説明をお願いします。","respondent":"冨岡高齢事業課長","answer":"その年が来年の１０月に、１９３７年の９月３０日までに生まれた方が７５歳になりましたら、それで一応完了するです。先ほど申し上げました平成２０年の４月にはその方たちがもう７５歳になっておいでになりますので、移行していくと、こういうことです。","id":"exchange-143"},{"speaker":"林（宏）委員","kind":"意見","question":"７５歳以上の方はこういうシステムの中で医療を受けていく。じゃあ、今、いわゆる老健の対象になっている方々はどこでどういう仕組みの中で品川区は医療制度を組み込んでいくのかなというのを聞かせてくださいとの意見を述べました。","respondent":"原国保年金課長","answer":"今、高齢事業課長が申し上げましたように、従来は７０歳から老人医療でございましたけれども、この５年間で老人医療の対象年齢を上げております。そうした結果、その方々については、国保加入者であれば７４歳までの方は国保加入という形になってあります。","id":"exchange-144"},{"speaker":"林（宏）委員","kind":"意見","question":"だから、わざわざ後期とつけるのは、現在は７５というラインがあるよというんでしょうけれども、これから先は、僕は要らないような気がするんです。これは広域連合でやることで、品川だけつけないとかはないんでしょうけど、考えだけ聞かせてくださいとの意見を述べました。","respondent":"原国保年金課長","answer":"前期につきましては、６５歳から７４歳までを前期高齢者ということで位置づけております。その方は国保です。","id":"exchange-145"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/754385?Template=document&Id=1264#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":119386,"voices":339}}]);
